@Override
    public void tick() {
        this.witch.setTarget(null);
        LivingEntity trader = this.witch.getTrader();
        if (--this.progress > 0) {
            this.witch.getNavigation().stop();
            if (trader != null && this.witch.distanceTo(trader) <= 16.0F) {
                this.witch.getLookControl().setLookAt(trader);
            }
        }
        if (this.progress <= 0) {
            Vec3 vec3 = trader != null ? trader.position() : this.witch.position();
            if (!this.witch.level.isClientSide) {
                if (this.witch.level.getServer() != null) {
                    float luck = 0.0F;
                    if (this.witch.getMainHandItem().is(ModTags.Items.WITCH_BETTER_CURRENCY)){
                        luck = 1.0F;
                    }
                    LootTable loottable = this.witch.level.getServer().getLootData().getLootTable(ModLootTables.WITCH_BARTER);
                    if (this.witch instanceof WarlockServant){
                        loottable = this.witch.level.getServer().getLootData().getLootTable(ModLootTables.WARLOCK_BARTER);
                    } else if (this.witch instanceof HereticServant){
                        loottable = this.witch.level.getServer().getLootData().getLootTable(ModLootTables.HERETIC_BARTER);
                    } else if (this.witch instanceof ReprobateServant){
                        loottable = this.witch.level.getServer().getLootData().getLootTable(ModLootTables.REPROBATE_BARTER);
                    }
                    List<ItemStack> list = loottable.getRandomItems((new LootParams.Builder((ServerLevel) this.witch.level)).withParameter(LootContextParams.THIS_ENTITY, this.witch).withParameter(LootContextParams.ORIGIN, this.witch.position()).withLuck(luck).create(LootContextParamSets.GIFT));
                    for(ItemStack itemstack : list) {
                        BehaviorUtils.throwItem(this.witch, itemstack, vec3.add(0.0D, 1.0D, 0.0D));
                    }
                }
            }
            this.clearTrade();
        }

        if (this.witch.hurtTime != 0){
            if (this.witch.getItemInHand(InteractionHand.MAIN_HAND).is(ModTags.Items.WITCH_CURRENCY)) {
                this.witch.spawnAtLocation(this.witch.getItemInHand(InteractionHand.MAIN_HAND));
                this.clearTrade();
            }
        }
    }

@Nullable
    public static LivingEntity getOwner(Entity owned) {
        if (owned == null) {
            return null;
        }
        if (owned instanceof IOwned owned1) {
            return owned1.getTrueOwner();
        } else if (owned instanceof OwnableEntity ownable) {
            return ownable.getOwner();
        } else if (owned instanceof Projectile projectile && projectile.getOwner() instanceof LivingEntity living) {
            if (living instanceof IOwned owned1) {
                return owned1.getTrueOwner();
            } else if (living instanceof OwnableEntity ownable) {
                return ownable.getOwner();
            } else {
                return living;
            }
        }
        return null;
    }

public static boolean notTargetingAlly(Entity attacker, Entity defender) {
        if (getTarget(attacker) == defender) {
            return false;
        } else if (getTarget(attacker) == getOwner(defender)) {
            return false;
        } else return !areAllies(defender, getTarget(attacker));
    }

default boolean shouldIgnoreDamage(DamageSource damageSource) {
        if (!damageSource.is(DamageTypeTags.BYPASSES_INVULNERABILITY) && !ServerConfigs.CAN_ATTACK_OWN_SUMMONS.get() && damageSource.getEntity() != null) {
            return DamageSources.isFriendlyFireBetween(damageSource.getEntity(), (Entity) this);
        }
        return false;
    }

default boolean isAlliedHelper(Entity entity) {
        var owner = getSummoner();
        if (owner == null) {
            return false;
        }
        if (entity instanceof IMagicSummon magicSummon) {
            var otherOwner = magicSummon.getSummoner();
            return otherOwner != null && (owner == otherOwner || otherOwner.isAlliedTo(otherOwner));
        } else if (entity instanceof OwnableEntity tamableAnimal) {
            var otherOwner = tamableAnimal.getOwner();
            return otherOwner != null && (owner == otherOwner || otherOwner.isAlliedTo(otherOwner));
        }
        return false;
    }

default void onDeathHelper() {
        if (this instanceof LivingEntity entity) {
            Level level = entity.level;
            var deathMessage = entity.getCombatTracker().getDeathMessage();

            if (!level.isClientSide && level.getGameRules().getBoolean(GameRules.RULE_SHOWDEATHMESSAGES) && getSummoner() instanceof ServerPlayer player) {
                player.sendSystemMessage(deathMessage);
            }
        }
    }

default void onRemovedHelper(Entity entity) {
        if (entity.level.isClientSide) {
            return;
        }
        var reason = entity.getRemovalReason();
        if (reason == null || reason == Entity.RemovalReason.UNLOADED_TO_CHUNK) {
            // seems to cause undefined behavior, not entirely sure why. disabling for now, as im not sure what this was accomplishing anyways - summons are not persistent by default
            // Force unloaded summons to die
//            ((EntityAccessor) entity).setRemovalReason(Entity.RemovalReason.DISCARDED);
        }
        if (reason == Entity.RemovalReason.DISCARDED) {
            if (this.getSummoner() instanceof ServerPlayer player) {
                player.sendSystemMessage(Component.translatable("ui.irons_spellbooks.summon_despawn_message", ((Entity) this).getDisplayName()));
            }
        }
        if (reason != null && reason.shouldDestroy()) {
            SummonManager.removeSummon(entity);
            SummonManager.stopTrackingExpiration(entity);
        }
    }

public boolean canUse() {
        if (!(this.owner.get() instanceof LivingEntity owner)) {
            return false;
        } else {
            if (--intervalToCheck <= 0) {
                var entities = owner.level.getEntitiesOfClass(Mob.class, owner.getBoundingBox().inflate(16, 8, 16), potentionalAggressor -> potentionalAggressor.getTarget() != null &&
                        (potentionalAggressor.getTarget().getUUID().equals(owner.getUUID())
                                || (potentionalAggressor.getTarget() instanceof IMagicSummon summon
                                && summon.getSummoner() != null && summon.getSummoner().getUUID().equals(owner.getUUID())))
                        && Utils.hasLineOfSight(mob.level, mob.getEyePosition(), potentionalAggressor.getEyePosition(), false)
                );
                if (entities.isEmpty()) {
                    currentIntensity = Math.max(0, currentIntensity - 10);
                    return false;
                } else {
                    mob.setTarget(entities.stream().min(Comparator.comparingDouble(o -> o.distanceToSqr(owner))).orElse(entities.getFirst()));
                    return true;
                }
            } else {
                int i = owner.getLastHurtByMobTimestamp();
                int tick = owner.tickCount;
                int combatIntervalModifier = Math.clamp((tick - i) / 5, 0, 200);
                int intensityModifier = maxIntensity - currentIntensity;
                intervalToCheck = 20 + combatIntervalModifier + intensityModifier;
            }
        }
        return false;
    }

public boolean canUse() {
        if (!(ownerGetter.get() instanceof Mob owner)) {
            return false;
