public void start() {
        this.timeToRecalcPath = 0;
        this.oldWaterCost = this.crow.getPathfindingMalus(BlockPathTypes.WATER);
        this.crow.setPathfindingMalus(BlockPathTypes.WATER, 0.0F);
        clockwise = crow.getRandom().nextBoolean();
        yLevel = crow.getRandom().nextInt(1);
        circlingTime = 0;
        maxCircleTime = 20 + crow.getRandom().nextInt(100);
        circleDistance = 1F + crow.getRandom().nextFloat() * 2F;
    }

public void tick() {
        this.crow.getLookControl().setLookAt(this.owner, 10.0F, (float) this.crow.getMaxHeadXRot());
        if (!this.crow.isLeashed() && !this.crow.isPassenger()) {
            double dist = this.crow.distanceToSqr(this.owner);
            if (--this.timeToRecalcPath <= 0) {
                this.timeToRecalcPath = 10;
                if (dist >= 144.0D && !crow.aiItemFlag) {
                    crow.setFlying(true);
                    crow.getMoveControl().setWantedPosition(owner.getX(), owner.getY() + owner.getEyeHeight() + 0.2F, owner.getZ(), 1F);
                    this.tryToTeleportNearEntity();
                    circlingTime = 0;
                }
            }

            if (!crow.aiItemFlag) {
                if (this.crow.isFlying()) {
                    circlingTime++;
                }
                if(circlingTime > maxCircleTime && crow.getRidingCrows(owner) < 2){
                    crow.getMoveControl().setWantedPosition(owner.getX(), owner.getY() + owner.getEyeHeight() + 0.2F, owner.getZ(), 0.7F);
                    if(crow.distanceTo(owner) < 2){
                        crow.startRiding(owner, true);
                        if (!crow.level().isClientSide) {
                            AlexsMobs.sendMSGToAll(new MessageCrowMountPlayer(crow.getId(), owner.getId()));
                        }
                    }
                }else{
                    Vec3 circlePos = getVultureCirclePos(owner.position());
                    if (circlePos == null) {
                        circlePos = owner.position();
                    }
                    crow.setFlying(true);
                    crow.getMoveControl().setWantedPosition(circlePos.x(), circlePos.y() + owner.getEyeHeight() + 0.2F, circlePos.z(), 0.7F);

                }

            }
        }
    }

public boolean canUse() {
        LivingEntity lvt_1_1_ = this.tameable.getOwner();
        if (lvt_1_1_ == null) {
            return false;
        } else if (lvt_1_1_.isSpectator()) {
            return false;
        } else if (!((IFollower)this.tameable).shouldFollow() || isInCombat()) {
            return false;
        } else if (this.tameable.distanceToSqr(lvt_1_1_) < (double) (this.minDist * this.minDist)) {
            return false;
        } else if (this.tameable.getTarget() != null && this.tameable.getTarget().isAlive()) {
            return false;
        } else {
            this.owner = lvt_1_1_;
            return true;
        }
    }

public boolean canContinueToUse() {
        if (this.tameable.getNavigation().isDone() || isInCombat()) {
            return false;
        } else if (!((IFollower)this.tameable).shouldFollow()) {
            return false;
        } else if (this.tameable.getTarget() != null && this.tameable.getTarget().isAlive()) {
            return false;
        } else {
            return this.tameable.distanceToSqr(this.owner) > (double) (this.maxDist * this.maxDist);
        }
    }

private boolean isInCombat() {
        Entity owner = tameable.getOwner();
        if(owner != null){
            return tameable.distanceTo(owner) < 30 && tameable.getTarget() != null && tameable.getTarget().isAlive();
        }
        return false;
    }

private boolean isTeleportFriendlyBlock(BlockPos pos) {
        BlockPathTypes blockPathType = WalkNodeEvaluator.getBlockPathTypeStatic(this.world, pos.mutable());
        if (world.getFluidState(pos).is(FluidTags.WATER) || !world.getFluidState(pos).is(FluidTags.WATER) && world.getFluidState(pos.below()).is(FluidTags.WATER)) {
            return true;
        }
        if (blockPathType != BlockPathTypes.WALKABLE || avoidsLand()) {
            return false;
        } else {
            BlockState lvt_3_1_ = this.world.getBlockState(pos.below());
            if (!this.teleportToLeaves && lvt_3_1_.getBlock() instanceof LeavesBlock) {
                return false;
            } else {
