public void start() {
            this.windup = MathHelper.secondsToTicks(1) + this.charger.getRandom().nextInt(MathHelper.secondsToTicks(1));
            this.charger.level.broadcastEntityEvent(this.charger, (byte)58);
            BlockPos blockpos = this.charger.blockPosition();
            if (this.chargePos != null) {
                this.ramDirection = (new Vec3((double) blockpos.getX() - this.chargePos.x(), 0.0D, (double) blockpos.getZ() - this.chargePos.z())).normalize();
            }
        }

@Override
        public void tick() {
            this.charger.getLookControl().setLookAt(this.chargePos.x(), this.chargePos.y() - 1, this.chargePos.z(), 10.0F, this.charger.getMaxHeadXRot());

            --this.windup;
            if (this.windup == 0){
                PathNavigation pathnavigation = this.charger.getNavigation();
                Path path = pathnavigation.createPath(BlockPos.containing(this.chargePos), 0);
                if (path != null && path.canReach()){
                    pathnavigation.moveTo(path, this.speed);
                } else {
                    pathnavigation.moveTo(this.chargePos.x(), this.chargePos.y(), this.chargePos.z(), this.speed);
                }
            }
            if (this.windup <= 0) {
                List<LivingEntity> list = this.charger.level.getNearbyEntities(LivingEntity.class, RAM_TARGET_CONDITIONS, this.charger, this.charger.getBoundingBox());
                list.removeIf(livingEntity -> MobUtil.areAllies(this.charger, livingEntity));
                if (!list.isEmpty()) {
                    LivingEntity livingentity = list.get(0);
                    DamageSource damageSource = this.charger instanceof IOwned owned && owned.getTrueOwner() != null ? ModDamageSource.summonAttack(this.charger, owned.getTrueOwner()) : this.charger.damageSources().mobAttack(this.charger);
                    livingentity.hurt(damageSource, (float)this.charger.getAttributeValue(Attributes.ATTACK_DAMAGE));
                    int i = this.charger.hasEffect(MobEffects.MOVEMENT_SPEED) ? this.charger.getEffect(MobEffects.MOVEMENT_SPEED).getAmplifier() + 1 : 0;
                    int j = this.charger.hasEffect(MobEffects.MOVEMENT_SLOWDOWN) ? this.charger.getEffect(MobEffects.MOVEMENT_SLOWDOWN).getAmplifier() + 1 : 0;
                    float f = 0.25F * (float)(i - j);
                    float f1 = Mth.clamp(this.charger.getSpeed() * 1.65F, 0.2F, 3.0F) + f;
                    float f2 = livingentity.isDamageSourceBlocked(damageSource) ? 0.5F : 1.0F;
                    if (this.ramDirection != null) {
                        livingentity.knockback((double) (f2 * f1) * this.getKnockbackForce.applyAsDouble(this.charger), this.ramDirection.x(), this.ramDirection.z());
                    }
                    this.stop();
                    this.charger.level.playSound((Player)null, this.charger, this.getImpactSound.apply(this.charger), SoundSource.NEUTRAL, 1.0F, 1.0F);
                } else if (this.hasRammedHornBreakingBlock()) {
                    this.charger.level.playSound((Player)null, this.charger, this.getImpactSound.apply(this.charger), SoundSource.NEUTRAL, 1.0F, 1.0F);
                    boolean flag = this.charger instanceof TwilightGoat goat && goat.dropHorn();
                    if (flag) {
                        this.charger.level.playSound((Player)null, this.charger, this.getHornBreakSound.apply(this.charger), SoundSource.NEUTRAL, 1.0F, 1.0F);
                    }

                    this.stop();
                } else {
                    boolean flag1 = this.chargePos == null || this.chargePos.closerThan(this.charger.position(), 0.25D);
                    if (flag1) {
                        this.stop();
                    }
                }
            } else {
                if (this.charger instanceof ICharger chargeMob) {
                    chargeMob.setCharging(true);
                }
            }
        }

@Override
        public void stop() {
            this.charger.level.broadcastEntityEvent(this.charger, (byte)59);
            this.charger.getNavigation().stop();
            this.windup = 0;
            this.chargeTarget = null;
            this.coolDown = this.charger.tickCount + this.coolDownTotal;
            if (this.charger instanceof ICharger chargeMob) {
                chargeMob.setCharging(false);
            }
        }

public SpellExplosion(Level level, Entity source, DamageSource damageSource, double x, double y, double z, float radius, float damage){
        float f2 = radius;
        if (SpellConfig.SpellExplosionDouble.get()) {
            f2 *= 2.0F;
        }
        Vec3 vec3 = new Vec3(x, y, z);
        if (!ExplosionUtil.enterExplosion()) {
            return;
        }
        try {
            for (Entity entity : explosionRangeEntities(level, source, x, y, z, radius)) {
                double d12 = Math.sqrt(entity.distanceToSqr(vec3)) / (double) f2;
                if (d12 <= 1.0D) {
                    double d5 = entity.getX() - x;
                    double d7 = entity.getEyeY() - y;
                    double d9 = entity.getZ() - z;
                    double d13 = Math.sqrt(d5 * d5 + d7 * d7 + d9 * d9);
                    if (d13 != 0.0D) {
                        d5 /= d13;
                        d7 /= d13;
                        d9 /= d13;
                        double d14 = (double) getSeenPercent(vec3, entity);
                        double d10 = (1.0D - d12) * d14;
                        float actualDamage = damage == 0 ? (float) ((int) ((d10 * d10 + d10) / 2.0D * 7.0D * (double) f2 + 1.0D)) : damage;
                        Entity trueSource = null;
                        boolean hurt = true;
                        if (entity instanceof ItemEntity) {
                            hurt = false;
                        } else if (damageSource.is(DamageTypeTags.IS_EXPLOSION) && entity.ignoreExplosion()){
                            hurt = false;
                        } else if (damageSource.getEntity() != null){
                            trueSource = damageSource.getEntity();
                        } else if (source != null){
                            trueSource = source;
                        }
                        if (trueSource != null) {
                            if (MobUtil.areAllies(trueSource, entity) || entity == trueSource){
                                hurt = false;
                            }
                        }
                        if (hurt) {
                            this.explodeHurt(entity, damageSource, d5, d7, d9, d10, actualDamage);
                        }
                    }
                }
            }
        } finally {
            ExplosionUtil.exitExplosion();
        }
    }

public void explodeHurt(Entity target, DamageSource damageSource, double x, double y, double z, double seen, float actualDamage){
        if (target.hurt(damageSource, actualDamage)) {
            this.postHurtEffect(target, damageSource, actualDamage);
        }
        double d11 = seen;
        if (target instanceof LivingEntity) {
            d11 = ProtectionEnchantment.getExplosionKnockbackAfterDampener((LivingEntity) target, seen);
        }
        if (damageSource.is(DamageTypeTags.WITCH_RESISTANT_TO)){
            if (target instanceof AbstractCyclone cyclone && (cyclone.getTrueOwner() == null || damageSource.getEntity() == null || !MobUtil.areAllies(damageSource.getEntity(), cyclone.getTrueOwner()))){
                cyclone.trueRemove();
            }
        }

        if (target instanceof LivingEntity) {
            MobUtil.push(target, x * d11, y * d11, z * d11);
        }
    }

default boolean isGuardingArea(){
        if (this instanceof Entity entity) {
            if (entity.level.dimension() != this.getBoundLevel()){
                return false;
            }
        }
        return this.getBoundPos() != null;
    }

default boolean isWithinGuard(BlockPos p_21445_){
        if (this.getBoundPos() == null) {
            return true;
        } else {
            return this.getBoundPos().distSqr(p_21445_) < Mth.square(GUARDING_RANGE);
        }
    }

@Nullable
    default GlobalPos getCurrentWaypoint() {
        List<GlobalPos> route = this.getPatrolRoute();
        if (route.isEmpty()) {
            return null;
        }
        return route.get(Mth.clamp(this.getPatrolIndex(), 0, route.size() - 1));
    }

default void advancePatrol() {
        List<GlobalPos> route = this.getPatrolRoute();
        if (route.isEmpty()) {
            return;
        }
        this.setPatrolIndex((this.getPatrolIndex() + 1) % route.size());
        this.setBoundPos(route.get(this.getPatrolIndex()).pos());
    }

default void clearPatrol() {
        this.setPatrolRoute(List.of());
        this.setPatrolIndex(0);
        this.setBoundPos(null);
    }

default void copyStance(IServant servant) {
        if (servant.isFollowing()) {
            this.setFollowing();
        } else if (servant.isWandering()) {
            this.setWandering();
        } else if (servant.isGuardingArea()) {
            this.setBoundPos(servant.getBoundPos());
            this.setBoundDim(servant.getBoundLevel());
        }
    }

default boolean isFollowing(){
        return !this.isWandering() && !this.isStaying() && !this.isGuardingArea() && this.canFollow();
    }

default void spawnUpgraded(){
        if (this instanceof Mob mob) {
            LivingEntity owner = this.getTrueOwner();
            if (MobsConfig.ServantOwnedServantPlayerBenefit.get()) {
                owner = this.getMasterOwner();
            }
            if (ServantUtil.isNecroHeal(mob)) {
                this.setUpgraded(CuriosFinder.hasUndeadCape(owner) || this.getTrueOwner() instanceof AbstractNecromancer);
            } else if (ServantUtil.isWildHeal(mob)) {
                this.setUpgraded(CuriosFinder.hasWildRobe(owner));
            } else if (ServantUtil.isFrostHeal(mob)) {
                this.setUpgraded(CuriosFinder.hasFrostRobes(owner));
            } else if (ServantUtil.isAbyssHeal(mob)) {
                this.setUpgraded(CuriosFinder.hasAbyssRobes(owner));
            } else if (ServantUtil.isNetherHeal(mob)) {
                this.setUpgraded(CuriosFinder.hasNetherRobe(owner));
            } else if (ServantUtil.isWindHeal(mob)) {
                this.setUpgraded(CuriosFinder.hasWindRobes(owner));
            } else if (ServantUtil.isVoidHeal(mob)) {
                this.setUpgraded(CuriosFinder.hasVoidRobe(owner));
            } else if (ServantUtil.isGeoHeal(mob)) {
                this.setUpgraded(CuriosFinder.hasGeoRobe(owner));
            }
        }
    }

default void updateMoveMode(Player player){
        if (this instanceof LivingEntity living) {
            boolean flag = false;
            if (!this.isWandering() && !this.isStaying() && !this.isGuardingArea() && this.canWander()) {
                this.clearPatrol();
                this.setBoundPos(null);
                this.setWandering(true);
                this.setStaying(false);
                player.displayClientMessage(Component.translatable("info.goety.servant.wander", living.getDisplayName()), true);
                flag = true;
            } else if (!this.isStaying() && !this.isGuardingArea() && this.canStay()) {
                this.clearPatrol();
                this.setBoundPos(null);
                this.setWandering(false);
                this.setStaying(true);
                player.displayClientMessage(Component.translatable("info.goety.servant.staying", living.getDisplayName()), true);
                flag = true;
            } else if (!this.isGuardingArea() && this.canGuardArea()) {
                this.clearPatrol();
                this.setBoundPos(living.blockPosition());
                this.setWandering(false);
                this.setStaying(false);
                player.displayClientMessage(Component.translatable("info.goety.servant.guard", living.getDisplayName()), true);
                flag = true;
            } else if (this.canFollow()) {
                this.clearPatrol();
                this.setBoundPos(null);
                this.setWandering(false);
                this.setStaying(false);
                player.displayClientMessage(Component.translatable("info.goety.servant.follow", living.getDisplayName()), true);
                flag = true;
            }
            if (flag){
                living.playSound(SoundEvents.ZOMBIE_VILLAGER_CONVERTED, 1.0f, 1.0f);
            }
        }
    }

default void setCommandPos(BlockPos blockPos, boolean removeEntity) {
        if (removeEntity) {
            this.setCommandPosEntity(null);
        }
        this.setCommandPos(blockPos);
        this.setCommandTick(MathHelper.secondsToTicks(10));
    }

default boolean isAbleToRide(LivingEntity livingEntity) {
        if (!(this instanceof PlayerRideable)
                && !(this instanceof IGolem)
                && (livingEntity instanceof PlayerRideable || livingEntity.getType().is(ModTags.EntityTypes.SERVANT_RIDEABLE))
                && livingEntity.getFirstPassenger() == null){
            if (livingEntity instanceof AbstractHorse horse){
                return horse.isTamed();
            } else if (MobUtil.getOwner(livingEntity) != null){
                return MobUtil.getOwner(livingEntity) == this.getTrueOwner();
            }
        }
        if (livingEntity instanceof IServant servant && this instanceof LivingEntity rider){
            return servant.canBeRidden(rider);
        }
        return false;
    }

default void servantTick(){
        if (this instanceof Mob owned){
            this.stayingMode();
            if (this.getKillChance() > 0){
                this.setKillChance(this.getKillChance() - 1);
            }
            if (owned.isAlive()) {
                this.chunkLoad();
            }
            this.commandMode();
            if (this.isWandering() || this.isGuardingArea()){
                if (this.isStaying()) {
                    this.setStaying(false);
                }
            }
            if (this.isGuardingArea()){
                if (!this.isPrioritizing()) {
                    if (owned.getTarget() != null){
                        if (owned.getTarget() != this.getPriorityTarget() && owned.getTarget().distanceToSqr(this.vec3BoundPos()) > Mth.square(GUARDING_RANGE * 2)){
                            owned.setTarget(null);
                            if (!this.isCommanded()){
                                owned.getNavigation().moveTo(this.getBoundPos().getX(), this.getBoundPos().getY(), this.getBoundPos().getZ(), 1.0F);
                            }
                        }
                    } else if (!this.isCommanded() && !this.isPatrolling()) {
                        boolean noSeat = true;
                        if (ISeat.canBePickedUp(owned) && !(this.getTrueOwner() instanceof IServant)) {
                            BlockState blockState = owned.level.getBlockState(this.getBoundPos());
                            if (blockState.getBlock() instanceof ISeat seat) {
                                if (!ISeat.isSeatOccupied(owned.level, this.getBoundPos())) {
                                    if (!owned.isPassenger() && owned.getTarget() == null) {
                                        noSeat = false;
                                        AABB aabb = new AABB(this.getBoundPos());
                                        if (owned.getBoundingBox().inflate(0.5F).intersects(aabb)) {
                                            BlockPos blockPos = this.getBoundPos();
                                            if (blockState.hasProperty(BlockStateProperties.DOUBLE_BLOCK_HALF)) {
                                                if (blockState.getValue(BlockStateProperties.DOUBLE_BLOCK_HALF) == DoubleBlockHalf.UPPER) {
                                                    blockPos = this.getBoundPos().below();
                                                }
                                            }
                                            seat.placeSeat(owned.level, blockPos, owned);
                                        } else {
                                            owned.getNavigation().moveTo(this.getBoundPos().getX(), this.getBoundPos().getY(), this.getBoundPos().getZ(), this.getCommandSpeed());
                                        }
                                    }
                                }
                            } else {
                                if (owned.getVehicle() instanceof SeatEntity) {
                                    owned.stopRiding();
                                }
                            }
                        }
                        if (noSeat) {
                            if (owned.distanceToSqr(this.vec3BoundPos()) > Mth.square(GUARDING_RANGE)) {
                                owned.getNavigation().moveTo(this.getBoundPos().getX(), this.getBoundPos().getY(), this.getBoundPos().getZ(), 1.0F);
                            }
                        }
                    }
                } else if (!this.isCommanded() && this.getPriorityPos() != null && owned.getTarget() == null) {
                    owned.getNavigation().moveTo(this.getPriorityPos().getX(), this.getPriorityPos().getY(), this.getPriorityPos().getZ(), 1.0F);
                }
            }
            if (this.isPrioritizing() && (owned.getTarget() == null || owned.getTarget().isDeadOrDying())) {
                this.setPriorityTime(this.getPriorityTime() - 1);
            }
            if (this.getPriorityTarget() != null) {
                if (!this.getPriorityTarget().isAlive()) {
                    this.setPriorityTarget(null);
                }
            }
            if (this.getNoHealTime() <= 0){
                this.healServant();
            } else {
                this.setNoHealTime(this.getNoHealTime() - 1);
            }
            this.burnServant(owned);
            this.ownedByServantTick();
        }
    }

default void ownedByServantTick() {
        if (this instanceof Mob mob) {
            if (this.getTrueOwner() instanceof IServant owner) {
                if (owner.isGuardingArea()) {
                    if (!this.isGuardingArea()) {
                        if (owner.getBoundPos() != null && owner.getBoundLevel() == mob.level.dimension()) {
                            this.setBoundPos(owner.getBoundPos());
                        }
                    }
                } else {
                    this.setFollowing();
                }
            }
        }
    }

default void healServant(){
        if (this instanceof LivingEntity self) {
            LivingEntity owner = this.getTrueOwner();
            if (MobsConfig.ServantOwnedServantPlayerBenefit.get()) {
                owner = this.getMasterOwner();
            }
            if (owner != null) {
                boolean crown = (ServantUtil.isFrostHeal(self) && CuriosFinder.hasFrostCrown(owner))
                        || (ServantUtil.isWindHeal(self) && CuriosFinder.hasWindCrown(owner))
                        || (ServantUtil.isStormHeal(self) && CuriosFinder.hasStormCrown(owner))
                        || (ServantUtil.isWildHeal(self) && CuriosFinder.hasWildCrown(owner))
                        || (ServantUtil.isGeoHeal(self) && CuriosFinder.hasAmethystNecklace(owner))
                        || (ServantUtil.isNetherHeal(self) && CuriosFinder.hasNetherCrown(owner))
                        || (ServantUtil.isAbyssHeal(self) && CuriosFinder.hasAbyssCrown(owner))
                        || (ServantUtil.isVoidHeal(self) && CuriosFinder.hasVoidCrown(owner))
                        || (ServantUtil.isNecroHeal(self) && CuriosFinder.hasUndeadCrown(owner));
                if (!crown) {
                    if (this.getLifespan() > 0) {
                        this.setHasLifespan(true);
                    }
                } else {
                    this.setHasLifespan(false);
                }
                if (!self.level.isClientSide) {
                    if (!this.hasLifespan() || this.getLifespan() > 20) {
                        ServantUtil.healServant(owner, self);
                    }
                }
            }
        }
    }

default void commandMode(){
        if (this instanceof Mob owned){
            if (this.isCommanded()){
                if (owned.getNavigation().isStableDestination(this.getCommandPos()) || this.getCommandPosEntity() != null){
                    this.setCommandTick(this.getCommandTick() - 1);
                    if (this.getCommandPosEntity() != null){
                        owned.getNavigation().moveTo(this.getCommandPosEntity(), this.getCommandSpeed());
                    } else {
                        owned.getNavigation().moveTo(this.getCommandPos().getX() + 0.5D, this.getCommandPos().getY(), this.getCommandPos().getZ() + 0.5D, this.getCommandSpeed());
                    }

                    AABB aabb = new AABB(this.getCommandPos());
                    Entity entity = owned.getControlledVehicle() != null ? owned.getControlledVehicle() : owned;
                    if (owned.getNavigation().isStuck() || this.getCommandTick() <= 0){
                        this.setCommandPosEntity(null);
                        this.setCommandPos(null);
                    } else if (entity.getBoundingBox().inflate(0.5F).intersects(aabb)){
                        if (this.getCommandPosEntity() != null &&
                                owned.getBoundingBox().inflate(1.25D).intersects(this.getCommandPosEntity().getBoundingBox())){
                            if (this.isAbleToRide(this.getCommandPosEntity())) {
                                if (owned.startRiding(this.getCommandPosEntity())) {
                                    if (this.getTrueOwner() instanceof Player player){
                                        player.displayClientMessage(Component.translatable("info.goety.servant.dismount"), true);
                                    }
                                }
                            }
                            this.setCommandPosEntity(null);
                        }
                        if (this.isGuardingArea()){
                            this.setBoundPos(this.getCommandPos());
                        }
                        if (owned.level.getBlockState(this.getCommandPos()).getBlock() instanceof ISeat seat) {
                            BlockState blockState = owned.level.getBlockState(this.getCommandPos());
                            if (!owned.isPassenger() && ISeat.canBePickedUp(owned) && !ISeat.isSeatOccupied(owned.level, this.getCommandPos())) {
                                BlockPos blockPos = this.getCommandPos();
                                if (blockState.hasProperty(BlockStateProperties.DOUBLE_BLOCK_HALF)) {
                                    if (blockState.getValue(BlockStateProperties.DOUBLE_BLOCK_HALF) == DoubleBlockHalf.UPPER) {
                                        blockPos = this.getCommandPos().below();
                                    }
                                }
                                seat.placeSeat(owned.level, blockPos, owned);
                            }
                        }
                        owned.getNavigation().stop();
                        owned.getMoveControl().strafe(0.0F, 0.0F);
                        owned.moveTo(this.getCommandPos(), owned.getYRot(), owned.getXRot());
                        this.setCommandPos(null);
                    }
                } else {
                    this.setCommandPos(null);
                }
            }
        }
    }

default void stayingMode(){
        if (this instanceof Mob owned) {
            AttributeInstance modifiableattributeinstance = owned.getAttribute(Attributes.MOVEMENT_SPEED);
            if (modifiableattributeinstance != null) {
                boolean isRidden = owned.getControllingPassenger() instanceof IServant servant && servant.isStaying();
                if (this.isStaying() || isRidden || this.altStaying()) {
                    if (owned.getNavigation().getPath() != null) {
                        owned.getNavigation().stop();
                    }
                    if (owned.getAttribute(Attributes.MOVEMENT_SPEED) != null) {
                        modifiableattributeinstance.removeModifier(SPEED_MODIFIER);
                        modifiableattributeinstance.addTransientModifier(SPEED_MODIFIER);
                    }
                    this.stayingPosition();
                    if (!isRidden) {
                        if (this.isWandering()) {
                            this.setWandering(false);
                        }
                    }
                } else {
                    if (modifiableattributeinstance.hasModifier(SPEED_MODIFIER)) {
                        modifiableattributeinstance.removeModifier(SPEED_MODIFIER);
                    }
                }
            }
        }
    }

default void readServantData(CompoundTag compound){
        if (compound.contains("Upgraded")) {
            this.setUpgraded(compound.getBoolean("Upgraded"));
        }
        if (compound.contains("wandering")) {
            this.setWandering(compound.getBoolean("wandering"));
        }
        if (compound.contains("staying")) {
            this.setStaying(compound.getBoolean("staying"));
        }
        if (compound.contains("commandPos")){
            this.setCommandPos(NbtUtils.readBlockPos(compound.getCompound("commandPos")));
        }
        if (compound.contains("commandPosEntity")){
            if (EntityFinder.getLivingEntityByUuiD(compound.getUUID("commandPosEntity")) != null) {
                this.setCommandPosEntity(EntityFinder.getLivingEntityByUuiD(compound.getUUID("commandPosEntity")));
            }
        }
        if (compound.contains("boundPos")){
            this.setBoundPos(NbtUtils.readBlockPos(compound.getCompound("boundPos")));
            if (compound.contains("boundDim")){
                this.setBoundDim(compound.getString("boundDim"));
            } else {
                if (this instanceof Entity entity) {
                    this.setBoundDim(entity.level.dimension());
                }
            }
        }
        if (compound.contains("PatrolPath")) {
            this.setPatrolRoute(LIST_CODEC.parse(NbtOps.INSTANCE, compound.get("PatrolPath"))
                    .resultOrPartial(Goety.LOGGER::error)
                    .<List<GlobalPos>>map(ArrayList::new)
                    .orElseGet(ArrayList::new));
        }
        if (compound.contains("PatrolIndex")){
            this.setPatrolIndex(compound.getInt("PatrolIndex"));
        }
        if (compound.contains("noHealTime")){
            this.setNoHealTime(compound.getInt("noHealTime"));
        }
        if (compound.contains("priorityTargetTime")){
            this.setPriorityTime(compound.getInt("priorityTargetTime"));
        }
        if (compound.contains("priorityPos")){
            this.setPriorityPos(NbtUtils.readBlockPos(compound.getCompound("priorityPos")));
        }
    }

default void saveServantData(CompoundTag compound){
        compound.putBoolean("Upgraded", this.isUpgraded());
        compound.putBoolean("wandering", this.isWandering());
        compound.putBoolean("staying", this.isStaying());
        if (this.getCommandPos() != null){
            compound.put("commandPos", NbtUtils.writeBlockPos(this.getCommandPos()));
        }
        if (this.getCommandPosEntity() != null) {
            compound.putUUID("commandPosEntity", this.getCommandPosEntity().getUUID());
        }
        compound.putInt("commandTick", this.getCommandTick());
        if (this.getBoundPos() != null){
            compound.put("boundPos", NbtUtils.writeBlockPos(this.getBoundPos()));
            compound.putString("boundDim", this.getBoundDim());
        }
        if (!this.getPatrolRoute().isEmpty()) {
            LIST_CODEC.encodeStart(NbtOps.INSTANCE, this.getPatrolRoute())
                    .resultOrPartial(Goety.LOGGER::error)
                    .ifPresent(encoded -> compound.put("PatrolPath", encoded));
            compound.putInt("PatrolIndex", this.getPatrolIndex());
        }
        compound.putInt("noHealTime", this.getNoHealTime());
        compound.putInt("priorityTargetTime", this.getPriorityTime());
        if (this.getPriorityPos() != null){
            compound.put("priorityPos", NbtUtils.writeBlockPos(this.getPriorityPos()));
        }
    }

@Override
    public boolean doHurtTarget(Entity entityIn) {
        boolean flag = super.doHurtTarget(entityIn);

        if (!this.level.isClientSide) {
            if (flag) {
                this.playSound(ModSounds.BLACK_BEAST_CLAW.get(), this.getSoundVolume(), this.getVoicePitch());
                if (entityIn instanceof LivingEntity target) {
                    int debuffDuration = MathHelper.secondsToTicks(15);
                    MobEffectInstance doom = new MobEffectInstance(GoetyEffects.DOOM.get(), debuffDuration, 0, false, false);
                    if (!target.hasEffect(GoetyEffects.DOOM.get()) && target.canBeAffected(doom) && !MobUtil.isInSunlightNoRain(this)) {
                        int regenAmp = 2;
                        if (MobsConfig.BlackBeastDayStrength.get()) {
                            if (this.level.dayTime() >= MathHelper.minecraftDayToTicks(50)) {
                                regenAmp += 1;
                            }

                            if (this.level.dayTime() >= MathHelper.minecraftDayToTicks(100)) {
                                regenAmp += 1;
                            }
                        }
                        this.playSound(ModSounds.BLACK_BEAST_ROAR.get(), this.getSoundVolume(), 0.25F);

                        target.addEffect(new MobEffectInstance(GoetyEffects.DOOM.get(), debuffDuration, 0, false, false), this);
                        target.addEffect(new MobEffectInstance(MobEffects.WITHER, debuffDuration, 1, false, false), this);
                        target.addEffect(new MobEffectInstance(GoetyEffects.CURSED.get(), debuffDuration, 0, false, false), this);
                        this.addEffect(new MobEffectInstance(MobEffects.REGENERATION, MathHelper.secondsToTicks(5), regenAmp, false, false), this);
                    }
                }
            }
        }

        return flag;
    }

@Override
