public static boolean illagerAllies(Entity self, Entity target){
        if (target == self) {
            return true;
        } else if (target.getTeam() != null && self.isAlliedTo(target.getTeam())) {
            return true;
        } else if (target instanceof Vex vex && vex.getOwner() != null) {
            return self.isAlliedTo(vex.getOwner());
        } else if (target instanceof Irk irk && irk.getTrueOwner() != null) {
            return self.isAlliedTo(irk.getTrueOwner());
        } else if (target instanceof Tormentor tormentor && tormentor.getOwner() != null) {
            return self.isAlliedTo(tormentor.getOwner());
        } else if (target instanceof LivingEntity livingEntity && livingEntity.getMobType() == MobType.ILLAGER) {
            if (livingEntity instanceof IOwned owned){
                if (owned.getTrueOwner() != null){
                    return self.isAlliedTo(owned.getTrueOwner());
                } else if (!owned.isHostile()){
                    return livingEntity.isAlliedTo(self);
                }
            }
            return self.getTeam() == null && target.getTeam() == null;
        } else {
            return false;
        }
    }

@SubscribeEvent
    public static void LivingEffects(LivingEvent.LivingTickEvent event){
        LivingEntity livingEntity = event.getEntity();
        if (livingEntity instanceof Mob mob && !StunnedEvents.isStunned(mob)){
            if (mob instanceof OwnableEntity ownable && mob.getTarget() != null) {
                if (SEHelper.isAlly(ownable.getOwner(), mob.getTarget())) {
                    mob.setTarget(null);
                }
            }
            if (mob instanceof IOwned && mob.getTarget() != null) {
                if (mob.getTarget().isDeadOrDying() || !EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(mob.getTarget())){
                    mob.setTarget(null);
                }
            }
            if (mob.getTarget() instanceof IOwned owned) {
                if (mob.getType().is(ModTags.EntityTypes.IGNORE_SERVANTS)) {
                    if (owned.getTrueOwner() != null) {
                        if (!owned.getTrueOwner().isDeadOrDying() && mob.canAttack(owned.getTrueOwner()) && EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(owned.getTrueOwner())) {
                            mob.setLastHurtByMob(owned.getTrueOwner());
                            mob.setTarget(owned.getTrueOwner());
                        }
                    }
                }
                if (mob.getTarget() != null && (mob.getTarget().isDeadOrDying() || !EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(mob.getTarget()))) {
                    mob.setTarget(null);
                }
            }
        }
        if (ServantUtil.notServantButOwned(livingEntity)){
            int i = MiscCapHelper.getNoHealTime(livingEntity);
            if (i > 0){
                MiscCapHelper.setNoHealTime(livingEntity, i - 1);
            }
        }
    }

@SubscribeEvent
    public static void TargetEvents(LivingChangeTargetEvent event){
        LivingEntity attacker = event.getEntity();
        LivingEntity target = event.getOriginalTarget();
        if (attacker instanceof Mob mobAttacker && !StunnedEvents.isStunned(mobAttacker)) {
            if (target instanceof Player) {
                if (mobAttacker.getLastHurtByMob() instanceof IOwned owned
                        && owned.getTrueOwner() == target
                        && !(mobAttacker instanceof Apostle)){
                    event.setNewTarget(mobAttacker.getLastHurtByMob());
                }
            }
            if (attacker.getType().is(ModTags.EntityTypes.IGNORE_SERVANTS)) {
                if (target instanceof OwnableEntity ownable) {
                    LivingEntity owner = target instanceof IOwned owned ? owned.getTrueOwner() : ownable.getOwner();
                    if (owner != null && !owner.isDeadOrDying() && attacker.canAttack(owner) && EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(owner)) {
                        attacker.setLastHurtByMob(owner);
                        event.setNewTarget(owner);
                    }
                }
            }
            if (attacker instanceof IOwned owned) {
                if (ServantUtil.nullifyTarget(owned, target)) {
                    if (event.getTargetType() == MOB_TARGET) {
                        event.setNewTarget(null);
                    } else {
                        event.setCanceled(true);
                    }
                }
            }
            if (!(mobAttacker instanceof Enemy)
                    && target instanceof IOwned owned && owned instanceof Enemy && !owned.isHostile()
                    && target instanceof Mob mob && mob.getTarget() != mobAttacker
                    && !(mobAttacker instanceof OwnableEntity ownable && ownable.getOwner() != null && ((ownable.getOwner().getLastHurtByMob() == target) || (ownable.getOwner() instanceof Mob mob1 && mob1.getTarget() == target)))
                    && mobAttacker.getLastHurtByMob() != target){
                if (event.getTargetType() == MOB_TARGET) {
                    event.setNewTarget(null);
                } else {
                    event.setCanceled(true);
                }
            }
        }
    }

