public @NotNull InteractionResult useOn(UseOnContext p_43223_) {
        Level level = p_43223_.getLevel();
        Player player = p_43223_.getPlayer();
        if (!(level instanceof ServerLevel serverLevel)) {
            return InteractionResult.SUCCESS;
        } else {
            ItemStack itemstack = p_43223_.getItemInHand();
            BlockPos blockpos = p_43223_.getClickedPos();
            Direction direction = p_43223_.getClickedFace();
            BlockState blockstate = level.getBlockState(blockpos);
            if (blockstate.is(Blocks.SPAWNER)) {
                BlockEntity blockentity = level.getBlockEntity(blockpos);
                if (blockentity instanceof SpawnerBlockEntity spawnerblockentity) {
                    EntityType<?> entitytype1 = this.getType(itemstack.getTag());
                    spawnerblockentity.setEntityId(entitytype1, level.getRandom());
                    blockentity.setChanged();
                    level.sendBlockUpdated(blockpos, blockstate, blockstate, 3);
                    level.gameEvent(p_43223_.getPlayer(), GameEvent.BLOCK_CHANGE, blockpos);
                    itemstack.shrink(1);
                    return InteractionResult.CONSUME;
                }
            }

            BlockPos blockpos1;
            if (blockstate.getCollisionShape(level, blockpos).isEmpty()) {
                blockpos1 = blockpos;
            } else {
                blockpos1 = blockpos.relative(direction);
            }

            EntityType<?> entitytype = this.getType(itemstack.getTag());
            Entity entity = entitytype.spawn(serverLevel, itemstack, p_43223_.getPlayer(), blockpos1, MobSpawnType.SPAWN_EGG, true, !Objects.equals(blockpos, blockpos1) && direction == Direction.UP);
            if (entity != null) {
                if (player != null && entity instanceof IOwned owned && !owned.isHostile()){
                    if (player.isCrouching()){
                        owned.setTrueOwner(player);
                        if (owned instanceof Mob mob){
                            ForgeEventFactory.onFinalizeSpawn(mob, serverLevel, serverLevel.getCurrentDifficultyAt(mob.blockPosition()), MobSpawnType.SPAWN_EGG, null, itemstack.getTag());
                        }
                    }
                }
                itemstack.shrink(1);
                level.gameEvent(p_43223_.getPlayer(), GameEvent.ENTITY_PLACE, blockpos);
            }

            return InteractionResult.CONSUME;
        }
    }

public @NotNull Optional<Mob> spawnOffspringFromSpawnEgg(@NotNull Player player, @NotNull Mob targetMob, @NotNull EntityType<? extends Mob> entityType, @NotNull ServerLevel serverLevel, @NotNull Vec3 vec3, ItemStack itemStack) {
        if (!this.spawnsEntity(itemStack.getTag(), entityType)) {
            return Optional.empty();
        } else {
            Mob mob;
            if (targetMob instanceof AgeableMob ageableMob) {
                mob = ageableMob.getBreedOffspring(serverLevel, ageableMob);
            } else if (targetMob instanceof AnimalSummon animalSummon) {
                mob = animalSummon.getBreedOffspring(serverLevel, animalSummon);
            } else if (targetMob instanceof AbstractIllagerServant illager) {
                mob = illager.getBreedOffspring(serverLevel, illager);
            } else {
                mob = entityType.create(serverLevel);
            }

            if (mob == null) {
                return Optional.empty();
            } else {
                mob.setBaby(true);
                if (!mob.isBaby()) {
                    return Optional.empty();
                } else {
                    if (mob instanceof IOwned owned && !owned.isHostile()) {
                        if (targetMob instanceof IOwned owned1 && !owned1.isHostile()) {
                            if (owned1.getTrueOwner() != null){
                                owned.setTrueOwner(owned1.getTrueOwner());
                            }
                        }
                    }

                    mob.moveTo(vec3.x(), vec3.y(), vec3.z(), 0.0F, 0.0F);
                    serverLevel.addFreshEntityWithPassengers(mob);
                    if (itemStack.hasCustomHoverName()) {
                        mob.setCustomName(itemStack.getHoverName());
                    }

                    if (!player.getAbilities().instabuild) {
                        itemStack.shrink(1);
                    }

                    return Optional.of(mob);
                }
            }
        }
    }

public InteractionResult mobInteract(Player p_27584_, InteractionHand p_27585_) {
        ItemStack itemstack = p_27584_.getItemInHand(p_27585_);
        if (this.getTrueOwner() != null && p_27584_ == this.getTrueOwner()) {
            if (this.isFood(itemstack)) {
                int i = this.getAge();
                if (!this.level.isClientSide && i == 0 && this.canFallInLove()) {
                    this.usePlayerItem(p_27584_, p_27585_, itemstack);
                    this.setInLove(p_27584_);
                    return InteractionResult.SUCCESS;
                }

                if (this.isBaby()) {
                    this.usePlayerItem(p_27584_, p_27585_, itemstack);
                    this.ageUp(getSpeedUpSecondsWhenFeeding(-i), true);
                    return InteractionResult.sidedSuccess(this.level.isClientSide);
                }

                if (this.level.isClientSide) {
                    return InteractionResult.CONSUME;
                }
            }
        }

        return super.mobInteract(p_27584_, p_27585_);
    }

public static void convertZombies(Entity target, LivingEntity owner, boolean permanent){
        if (target instanceof Zombie zombieEntity && net.minecraftforge.event.ForgeEventFactory.canLivingConvert(zombieEntity, ModEntityType.ZOMBIE_SERVANT.get(), (timer) -> {})) {
            EntityType<? extends Mob> entityType = ModEntityType.ZOMBIE_SERVANT.get();
            if (zombieEntity instanceof ZombieVillager){
                entityType = ModEntityType.ZOMBIE_VILLAGER_SERVANT.get();
            } else if (zombieEntity instanceof Husk){
                entityType = ModEntityType.HUSK_SERVANT.get();
            } else if (zombieEntity instanceof Drowned){
                entityType = ModEntityType.DROWNED_SERVANT.get();
            } else if (zombieEntity instanceof Frayed){
                entityType = ModEntityType.FRAYED_SERVANT.get();
            } else if (zombieEntity instanceof ZombifiedPiglin){
                entityType = ModEntityType.ZPIGLIN_SERVANT.get();
            }
            ZombieServant zombieServant = (ZombieServant) zombieEntity.convertTo(entityType, true);
            if (zombieServant != null) {
                if (owner != null) {
                    zombieServant.setTrueOwner(owner);
                }
                if (target.level instanceof ServerLevel serverLevel) {
                    zombieServant.finalizeSpawn(serverLevel, target.level.getCurrentDifficultyAt(zombieServant.blockPosition()), MobSpawnType.CONVERSION, null, null);
                }
                if (zombieEntity instanceof ZombieVillager villager && zombieServant instanceof ZombieVillagerServant servant){
                    servant.setVillagerData(villager.getVillagerData());
                    servant.setGossips(villager.gossips);
                    servant.setTradeOffers(villager.tradeOffers);
                    servant.setVillagerXp(villager.getVillagerXp());
                }
                zombieServant.setBaby(zombieEntity.isBaby());
                if (!permanent) {
                    zombieServant.setLimitedLife(10 * (15 + target.level.random.nextInt(45)));
                }
                net.minecraftforge.event.ForgeEventFactory.onLivingConvert(zombieEntity, zombieServant);
                if (!zombieServant.isSilent()) {
                    zombieServant.level.levelEvent(null, 1026, zombieServant.blockPosition(), 0);
                }
            }
        }
    }

