public void aiStep() {
        if (this.attackAnimationRemainingTicks > 0) {
            --this.attackAnimationRemainingTicks;
        }
        if (this.level instanceof ServerLevel serverLevel){
            if (this.findNearestRepellent(serverLevel, this).isPresent()){
                if (this.nearestRepellent == null){
                    this.nearestRepellent = this.findNearestRepellent(serverLevel, this).get();
                    this.getNavigation().stop();
                    this.retreatTime = 200;
                }
            } else {
                this.nearestRepellent = null;
            }

            if (this.isBaby()){
                if (this.toAvoid != null && !this.toAvoid.isDeadOrDying()){
                    Vec3 vec31 = this.toAvoid.position();
                    if (this.position().closerThan(vec31, 8)) {
                        if (this.getNavigation().isDone()) {
                            for (int i = 0; i < 10; ++i) {
                                Vec3 vector3d2 = DefaultRandomPos.getPosAway(this, 16, 7, vec31);
                                if (vector3d2 != null) {
                                    Path path = this.getNavigation().createPath(vector3d2.x, vector3d2.y, vector3d2.z, 0);
                                    if (path != null && path.canReach()) {
                                        this.getNavigation().moveTo(path, 1.0F);
                                        break;
                                    }
                                }
                            }
                        }
                    }
                }
            } else {
                this.toAvoid = null;
            }

            if (this.retreatTime > 0){
                --this.retreatTime;
                this.setTarget(null);
            }

            if (this.avoidTime > 0){
                --this.avoidTime;
                this.setTarget(null);
            } else {
                this.toAvoid = null;
            }

            if (this.nearestRepellent != null){
                Vec3 vec31 = this.nearestRepellent.getCenter();
                if (this.position().closerThan(vec31, 8)) {
                    if (this.getNavigation().isDone()) {
                        for (int i = 0; i < 10; ++i) {
                            Vec3 vector3d2 = LandRandomPos.getPosAway(this, 16, 7, vec31);
                            if (vector3d2 != null) {
                                Path path = this.getNavigation().createPath(vector3d2.x, vector3d2.y, vector3d2.z, 0);
                                if (path != null && path.canReach()) {
                                    this.getNavigation().moveTo(path, 1.0F);
                                    break;
                                }
                            }
                        }
                    }
                }
            }
        }

        super.aiStep();
    }

public void remove(RemovalReason p_149847_) {
        int i = this.getSize();
        if (!this.level.isClientSide && i > 1 && this.isDeadOrDying()) {
            Component component = this.getCustomName();
            boolean flag = this.isNoAi();
            float f = (float)i / 4.0F;
            int j = i / 2;
            int k = 2 + this.random.nextInt(3);

            for(int l = 0; l < k; ++l) {
                float f1 = ((float)(l % 2) - 0.5F) * f;
                float f2 = ((float)(l / 2) - 0.5F) * f;
                SlimeServant slime = this.getType().create(this.level);
                if (slime != null) {
                    if (this.isPersistenceRequired()) {
                        slime.setPersistenceRequired();
                    }

                    slime.setCustomName(component);
                    slime.setNoAi(flag);
                    slime.setInvulnerable(this.isInvulnerable());
                    slime.setSize(j, true);
                    if (this.getTrueOwner() != null) {
                        slime.setTrueOwner(this.getTrueOwner());
                    }
                    if (this.limitedLifeTicks > 0) {
                        slime.setLimitedLife(this.limitedLifeTicks);
                    }
                    slime.setHostile(this.isHostile());
                    slime.moveTo(this.getX() + (double) f1, this.getY() + 0.5D, this.getZ() + (double) f2, this.random.nextFloat() * 360.0F, 0.0F);
                    this.level.addFreshEntity(slime);
                }
            }
        }

        super.remove(p_149847_);
    }

