                            return false;
                        } else {
                            EvokerServant.this.setRavageTarget(list.get(EvokerServant.this.random.nextInt(list.size())));
                            return true;
                        }
                    } else {
                        return false;
                    }
                } else {
                    return false;
                }
            }
        }

