private static Pair<BlockPos, Integer> findPos(ServerWorldAccess world, BlockPos pos) {
		BWWorldState worldState = BWWorldState.get(world.toServerWorld());
		for (Long longPos : worldState.potentialCandelabras) {
			BlockPos candelabraPos = BlockPos.fromLong(longPos);
			double distance = Math.sqrt(candelabraPos.getSquaredDistance(pos));
			if (distance <= Byte.MAX_VALUE) {
				int radius = -1;
				BlockEntity blockEntity = world.getBlockEntity(candelabraPos);
				BlockState state = world.getBlockState(candelabraPos);
				if (blockEntity instanceof WitchAltarBlockEntity witchAltar) {
					for (int i = 0; i < witchAltar.size(); i++) {
						Block block = Block.getBlockFromItem(witchAltar.getStack(i).getItem());
						if (block instanceof CandelabraBlock candelabraBlock) {
							radius = candelabraBlock.repellentRadius;
							break;
						}
					}
				} else if (state.getBlock() instanceof CandelabraBlock candelabra && state.get(Properties.LIT)) {
					radius = candelabra.repellentRadius;
				}
				if (distance <= radius) {
					return new Pair<>(candelabraPos, radius);
				}
			}
		}
		return null;
	}

@Override
    public boolean canUse() {
        if (this.entity.getLeader().isEmpty()) {
            List<WerewolfBaseEntity> list = this.entity.getCommandSenderWorld().getEntitiesOfClass(WerewolfBaseEntity.class, this.entity.getBoundingBox().inflate(16, 8, 16), IEntityLeader.class::isInstance);
            double d0 = Double.MAX_VALUE;
            IEntityLeader newLeader = null;
            for (WerewolfBaseEntity entity : list) {
                IEntityLeader leader = (IEntityLeader) entity;
                if (entity.isAlive() && leader.getFollowingCount() < leader.getMaxFollowerCount()) {
                    double d1 = this.entity.distanceToSqr(entity);

                    if (d1 <= d0) {
                        d0 = d1;
                        newLeader = leader;
                    }
                }
            }

            if (newLeader != null) {
                this.entity.setLeader(newLeader);
                newLeader.increaseFollowerCount();
            }
        }
        return this.entity.getLeader().map(leader -> leader.getRepresentingEntity().isAlive() && this.entity.distanceToSqr(leader.getRepresentingEntity()) > DIST).orElse(false);
    }

@Override
    public boolean canContinueToUse() {
        return this.entity.getLeader().map(leader -> {
            double d0 = this.entity.distanceToSqr(leader.getRepresentingEntity());
            return d0 >= DIST && d0 <= 256.0D;
        }).orElse(false);
    }

