@Override
	public void aiStep() {
		if (this.master == null) {
			this.findNewMaster();
		}
		// if we still don't have a master, or ours is dead, die.
		if (this.master == null || !this.master.isAlive()) {
			this.discard();
		}
		super.aiStep();
	}

private void findNewMaster() {
		List<Lich> nearbyLiches = this.level().getEntitiesOfClass(Lich.class, new AABB(getX(), getY(), getZ(), getX() + 1, getY() + 1, getZ() + 1).inflate(32.0D, 16.0D, 32.0D));

		for (Lich nearbyLich : nearbyLiches) {
			if (!nearbyLich.isShadowClone() && nearbyLich.wantsNewMinion()) {
				this.master = nearbyLich;

				// animate our new linkage!
				if (!this.level().isClientSide()) {
					this.master.makeMagicTrail(this.getEyePosition(), this.master.getEyePosition(), 0.0F, 0.0F, 0.0F);
				}

				// become angry at our masters target
				this.setTarget(this.master.getTarget());

				// quit looking
				break;
			}
		}
	}

@Override
	public @Nullable SpawnGroupData finalizeSpawn(ServerLevelAccessor level, DifficultyInstance difficulty, EntitySpawnReason spawnType, @Nullable SpawnGroupData spawnGroupData) {
		boolean baby = false;

		if (this.master != null && difficulty.getDifficulty() == Difficulty.HARD) {
			int babiesSummoned = this.master.getBabyMinionsSummoned();
			if (babiesSummoned < this.master.getAttributeValue(TFAttributes.MINION_COUNT) / 4) { // One quarter can be babies on hard, by default: 9 / 4 = 2
				baby = this.getRandom().nextInt(100) <= 20; // 20%
			}
			if (baby) this.master.setBabyMinionsSummoned(babiesSummoned + 1);
		}

		spawnGroupData = new ZombieGroupData(baby, true);
		return super.finalizeSpawn(level, difficulty, spawnType, spawnGroupData);
	}

@Override
	public void tick() {
		if (this.lich.getTeleportInvisibility() > 0) return;
		LivingEntity targetedEntity = this.lich.getTarget();
		if (targetedEntity == null) return;
		float dist = this.lich.distanceTo(targetedEntity);
		// spawn minions every so often
		if (this.lich.getAttackCooldown() % 15 == 0) this.checkAndSpawnMinions();

		boolean hasLineOfSight = this.lich.getSensing().hasLineOfSight(targetedEntity);
		if (hasLineOfSight != this.seeTime > 0) this.seeTime = 0;

		if (hasLineOfSight) ++this.seeTime;
        else --this.seeTime;

		if (dist < ATTACK_RANGE && this.seeTime >= 20) {
			this.lich.getNavigation().stop();
			++this.strafingTime;
		} else this.strafingTime = -1;

		if (this.strafingTime >= 20) {
			if ((double)this.lich.getRandom().nextFloat() < 0.3) this.strafingClockwise = !this.strafingClockwise;
			if ((double)this.lich.getRandom().nextFloat() < 0.3) this.strafingBackwards = !this.strafingBackwards;
			this.strafingTime = 0;
		}

		if (this.strafingTime > -1) {
			if (dist > (double)(ATTACK_RANGE * 0.75F)) this.strafingBackwards = false;
            else if (dist < (double)(ATTACK_RANGE * 0.25F)) this.strafingBackwards = true;

			this.lich.getMoveControl().strafe(this.strafingBackwards ? -0.5F : 0.5F, this.strafingClockwise ? 0.5F : -0.5F);
			this.lich.lookAt(targetedEntity, 30.0F, 30.0F);
		} else {
			this.lich.getLookControl().setLookAt(targetedEntity, 30.0F, 30.0F);
		}

		if (this.lich.getAttackCooldown() == 0) {
			ServerLevel serverLevel = getServerLevel(this.lich);
			if (dist < 2.0F) {
				// melee attack
				this.lich.doHurtTarget(serverLevel, targetedEntity);

				this.lich.swing(InteractionHand.MAIN_HAND);
				this.lich.setAttackCooldown(20);
			} else if (dist < ATTACK_RANGE && this.lich.getSensing().hasLineOfSight(targetedEntity)) {
				if (this.lich.getNextAttackType() == 0) this.lich.launchProjectileAt(new LichBolt(serverLevel, this.lich));
				else this.lich.launchProjectileAt(new LichBomb(serverLevel, this.lich));

				this.lich.swing(InteractionHand.MAIN_HAND);
				this.lich.setNextAttackType(this.lich.getRandom().nextBoolean() ? 0 : 1);
				this.lich.setAttackCooldown(60);
			} else {
				// if not, teleport around
				this.lich.teleportToNewTarget(targetedEntity, ATTACK_RANGE, null);
				this.lich.setAttackCooldown(20);
			}
		}
	}

private void checkAndSpawnMinions() {
		if (this.lich.getMinionsToSummon() > 0) {
			int minions = this.lich.countMyMinions();

			// if not, spawn one!
			if (minions < Lich.MAX_ACTIVE_MINIONS) {
				this.spawnMinionAt();
				this.lich.setMinionsToSummon(this.lich.getMinionsToSummon() - 1);
			}
		}
	}

private void spawnMinionAt() {
		// find a good spot
		LivingEntity targetedEntity = this.lich.getTarget();
		Vec3 minionSpot = this.lich.findVecInLOSOf(targetedEntity);

		if (minionSpot != null && this.lich.level() instanceof ServerLevelAccessor accessor) {
			// put a clone there
			LichMinion minion = new LichMinion(this.lich.level(), this.lich);
			minion.setPos(minionSpot.x(), minionSpot.y(), minionSpot.z());
			EventHooks.finalizeMobSpawn(minion, accessor, accessor.getCurrentDifficultyAt(BlockPos.containing(minionSpot)), EntitySpawnReason.MOB_SUMMONED, null);
			this.lich.level().addFreshEntity(minion);

			minion.setTarget(targetedEntity);

			minion.spawnAnim();
			minion.playSound(TFSounds.MINION_SUMMON.get(), 1.0F, ((this.lich.getRandom().nextFloat() - this.lich.getRandom().nextFloat()) * 0.7F + 1.0F) * 0.75F);

			this.lich.swing(InteractionHand.MAIN_HAND);
			// make sparkles leading to it
			this.lich.makeMagicTrail(this.lich.getEyePosition(), minion.getEyePosition(), this.lich.getRandom().nextFloat() * 0.0625F + 0.125F, this.lich.getRandom().nextFloat() * 0.0625F + 0.125F, this.lich.getRandom().nextFloat() * 0.0625F + 0.125F);
		}
	}

@Override
	public boolean canUse() {
		return this.lich.getHealth() < this.lich.getMaxHealth() / 2 && this.lich.countMyMinions() > 0;
	}

@Override
	public void tick() {
		if (this.lich.getTeleportInvisibility() > 0) return;
		super.tick();
		if (this.lich.getScepterTimeLeft() > 0) return;

		List<LichMinion> minions = this.lich.level().getEntitiesOfClass(LichMinion.class, this.lich.getBoundingBox().inflate(32.0D, 16.0D, 32.0D))
			.stream().filter(m -> m.master == this.lich).toList();

		if (!minions.isEmpty()) {
			LichMinion minion = minions.getFirst();
			minion.discard();
			//rain particles
			LifedrainScepterItem.animateTargetShatter((ServerLevel) this.lich.level(), minion);
			// play death sound
			SoundEvent deathSound = EntityUtil.getDeathSound(minion);
			if (deathSound != null) {
				this.lich.level().playSound(null, minion.blockPosition(), deathSound, SoundSource.HOSTILE, 1.0F, minion.getVoicePitch());
			}
			//funny pop sound
			this.lich.playSound(TFSounds.LICH_POP_MOB.get(), 3.0F, 0.4F + this.lich.getRandom().nextFloat() * 0.2F);
			minion.playSound(TFSounds.LICH_POP_MOB.get(), 3.0F, 0.4F + this.lich.getRandom().nextFloat() * 0.2F);
			// make trail so it's clear that we did it
			this.lich.makeMagicTrail(minion.getEyePosition(), this.lich.getEyePosition(), 1.0F, 0.5F, 0.5F);
			//heal some health
			this.lich.heal(minion.getHealth());
			this.lich.swing(InteractionHand.MAIN_HAND);
			this.lich.setPopCooldown(40);
			this.lich.gameEvent(GameEvent.ENTITY_DIE);
		}
	}

@Override
	protected void registerGoals() {
		this.goalSelector.addGoal(0, new FloatGoal(this));
		this.goalSelector.addGoal(0, new AttemptToGoHomeGoal<>(this, 1.25D) {
			@Override
			public boolean canUse() {
				return super.canUse() && Lich.this.isOutsideHomeRange(Lich.this.position());
			}

			@Override
			public boolean requiresUpdateEveryTick() {
				return true;
			}

			@Override
			public void tick() {
				if (Lich.this.getTeleportInvisibility() > 0) return;
				if (Lich.this.getNavigation().getPath() == null || Lich.this.getNavigation().isStuck() || !Lich.this.getNavigation().getPath().canReach()) {
					if (!Lich.this.teleportToNewTarget(Lich.this.getTarget(), 20.0F, null)) Lich.this.teleportHome();
				}
			}
		});
		this.goalSelector.addGoal(1, new RandomLookAroundIfBoredGoal(this));
		this.goalSelector.addGoal(1, new AlwaysWatchTargetGoal(this));
		this.goalSelector.addGoal(1, new LichPopMobsGoal(this));
		this.goalSelector.addGoal(1, new LichAbsorbMinionsGoal(this));
		this.goalSelector.addGoal(2, new LichShadowsGoal(this, 30.0F)); // Phase 1
		this.goalSelector.addGoal(3, new LichMinionsGoal(this)); // Phase 2
		this.goalSelector.addGoal(4, new MeleeAttackGoal(this, 0.75D, true) { // Phase 3
			@Override
			public boolean canUse() {
				return Lich.this.getPhase() == 3 && super.canUse();
			}

			@Override
			public void tick() {
				if (((Lich)this.mob).getTeleportInvisibility() > 0) return;
				super.tick();
				if (this.mob.getTarget() != null && !this.mob.isWithinMeleeAttackRange(this.mob.getTarget()) && this.mob.getNavigation().isDone()) {
					if (!this.mob.getNavigation().moveTo(this.mob.getTarget(), this.speedModifier)) {
						Lich.this.teleportToSightOfEntity(this.mob.getTarget());
					}
				}
			}

			@Override
			public void start() {
				super.start();
				this.mob.setItemInHand(InteractionHand.MAIN_HAND, new ItemStack(Items.GOLDEN_SWORD));
			}
		});
		this.addRestrictionGoals(this, this.goalSelector);
		this.targetSelector.addGoal(1, new HurtByTargetGoal(this) {
			@Override
			public boolean canUse() {
				if (this.mob instanceof Lich main && this.mob.getLastHurtByMob() instanceof Lich lich && lich.getMaster() == main.getMaster()) {
					return false;
				}
				return super.canUse();
			}
		});
		this.targetSelector.addGoal(2, new NearestAttackableTargetGoal<>(this, Player.class, false));
	}

@Override
