		this.babyMinionsSummoned = input.getIntOr("BabyMinionsSummoned", 0);
		this.hitsWithoutTeleport = input.getIntOr("HitsWithoutTeleport", 0);
	}

@Override
	public boolean hurtServer(ServerLevel serverLevel, DamageSource src, float damage) {
		if (this.getTeleportInvisibility() > 0 && !src.is(DamageTypeTags.BYPASSES_INVULNERABILITY)) return false;

		// if we're in a wall, teleport for gosh sakes
		if (src.is(DamageTypes.IN_WALL) && this.getTarget() != null) {
			this.teleportToNewTarget(this.getTarget(), 20.0F, null);
		}

		if (this.isShadowClone() && !src.is(DamageTypeTags.BYPASSES_INVULNERABILITY)) {
			this.playSound(TFSounds.LICH_CLONE_HURT.get(), 1.0F, this.getVoicePitch() * 2.0F);
			return false;
		}

		// ignore all bolts that are not reflected
		if (src.getEntity() instanceof Lich) {
			return false;
		}

		// if our shield is up, ignore any damage that can be blocked.
		if (!src.is(DamageTypeTags.BYPASSES_INVULNERABILITY) && this.getShieldStrength() > 0) {
			if (src.is(TFDamageTypeTags.BREAKS_LICH_SHIELDS) && damage > 2) {
				// reduce shield for magic damage greater than 1 heart
				if (this.getShieldStrength() > 0) {
					int newShieldStrength = this.getShieldStrength() - 1;
					this.setShieldStrength(newShieldStrength);
					float volume = 1.5F;
					FortificationShieldAttachment.addShieldBreakParticles(src, this);
					if (newShieldStrength < 6) volume += 0.25F * (6 - newShieldStrength);
					if (newShieldStrength == 0) volume += 0.5F;
					this.playSound(TFSounds.SHIELD_BREAK.get(), volume, this.getVoicePitch() * 1.25F);
					this.gameEvent(GameEvent.ENTITY_DAMAGE);
				}
			} else {
				this.playSound(TFSounds.SHIELD_BLOCK.get(), 0.75F, this.getVoicePitch() * 1.75F);
				this.gameEvent(GameEvent.ENTITY_DAMAGE);
				if (src.getEntity() instanceof LivingEntity living) {
					this.setLastHurtByMob(living);
				}
			}

			return false;
		}

		if (super.hurtServer(serverLevel, src, damage)) {
			if (this.getRandom().nextInt(this.getPhase() == 3 ? 6 : 3) <= this.hitsWithoutTeleport++ && !this.isDeadOrDying()) {
				this.hitsWithoutTeleport = 0;
				this.teleportToNewTarget(this.getTarget(), 20.0F, null);
			}

			return true;
		} else return false;
	}

public int countMyClones() {
		// check if there are enough clones
		int count = 0;

		if (this.level() instanceof ServerLevel server) {
			for (UUID uuid : this.summonedClones) {
				Entity clone = server.getEntity(uuid);
				if (clone instanceof Lich lich && lich.getMaster() == this) {
					count++;
				}
			}
		}

		return count;
	}

public int countMyMinions() {
		return (int) this.level().getEntitiesOfClass(LichMinion.class, new AABB(this.getX(), this.getY(), this.getZ(), this.getX() + 1, this.getY() + 1, this.getZ() + 1).inflate(32.0D, 16.0D, 32.0D))
			.stream()
			.filter(m -> m.master == this)
			.count();
	}

public boolean teleportToNewTarget(@Nullable LivingEntity target, float range, @Nullable LichShadowsGoal lichShadowsGoal) {
		List<Player> possibleTargets = new ArrayList<>();
		for (Player player : this.level().players()) {
			if (player.distanceTo(this) < range && !player.isDeadOrDying()) possibleTargets.add(player);
		}

		if (!possibleTargets.isEmpty()) target = possibleTargets.get(this.getRandom().nextInt(possibleTargets.size()));

		if (target != null) {
			this.setTarget(target);
			if (this.teleportToSightOfEntity(target)) {
				for (Lich clone : this.getAllClones()) {
					clone.setTarget(target);
                    clone.teleportToSightOfEntity(target);
                }
				if (lichShadowsGoal != null) lichShadowsGoal.checkAndSpawnClones(target);
				return true;
			}
		}
		return false;
	}

public int getPhase() {
		if (this.isShadowClone() || this.getShieldStrength() > 0) {
			return 1;
		} else if (this.getMinionsToSummon() > 0 || this.countMyMinions() > 0) {
			return 2;
		} else {
			return 3;
		}
	}

protected MinionEntity(EntityType<? extends PathfinderMob> type, Level world, @NotNull Predicate<LivingEntity> attackPredicate) {
        super(type, world);
        this.softAttackPredicate = attackPredicate;
        this.hardAttackPredicate = livingEntity -> {
            boolean flag1 = getLordOpt().map(ILordPlayer::asEntity).filter(entity -> entity == livingEntity).isPresent(); //Don't attack lord
            boolean flag2 = livingEntity instanceof MinionEntity && ((MinionEntity<?>) livingEntity).getLordID().filter(id -> getLordID().map(id2 -> id == id2).orElse(false)).isPresent(); //Don't attack other minions of lord
            boolean flag3 = livingEntity instanceof Player otherPlayer && getLordOpt().map(ILordPlayer::asEntity).map(player -> !player.canHarmPlayer(otherPlayer)).orElse(!Permissions.isPvpEnabled(otherPlayer));
            return !flag1 && !flag2 && !flag3;
        };
        this.property = createSync();
    }

@Override
    public void aiStep() {
        updateSwingTime();
        super.aiStep();
        if (!this.level().isClientSide() && this.isAlive()) {
            if (this.random.nextInt(900) == 0 && this.deathTime == 0) {
                this.heal(1.0F);
            }
            if (this.tickCount % 20 == 0) {
                this.consumeOffhand();
            }
        }
        if (convertCounter > 0) {
            convertCounter--;
        }
        if (!this.level().isClientSide() && !this.isValid() && this.isAlive()) {
            LOGGER.warn("Minion without lord.");
            this.discard();
        }
    }

public void claimMinionSlot(int id, @NotNull PlayerMinionController controller) {
        assert minionId == 0;
        controller.claimMinionSlot(id).ifPresent(token -> {
            playerMinionController = controller;
            minionId = id;
            this.token = token;
            getEntityData().set(LORD_ID, Optional.of(playerMinionController.getUUID()));
        });
    }

@Override
    public void die(@NotNull DamageSource cause) {
        super.die(cause);
        if (this.playerMinionController != null) {
            this.getLordOpt().map(ILordPlayer::asEntity).ifPresent(p -> p.sendOverlayMessage(Component.translatable("dialogue.factionapi.minion.died", this.getDisplayName())));
            this.playerMinionController.markDeadAndReleaseMinionSlot(minionId, token);
            this.playerMinionController = null;
        }
    }

public Predicate<LivingEntity> getAttackPredicate(boolean onlyShould) {
        return onlyShould ? this.hardAttackPredicate.and(this.softAttackPredicate) : this.hardAttackPredicate;
    }

@Override
    public void setTarget(@Nullable LivingEntity entitylivingbaseIn) {
        if (entitylivingbaseIn == null || hardAttackPredicate.test(entitylivingbaseIn)) {
            super.setTarget(entitylivingbaseIn);
        }
    }

protected Optional<ILordPlayer> getLord() {
        return this.getLordID().map(this.level()::getPlayerByUUID).filter(Player::isAlive).map(FactionPlayerHandler::get).flatMap(IFactionExtensionGetter::getPlayerLord);
    }

@Override
    public void onRemovedFromLevel() {
        if (playerMinionController != null) {
            playerMinionController.checkInMinion(this.minionId, this.token);
            //noinspection DataFlowIssue
            this.minionData.updateEntityCaps(this.serializeMinionCaps());
            this.minionData = null;
            this.playerMinionController = null;
        }
        super.onRemovedFromLevel();
    }

@Override
    public void readAdditionalSaveData(@NotNull ValueInput input) {
        super.readAdditionalSaveData(input);
        input.child("minion").ifPresent(minion -> {
            var id = minion.read("lord", UUIDUtil.CODEC);
            if (id.isPresent()) {
                if (level() instanceof ServerLevel serverLevel) {
                    this.playerMinionController = MinionWorldData.getData(serverLevel).getController(id.get());
                    if (this.playerMinionController == null) {
                        LOGGER.warn("Cannot get PlayerMinionController for {}", id.get());
                    } else {
                        this.minionId = minion.getInt("minion_id").orElseThrow();
                        this.token = minion.getInt("minion_token").orElseThrow();
                        this.getEntityData().set(LORD_ID, id);
                    }
                }
            }
        });
    }

protected void consumeOffhand() {
        if (isUsingItem()) return;
        if (this.targetSelector.getAvailableGoals().stream().anyMatch(WrappedGoal::isRunning)) return;
        ItemStack stack = this.getInventory().map(i -> i.getItem(1)).orElse(ItemStack.EMPTY);
        if (stack.isEmpty()) return;
        Consumable consumable = stack.get(DataComponents.CONSUMABLE);
        if (consumable == null) return;
        if (!canConsume(stack, consumable)) return;
        this.startUsingItem(InteractionHand.OFF_HAND);
        this.setYRot(this.getYHeadRot());
    }

