private void checkoutMinionData(HolderLookup.Provider provider) {
        if (playerMinionController != null && minionData == null) {
            this.minionData = playerMinionController.checkoutMinion(this.minionId, this.token, this);
            if (minionData == null) {
                this.playerMinionController = null;
            } else {
                this.handleLoadedMinionData(minionData);
            }
        }
    }

public final void handleLoadedMinionData(@NotNull T data) {
        this.updateAttributes();
        super.setHealth(data.getHealth());
        super.setCustomName(data.getFormattedName());
        try {
            this.onMinionDataReceived(data);
        } catch (ClassCastException e) {
            LOGGER.error("Failed to cast minion data. Maybe the correct data was not registered", e);
            this.discard();
        }
        sync();
    }

public DefendAreaGoal(@NotNull MinionEntity<?> entity) {
        super(entity, false);
        this.entity = entity;
        this.setFlags(EnumSet.of(Goal.Flag.TARGET));
        this.predicate = TargetingConditions.forCombat().selector((e, level) -> entity.getAttackPredicate(true).test(e)).ignoreInvisibilityTesting().range(60);
    }

@Override
    public boolean canUse() {
        return entity.getCurrentTask().filter(task -> task.getTask() == FactionMinionTasks.DEFEND_AREA.get() && ((DefendAreaTask.Desc) task).center != null).map(task -> {
                    BlockPos newCenter = ((DefendAreaTask.Desc) task).center;
                    if (bb == null || center == null || !center.equals(newCenter)) {
                        this.bb = new AABB(newCenter).inflate(((DefendAreaTask.Desc) task).distance);
                        this.center = newCenter;
                    }

                    this.targetMob = ((ServerLevel)entity.level()).getNearestEntity(LivingEntity.class, predicate, entity, entity.getX(), entity.getY(), entity.getZ(), bb);
                    return this.targetMob != null;
                }
        ).orElse(false);
    }

