public void tick() {
            double dist = EntityBlueJay.this.distanceTo(this.following);
            if (dist > 6 || EntityBlueJay.this.isFlying()) {
                EntityBlueJay.this.setFlying(true);
                EntityBlueJay.this.getMoveControl().setWantedPosition(this.following.getX(), this.following.getY(), this.following.getZ(), 1);
            }else{
                EntityBlueJay.this.getNavigation().moveTo(this.following.getX(), this.following.getY(), this.following.getZ(), 1);
            }
            if(EntityBlueJay.this.isFlying() && EntityBlueJay.this.onGround() && dist < 3){
                EntityBlueJay.this.setFlying(false);
            }
            if (this.following instanceof EntityRaccoon raccoon) {
                if(dist > 40){
                    EntityBlueJay.this.teleportTo(this.following.getX(), this.following.getY(), this.following.getZ());
                }
                if(dist < 2.5F){
                    EntityBlueJay.this.getMoveControl().setWantedPosition(this.following.getX(), this.following.getY(), this.following.getZ(), 1);
                }
                if(dist < 1F && raccoon.getPassengers().isEmpty()){
                    EntityBlueJay.this.startRiding(raccoon, false);
                }
            }
        }

public void tick() {
        if (this.blueJay.isFlying()) {
            circlingTime++;
        }
        LivingEntity target = blueJay.getTarget();
        if(target != null){
            if(blueJay.distanceTo(target) < 3){
                blueJay.peck();
                target.hurt(target.damageSources().generic(), 1);
                stop();
            }
            if(circlingTime > maxCircleTime){
                blueJay.getMoveControl().setWantedPosition(target.getX(), target.getY() + target.getEyeHeight() / 2F, target.getZ(), 1.6F);

            }else{
                Vec3 circlePos = getVultureCirclePos(target.position());
                if (circlePos == null) {
                    circlePos = target.position();
                }
                blueJay.setFlying(true);
                blueJay.getMoveControl().setWantedPosition(circlePos.x(), circlePos.y() + target.getEyeHeight() + 0.2F, circlePos.z(), 1.6F);

            }
        }
    }

public boolean canUse() {
        if (this.mob.hasFollowers()) {
            return false;
        } else if (this.mob.isFollower()) {
            return true;
        } else if (this.nextStartTick > 0) {
            --this.nextStartTick;
            return false;
        } else {
            this.nextStartTick = this.nextStartTick(this.mob);
            Predicate<EntityFroststalker> froststalkerPredicate = (p_25258_) -> {
                return p_25258_.canBeFollowed() || !p_25258_.isFollower();
            };
            float range = 60F;
            List<Player> playerList = this.mob.level().getEntitiesOfClass(Player.class, this.mob.getBoundingBox().inflate(range, range, range), EntityFroststalker.VALID_LEADER_PLAYERS);
            Player closestPlayer = null;
            for(Player player : playerList){
                if(closestPlayer == null || player.distanceTo(mob) < closestPlayer.distanceTo(mob)){
                    closestPlayer = player;
                }
            }
            if(closestPlayer == null){
                List<EntityFroststalker> list = this.mob.level().getEntitiesOfClass(EntityFroststalker.class, this.mob.getBoundingBox().inflate(range, range, range), froststalkerPredicate);
                EntityFroststalker entityFroststalker = DataFixUtils.orElse(list.stream().filter(EntityFroststalker::canBeFollowed).findAny(), this.mob);
                entityFroststalker.addFollowers(list.stream().filter((p_25255_) -> {
                    return !p_25255_.isFollower();
                }));
            }else{
                this.mob.startFollowing(closestPlayer);
            }

            return this.mob.isFollower();
        }
    }

