public boolean hurt(DamageSource source, float amount) {
        if(source.is(DamageTypeTags.IS_FIRE)){
            amount *= 2F;
        }
        boolean prev = super.hurt(source, amount);
        if (prev && this.hasSpikes() && !this.isSpikeShaking() && source.getEntity() != null && source.getEntity().distanceTo(this) < 10) {
            this.setSpikeShaking(true);
            shakeTime = 20 + random.nextInt(60);
            standFor(shakeTime + 10);
        }
        return prev;
    }

public void tick() {
        super.tick();
        this.prevBipedProgress = bipedProgress;
        this.prevTackleProgress = tackleProgress;
        this.prevSpikeShakeProgress = spikeShakeProgress;
        this.prevTurnAngle = getTurnAngle();

        if (this.isBipedal()) {
            if (bipedProgress < 5.0F)
                bipedProgress++;
        } else {
            if (bipedProgress > 0F)
                bipedProgress--;
        }

        if (this.isTackling()) {
            if (tackleProgress < 5.0F)
                tackleProgress++;
        } else {
            if (tackleProgress > 0F)
                tackleProgress--;
        }

        if (this.isSpikeShaking()) {
            if (spikeShakeProgress < 5.0F)
                spikeShakeProgress++;

            if (currentSpeedMode != 2) {
                currentSpeedMode = 2;
                this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.1F);
            }
        } else {
            if (spikeShakeProgress > 0F)
                spikeShakeProgress--;

            if (isBipedal()) {
                if (currentSpeedMode != 0) {
                    currentSpeedMode = 0;
                    this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.35F);
                }
            } else {
                if (currentSpeedMode != 1) {
                    currentSpeedMode = 1;
                    this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.25F);
                }
            }
        }

        if (this.hasSpikes()) {
            if (!hasSpikedArmor) {
                hasSpikedArmor = true;
                this.getAttribute(Attributes.ARMOR).setBaseValue(12F);
            }
        } else {
            if (hasSpikedArmor) {
                hasSpikedArmor = false;
                this.getAttribute(Attributes.ARMOR).setBaseValue(0F);
            }
        }

        if (!this.level().isClientSide) {
            if (this.tickCount % 200 == 0) {
                if (isInWaterRainOrBubble() && !this.hasSpikes()) {
                    this.setSpiked(true);
                }
                if (this.isHotBiome() && !isInWaterRainOrBubble()) {
                    this.addEffect(new MobEffectInstance(MobEffects.WEAKNESS, 400));
                    if (random.nextInt(2) == 0 && !this.isInWaterRainOrBubble()) {
                        this.setSpiked(false);
                    }
                }
            }
            float threshold = 1F;
            boolean flag = false;
            if (isBipedal() && this.yRotO - this.getYRot() > threshold) {
                this.setTurnAngle(this.getTurnAngle() + 5);
                flag = true;
            }
            if (isBipedal() && this.yRotO - this.getYRot() < -threshold) {
                this.setTurnAngle(this.getTurnAngle() - 5);
                flag = true;
            }
            if (!flag) {
                if (this.getTurnAngle() > 0) {
                    this.setTurnAngle(Math.max(this.getTurnAngle() - 10, 0));
                }
                if (this.getTurnAngle() < 0) {
                    this.setTurnAngle(Math.min(this.getTurnAngle() + 10, 0));
                }
            }
            this.setTurnAngle(Mth.clamp(this.getTurnAngle(), -60, 60));
            if (standingTime > 0) {
                standingTime--;
            }
            if (standingTime < 0) {
                standingTime++;
            }

            if (standingTime <= 0 && this.isBipedal()) {
                standingTime = -200 - random.nextInt(400);
                this.setBipedal(false);
            }
            if (standingTime == 0 && !this.isBipedal() && this.getDeltaMovement().lengthSqr() >= 0.03D) {
                standingTime = 200 + random.nextInt(600);
                this.setBipedal(true);
            }
            if (shakeTime > 0) {
                if (this.shakeTime % 5 == 0) {
                    int spikeCount = 2 + random.nextInt(4);
                    for (int i = 0; i < spikeCount; i++) {
                        float f = ((i + 1) / (float) spikeCount) * 360F;
                        EntityIceShard shard = new EntityIceShard(level(), this);
                        shard.shootFromRotation(this, this.getXRot() - random.nextInt(40), f, 0.0F, 0.15F + random.nextFloat() * 0.2F, 1.0F);
                        level().addFreshEntity(shard);
                    }
                }
                shakeTime--;
            }
            if (shakeTime == 0 && this.isSpikeShaking()) {
                this.setSpikeShaking(false);
                if (random.nextInt(2) == 0) {
                    this.setSpiked(false);
                }
            }
            if (this.getTarget() != null && isValidLeader(this.getTarget())) {
                this.setTarget(null);
            }
            //Makes entire pack attack target
            if (this.getTarget() != null && !isValidLeader(this.getTarget()) && this.getTarget().isAlive() && (this.getLastHurtByMob() == null || !this.getLastHurtByMob().isAlive())) {
                this.setLastHurtByMob(this.getTarget());
            }
            LivingEntity playerTarget = null;
            if (leader instanceof Player) {
                playerTarget = leader.getLastHurtMob();
                if (playerTarget == null || !playerTarget.isAlive() || playerTarget instanceof EntityFroststalker) {
                    playerTarget = leader.getLastHurtByMob();
                }
            }
            if (playerTarget != null && playerTarget.isAlive() && !(playerTarget instanceof EntityFroststalker)) {
                this.setTarget(playerTarget);
            }
            boolean attackAnim = this.getAnimation() == ANIMATION_BITE && this.getAnimationTick() == 5 ||
                    this.getAnimation() == ANIMATION_SHOVE && this.getAnimationTick() == 8 ||
                    this.getAnimation() == ANIMATION_SLASH_L && this.getAnimationTick() == 7 ||
                    this.getAnimation() == ANIMATION_SLASH_R && this.getAnimationTick() == 7;
            if (this.getTarget() != null && attackAnim) {
                getTarget().knockback(0.2F, getTarget().getX() - this.getX(), getTarget().getZ() - this.getZ());
                this.getTarget().hurt(this.damageSources().mobAttack(this), (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE));
            }
        }
        if (fleeFireFlag > 0) {
            fleeFireFlag--;
        }
        if(!this.level().isClientSide){
            if(resetLeaderCooldown > 0){
                resetLeaderCooldown--;
            }else{
                resetLeaderCooldown = 200 + this.getRandom().nextInt(200);
                this.lookForPlayerLeader();
            }
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

private void lookForPlayerLeader() {
       if(!(this.leader instanceof Player)){
           float range = 10;
           List<Player> playerList = this.level().getEntitiesOfClass(Player.class, this.getBoundingBox().inflate(range, range, range), EntityFroststalker.VALID_LEADER_PLAYERS);
           Player closestPlayer = null;
           for(Player player : playerList){
               if(closestPlayer == null || player.distanceTo(this) < closestPlayer.distanceTo(this)){
                   closestPlayer = player;
               }
           }
           if(closestPlayer != null){
               this.stopFollowing();
               this.startFollowing(closestPlayer);
           }
       }
    }

public boolean isValidLeader(LivingEntity leader) {
        if (leader instanceof Player) {
            if (this.getLastHurtByMob() != null && this.getLastHurtByMob().equals(leader)) {
                return false;
            }
            return leader.getItemBySlot(EquipmentSlot.HEAD).is(AMItemRegistry.FROSTSTALKER_HELMET.get());
        } else {
            return leader.isAlive() && leader instanceof EntityFroststalker;
        }
    }

public LivingEntity startFollowing(LivingEntity leader) {
        this.leader = leader;
        if (leader instanceof EntityFroststalker) {
            ((EntityFroststalker) leader).addFollower();
        }
        return leader;
    }

public void stopFollowing() {
        if (this.leader instanceof EntityFroststalker) {
            ((EntityFroststalker) this.leader).removeFollower();
        }
        this.leader = null;
    }

public void pathToLeader() {
        if (this.isFollower()) {
            double speed = 1.0D;
            if (leader instanceof Player) {
                speed = 1.3D;
                if (this.distanceTo(leader) > 24) {
                    speed = 1.4F;
                    this.standFor(20);
                }
            }
            if (this.distanceTo(leader) > 6 && this.getNavigation().isDone()) {
                this.getNavigation().moveTo(this.leader, speed);
            }
        }
    }

public static List<LivingEntity> getOwnerEnemies(LivingEntity owner, LivingEntity familiar, float range) {
        if (null == owner)
            return new ArrayList<>();

        LivingEntity revenge = owner.getLastHurtByMob();
        LivingEntity target = owner.getLastHurtMob();
        if (target instanceof IFamiliar ally && ally.getFamiliarOwner() == owner)
            target = null;
        if (target instanceof TamableAnimal ally && ally.getOwner() == owner)
            target = null;

        List<LivingEntity> enemies = new ArrayList<>();
        if (isClose(revenge, familiar, range))
            enemies.add(revenge);
        if (isClose(target, familiar, range))
            enemies.add(target);
        return enemies;
    }

public static <T extends Entity & IFamiliar> List<T> getAllNearbyFamiliars(LivingEntity owner, EntityType<T> type,
                                                                               Predicate<T> pred) {
        return owner.level().getEntities(type, owner.getBoundingBox().inflate(10),
                e -> pred.test(e) && e.getFamiliarOwner() == owner && e.isAlive());
    }

@SuppressWarnings("unchecked")
    public static <T extends Entity & IFamiliar> List<T> getAllEquippedFamiliars(LivingEntity owner, EntityType<T> type,
                                                                                 Predicate<T> pred) {
        List<T> familiars = new ArrayList<>();

        var handler = CuriosApi.getCuriosInventory(owner).orElse(null);
        if (handler == null)
            return familiars;

        for (ICurioStacksHandler curios : handler.getCurios().values()) {
            var stacks = curios.getStacks();
            for (int i = 0; i < stacks.getSlots(); i++) {
                List<IFamiliar> familiarList = FamiliarCurio.getFamiliar(stacks.getStackInSlot(i), owner.level());
                if (familiarList != null) {
                    for (IFamiliar familiar : familiarList) {
                        if (familiar.getFamiliarEntity().getType() == type) {
                            T fam = (T) familiar.getFamiliarEntity();
                            if (pred.test(fam)) {
                                familiars.add(fam);
                            }
                        }
                    }
                }
            }
        }
        for (EquipmentSlot slot : EquipmentSlot.values()) {
            if ((owner.getItemBySlot(slot).is(Tags.Items.TOOLS) && slot.getType().equals(EquipmentSlot.Type.HAND))
                    || slot.isArmor()) {
                List<IFamiliar> familiarList = FamiliarCurio.getFamiliar(owner.getItemBySlot(slot), owner.level());
                if (familiarList != null) {
                    for (IFamiliar familiar : familiarList) {
                        if (familiar.getFamiliarEntity().getType() == type) {
                            T fam = (T) familiar.getFamiliarEntity();
                            if (pred.test(fam)) {
                                familiars.add(fam);
                            }
                        }
                    }
                }
            }
        }

        return familiars;
    }

public static <T extends Entity & IFamiliar> T getFamiliar(LivingEntity owner, EntityType<T> type,
                                                               Predicate<T> pred) {
        T familiar = getEquippedFamiliar(owner, type, pred);
        if (familiar == null)
            familiar = getNearbyFamiliar(owner, type, pred);
        return familiar;
    }

@SubscribeEvent
    public static void familiarFriends(LivingChangeTargetEvent event) {
        LivingEntity entity = event.getEntity();
        LivingEntity target = event.getOriginalAboutToBeSetTarget();
        if (target == null || event.isCanceled())
            return;

        if (entity.is(OccultismTags.Entities.FRIENDS_AQUATIC) && target.hasEffect(OccultismEffects.AQUATIC_LORD))
            event.setCanceled(true);

        if (entity.is(OccultismTags.Entities.FRIENDS_FOREST) && target.hasEffect(OccultismEffects.FOREST_WHISPERER))
            event.setCanceled(true);

        if (entity.is(OccultismTags.Entities.FRIENDS_ABERRATIONS) && target.hasEffect(OccultismEffects.HERALD_ABERRATIONS))
            event.setCanceled(true);

        if (entity.is(OccultismTags.Entities.FRIENDS_NETHER) && target.hasEffect(OccultismEffects.NETHER_EMPEROR))
            event.setCanceled(true);
    }

private static void fairySave(LivingDeathEvent event) {
        LivingEntity entity = event.getEntity();

        if (event.getSource().is(DamageTypeTags.BYPASSES_INVULNERABILITY) || !(entity instanceof IFamiliar familiar)
                || entity.getType() == OccultismEntities.GUARDIAN_FAMILIAR.get()
                || entity.getType() == OccultismEntities.FAIRY_FAMILIAR.get())
            return;

        LivingEntity owner = familiar.getFamiliarOwner();

        if (owner == null || !FamiliarUtil.isFamiliarEnabled(owner, OccultismEntities.FAIRY_FAMILIAR.get()))
            return;

        FairyFamiliarEntity fairy = FamiliarUtil.getFamiliar(owner, OccultismEntities.FAIRY_FAMILIAR.get());

        if (fairy == null || !fairy.saveFamiliar(familiar))
            return;

        if (!fairy.isAddedToLevel()) {
            if (entity.hasEffect(OccultismEffects.OCCULT_UNDYING_COOLDOWN)) {
                return;
            } else {
                int i = fairy.hasBlacksmithUpgrade() ? 1 : 2;
                entity.addEffect(new MobEffectInstance(OccultismEffects.OCCULT_UNDYING_COOLDOWN, i * 20 * 20, 0));
            }
        }

        event.setCanceled(true);
        entity.setHealth(2);
        entity.addEffect(new MobEffectInstance(MobEffects.ABSORPTION, 20 * 5, 2));

        if (!owner.level().isClientSide())
            OccultismAdvancements.FAMILIAR.get().trigger(owner, Type.FAIRY_SAVE);
    }

private static void guardianUltimateSacrifice(LivingDeathEvent event) {
        if (event.getSource().is(DamageTypeTags.BYPASSES_INVULNERABILITY) || !(event.getEntity() instanceof Player player))
            return;

        if (!FamiliarUtil.isFamiliarEnabled(player, OccultismEntities.GUARDIAN_FAMILIAR.get()))
            return;

        GuardianFamiliarEntity guardian = FamiliarUtil.getFamiliar(player, OccultismEntities.GUARDIAN_FAMILIAR.get());
        if (guardian == null)
            return;

        if (!guardian.isAddedToLevel() && player.hasEffect(OccultismEffects.OCCULT_UNDYING_COOLDOWN)) {
            return;
        }

        if (!guardian.sacrifice())
            return;

        event.setCanceled(true);
        player.setHealth(1);
        player.removeAllEffects();
        player.addEffect(new MobEffectInstance(MobEffects.REGENERATION, 20 * 10, 1));
        player.addEffect(new MobEffectInstance(MobEffects.ABSORPTION, 20 * 5, 1));
        player.invulnerableTime = 30;
        if (!guardian.isAddedToLevel()) {
            int i = guardian.hasBlacksmithUpgrade() ? 6 : 7;
            int t = guardian.hasIesniumUpgrade() ? 10 : 20;
            i -= guardian.getLives();
            player.addEffect(new MobEffectInstance(OccultismEffects.OCCULT_UNDYING_COOLDOWN, i * 60 * t, 0, true, true));
        }
    }

private static void headlessStealHead(LivingDeathEvent event) {
        if (!(event.getSource().getEntity() instanceof Player player))
            return;

        if (!FamiliarUtil.isFamiliarEnabled(player, OccultismEntities.HEADLESS_FAMILIAR.get()))
            return;

        HeadlessFamiliarEntity headlesses = FamiliarUtil.getNearbyFamiliar(player,
                OccultismEntities.HEADLESS_FAMILIAR.get(), pred -> true);

        if (headlesses == null)
            return;

        if (event.getEntity().getType() == OccultismEntities.CTHULHU_FAMILIAR.get())
            OccultismAdvancements.FAMILIAR.get().trigger(player, Type.HEADLESS_CTHULHU_HEAD);

        headlesses.setHeadType(event.getEntity().getType());
    }

default InteractionResult familiarInteractLivingEntity(ItemStack stack, Player playerIn, LivingEntity target, InteractionHand hand) {
