            if (source.getEntity() != null) {
                if (Common.FIRENANDO_KILL.get() && source.getEntity().getUUID().equals(getOwner())) {
                    level().addFreshEntity(new ItemEntity(level(), getX(), getY(), getZ(), new ItemStack(ModItems.FIRENANDO_CHARM.get())));
