protected void onHitEntity(EntityHitResult p_37626_) {
        super.onHitEntity(p_37626_);
        if (!this.level.isClientSide) {
            float baseDamage = SpellConfig.NecroBoltDamage.get().floatValue() * WandUtil.damageMultiply();
            Entity entity = p_37626_.getEntity();
            Entity entity1 = this.getOwner();
            boolean flag;
            if (entity1 instanceof LivingEntity livingentity) {
                if (livingentity instanceof Mob mob){
                    if (mob.getAttribute(Attributes.ATTACK_DAMAGE) != null && mob.getAttributeValue(Attributes.ATTACK_DAMAGE) > 0){
                        baseDamage = (float) mob.getAttributeValue(Attributes.ATTACK_DAMAGE);
                    }
                }
                baseDamage += this.getExtraDamage();
                flag = entity.hurt(entity.damageSources().indirectMagic(this, livingentity), baseDamage);
                if (flag) {
                    if (entity.isAlive()) {
                        this.doEnchantDamageEffects(livingentity, entity);
                    } else {
                        if (entity instanceof Zombie) {
                            ServantUtil.convertZombies(entity, livingentity, true);
                        } else if (entity instanceof AbstractSkeleton) {
                            boolean wither = false;
                            if (livingentity instanceof Player player){
                                wither = SEHelper.hasResearch(player, ResearchList.BYGONE);
                            }
                            ServantUtil.convertSkeletons(entity, livingentity, wither, true);
                        } else if (entity instanceof Mob mob) {
                            boolean flag1 = ServantUtil.convertUndead(mob, livingentity, true, true);
                            if (!flag1) {
                                ServantUtil.infect(mob, livingentity, true, true);
                            }
                        }
                    }
                }
            } else {
                flag = entity.hurt(entity.damageSources().magic(), baseDamage);
            }

            if (flag && entity instanceof LivingEntity) {
                double x = this.getX();
                double z = this.getZ();
                if (entity1 != null){
                    x = entity1.getX();
                    z = entity1.getZ();
                }
                ((LivingEntity) entity).knockback(1.0F, x - entity.getX(), z - entity.getZ());
            }

        }
    }

@Override
    public void tick() {
        super.tick();
        this.setYRot(this.getYHeadRot());
        this.yBodyRot = this.getYRot();
        this.noPhysics = true;
        this.setNoGravity(true);

        ++this.life;
        if (!this.level.isClientSide) {
            if (!this.sentSpawnEvent) {
                this.level.broadcastEntityEvent(this, (byte)4);
                this.sentSpawnEvent = true;
            }
            if (this.life < 30) {
                Vec3 vector3d;
                if (this.getTarget() != null) {
                    vector3d = this.getTarget().getEyePosition(1.0F);
                    MobUtil.instaLook(this, this.getTarget());
                } else {
                    vector3d = this.getViewVector(1.0F);
                    MobUtil.instaLook(this, vector3d);
                }
                double dx = this.getX() - vector3d.x();
                double dy = this.getY() - vector3d.y();
                double dz = this.getZ() - vector3d.z();
                double d0 = Math.sqrt(dx * dx + dy * dy + dz * dz);
                double velocity = 2.0D;
                double xPower = -(dx / d0 * velocity * 0.2D);
                double yPower = -(dy / d0 * velocity * 0.2D);
                double zPower = -(dz / d0 * velocity * 0.2D);
                this.chargePos = new Vec3(xPower, yPower, zPower);
                this.keepYRot = this.getYRot();
                this.keepXRot = this.getXRot();
            } else {
                this.setYRot(this.keepYRot);
                this.setXRot(this.keepXRot);
                if (!this.sentAttackEvent) {
                    this.level.broadcastEntityEvent(this, (byte)5);
                    this.sentAttackEvent = true;
                }
                if (this.chargePos != null) {
                    this.setDeltaMovement(this.chargePos);
                }
                if (this.life <= 40) {
                    for (LivingEntity livingEntity : this.level.getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(1.0D))) {
                        if (!this.hitEntities.contains(livingEntity) && !MobUtil.areAllies(this.getOwner() != null ? this.getOwner() : this, livingEntity) && EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(livingEntity)) {
                            DamageSource damageSource = this.damageSources().mobAttack(this);
                            if (this.getOwner() != null){
                                damageSource = ModDamageSource.summonAttack(this, this.getOwner());
                            }
                            if (livingEntity.hurt(damageSource, AttributesConfig.BlackBeastDamage.get().floatValue())) {
                                this.hitEntities.add(livingEntity);
                            }
                        }
                    }
                } else {
                    this.setDeltaMovement(this.getDeltaMovement().scale(0.25D));
                }
            }
            if (this.life >= 70) {
                this.discard();
            }
        } else {
            if (this.life > 10 && this.life < 50 && this.alpha < 1.0F){
                this.alpha = Mth.clamp(this.alpha + 0.1F, 0.0F, 1.0F);
            }
            if (this.life >= 50){
                this.alpha = Mth.clamp(this.alpha - 0.05F, 0.0F, 1.0F);
            }
        }
    }

private void explode() {
        if (!this.level.isClientSide) {
            if (this.level instanceof ServerLevel serverLevel){
                ColorUtil colorUtil = new ColorUtil(0xff8905);
                serverLevel.sendParticles(new CircleExplodeParticleOption(colorUtil.red, colorUtil.green, colorUtil.blue, this.getExplosionPower(), 1), this.getX(), this.getY(), this.getZ(), 0, 0.0D, 0.0D, 0.0D, 0);
                serverLevel.sendParticles(new SphereExplodeParticleOption(colorUtil.red, colorUtil.green, colorUtil.blue, this.getExplosionPower(), 1), this.getX(), this.getY(), this.getZ(), 0, 0.0D, 0.0D, 0.0D, 0);
                for (int i = 0; i < 32; ++i) {
                    ColorUtil colorUtil1 = new ColorUtil(0xac9b8f);
                    serverLevel.sendParticles(ModParticleTypes.BIG_CULT_SPELL.get(), this.getRandomX(1.0F), this.getRandomY(), this.getRandomZ(1.0F), 0, colorUtil1.red, colorUtil1.green, colorUtil1.blue, 1.0F);
                    serverLevel.sendParticles(ModParticleTypes.BIG_FIRE_GROUND.get(), this.getRandomX(0.5F), this.getY(), this.getRandomZ(0.5F), 1, 0.0F, 0.0F, 0.0F, 0.0F);
                }
            }
            this.dead = true;
            new SpellExplosion(this.level, this.getTrueOwner() != null ? this.getTrueOwner() : this, this.damageSources().explosion(this, this.getTrueOwner() != null ? this.getTrueOwner() : this), this.getX(), this.getY(), this.getZ(), this.getExplosionPower(), 0);
            this.playSound(SoundEvents.GENERIC_EXPLODE, 4.0F, (1.0F + (this.level.getRandom().nextFloat() - this.level.getRandom().nextFloat()) * 0.2F) * 0.7F);
            this.discard();
        }
    }

public void aiStep() {
        super.aiStep();
        if (!this.isEmerging()){
            if (!this.isActivate()){
                this.setActivate(true);
                this.playSound(ModSounds.BOMB_LOAD.get(), 2.0F, 1.0F);
            }
            if (this.tickCount == MathHelper.secondsToTicks(1)){
