            }
        }
    }

public boolean canUse() {
            LivingEntity livingentity = this.mob.getTarget();
            if (livingentity != null && livingentity.isAlive()
                    && this.mob.hasLineOfSight(livingentity)
                    && livingentity.distanceTo(this.mob) <= this.attackRadius) {
                this.target = livingentity;
                return !this.mob.isEmerging()
                        && this.mob.getCurrentAnimation() != this.mob.getAnimationState("hold")
                        && this.mob.getCurrentAnimation() != this.mob.getAnimationState("burrow");
            } else {
                return false;
            }
        }

public void tick() {
            if (this.target != null) {
                this.mob.getLookControl().setLookAt(this.target, 30.0F, 30.0F);
                ++this.attackTime;
                if (this.attackTime == 1) {
                    this.mob.setAnimationState(SHOOT);
                } else if (this.attackTime == 10) {
                    this.mob.shootQuill(this.target);
                } else if (this.attackTime >= 25){
                    this.mob.setAnimationState(TARGET);
                    this.attackTime = -20;
                }
            }
        }

public void blowUp(Vec3 vec3) {
        AcidPool acidPool = new AcidPool(ModEntityType.ACID_POOL.get(), this.level);
        if (this.getOwner() instanceof LivingEntity livingEntity) {
            acidPool.setOwner(livingEntity);
        }
        acidPool.setColor(0xec67eb);
        acidPool.setWarmupColor(0xfdd4fb);
        acidPool.setRadius(2.0F);
        acidPool.setDamage(4.0F);
        acidPool.setDuration(60);
        acidPool.setPos(vec3);
        if (this.level.addFreshEntity(acidPool)) {
            this.playSound(SoundEvents.GLASS_BREAK, 2.0F, 1.0F);
            this.playSound(SoundEvents.ZOMBIE_BREAK_WOODEN_DOOR, 1.0F, 1.0F);
            this.playSound(ModSounds.BREW_GAS_ALT.get(), 2.0F, 1.0F);
        }
        this.discard();
    }

@Override
