protected void onHitEntity(EntityHitResult pResult) {
        super.onHitEntity(pResult);
        if (!this.level.isClientSide) {
            Entity target = pResult.getEntity();
            Entity owner = this.getOwner();
            boolean flag;
            float enchantment = this.getExtraDamage();
            int flaming = this.getFiery();
            if (owner instanceof LivingEntity livingentity) {
                flag = target.hurt(this.damageSources().indirectMagic(this, livingentity), this.getDamage() + enchantment);
                if (livingentity instanceof SkullLord){
                    if (target instanceof BoneLord){
                        flag = false;
                    }
                }
                if (flag) {
                    if (target.isAlive()) {
                        this.doEnchantDamageEffects(livingentity, target);
                        if (flaming != 0) {
                            target.setSecondsOnFire(5 * flaming);
                        }
                    } else {
                        livingentity.heal(1.0F);
                    }
                }
            } else {
                target.hurt(this.damageSources().magic(), this.getDamage());
            }
        }
    }

protected boolean canHitEntity(Entity pEntity) {
        if (this.getOwner() != null){
            if (pEntity == this.getOwner()){
                return false;
            }
            if (this.getOwner() instanceof Mob mob && mob.getTarget() == pEntity){
                return super.canHitEntity(pEntity);
            } else {
                if (MobUtil.areAllies(this.getOwner(), pEntity)){
                    return false;
                }
                if (pEntity instanceof IOwned owned0 && this.getOwner() instanceof IOwned owned1){
                    return !MobUtil.ownerStack(owned0, owned1);
                }
            }
        }
        if (this.isUpgraded()){
            if (pEntity instanceof AbstractHurtingProjectile){
                return false;
            }
        }
        return super.canHitEntity(pEntity);
    }

public void explode(){
        if (this.exploding || this.isRemoved()) {
            return;
        }
        this.exploding = true;
        if (!this.level.isClientSide) {
            Entity owner = this.getOwner();
            boolean flaming = this.getFiery() > 0;
            Explosion.BlockInteraction explodeMode = Explosion.BlockInteraction.KEEP;
            boolean damaging;
            if (owner instanceof Player || (owner instanceof IOwned iOwned && iOwned.getMasterOwner() instanceof Player)) {
                damaging = SpellConfig.HauntedSkullGriefing.get();
            } else {
                damaging = net.minecraftforge.event.ForgeEventFactory.getMobGriefingEvent(this.level, this);
            }
            if (!damaging) {
                flaming = false;
            }
            if (this.isDangerous()) {
                if (this.getOwner() instanceof Player) {
                    explodeMode = damaging ? Explosion.BlockInteraction.DESTROY : Explosion.BlockInteraction.KEEP;
                } else {
                    explodeMode = damaging ? Explosion.BlockInteraction.DESTROY : Explosion.BlockInteraction.KEEP;
                }
            }
            LootingExplosion.Mode lootMode = CuriosFinder.hasWanting(owner) ? LootingExplosion.Mode.LOOT : LootingExplosion.Mode.REGULAR;
            ExplosionUtil.lootExplode(this.level, this, this.getX(), this.getY(), this.getZ(), this.getExplosionPower(), flaming, explodeMode, lootMode);
            this.discard();
        }
    }

public boolean hurt(DamageSource source, float amount) {
        if (this.exploding || this.isRemoved()) {
            return false;
        } else if (this.isUpgraded()) {
            return false;
        } else {
            this.explode();
            this.markHurt();
            return !this.isInvulnerableTo(source);
        }
    }

public void findTarget(){
        if (this.getTarget() == null) {
            for (LivingEntity livingEntity : this.level.getEntitiesOfClass(LivingEntity.class, this.getBoundingBox())) {
                if (EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(livingEntity)) {
                    LivingEntity target = livingEntity;
                    if (target.isPassenger() && target.getVehicle() instanceof LivingEntity vehicle){
                        target = vehicle;
                    }
                    if (this.canHitEntity(target)) {
                        this.setTarget(target);
                    }
                }
            }
        }
    }

public void tangleTarget(){
        if (this.getTarget() != null
                && this.getTarget().isAlive()
                && !this.getTarget().getType().is(ModTags.EntityTypes.UNTANGLEABLE)
                && this.getTarget().canBeAffected(new MobEffectInstance(GoetyEffects.TANGLED.get()))){
            this.getTarget().setPos(this.position());
            this.getTarget().setDeltaMovement(Vec3.ZERO);
            this.getTarget().move(MoverType.SELF, Vec3.ZERO);
            this.getTarget().moveRelative(0.0F, Vec3.ZERO);
            if (this.level.isClientSide){
                ModNetwork.sendToServer(new CSetDeltaMovement(this.getTarget().getId(), 0.0D, 0.0D, 0.0D));
            } else {
                if (this.activeTick < 10){
                    ModNetwork.sentToTrackingEntityAndPlayer(this.getTarget(), new SRepositionPacket(this.getTarget().getId(), this.position().x, this.position().y, this.position().z));
                }
            }
            this.getTarget().addEffect(new MobEffectInstance(GoetyEffects.TANGLED.get(), 2, 0, false, false, false));
        }
    }

public void entangleTick(){
        if (this.activeTick == 1){
            this.burst();
        } else {
            if (this.activeTick < 5){
                this.findTarget();
            }
            if (this.activeTick < this.lifeSpan) {
                this.tangleTarget();
            } else if (this.activeTick == this.lifeSpan) {
                this.burrow();
            } else if (this.activeTick >= (this.lifeSpan + 20)){
                this.discard();
            }
        }
    }

protected boolean canHitEntity(Entity pEntity) {
        if (this.getOwner() != null){
            if (this.getOwner() instanceof Mob mob && mob.getTarget() == pEntity){
                return true;
            } else {
                if (MobUtil.areAllies(this.getOwner(), pEntity)){
                    return false;
                }
                if (this.getOwner() instanceof Enemy && pEntity instanceof Enemy){
                    return false;
                }
                if (pEntity instanceof IOwned owned0 && this.getOwner() instanceof IOwned owned1){
                    return !MobUtil.ownerStack(owned0, owned1);
                }
            }
        }
        return true;
    }

protected boolean canHitEntity(Entity pEntity) {
        if (pEntity instanceof ItemEntity) {
            return false;
        }
        if (this.getOwner() != null){
            if (this.getOwner() instanceof Mob mob && mob.getTarget() == pEntity){
                return super.canHitEntity(pEntity);
            } else {
                if (MobUtil.areAllies(this.getOwner(), pEntity)){
                    return false;
                }
                if (this.getOwner() instanceof Enemy && pEntity instanceof Enemy){
                    return false;
                }
                if (pEntity instanceof Projectile projectile && projectile.getOwner() == this.getOwner()){
                    return false;
                }
                if (pEntity instanceof IOwned owned0 && this.getOwner() instanceof IOwned owned1){
                    return !MobUtil.ownerStack(owned0, owned1);
                }
            }
        }
        return super.canHitEntity(pEntity);
    }

@Override
    public boolean canUse() {
        if (!this.entity.isFlying() && !this.entity.isTame()) {

            if (this.entity.level.getGameTime() % 4 == 0) // only update the list every 4 ticks
                list = this.entity.level.getEntitiesOfClass(Player.class, this.entity.getBoundingBox().inflate(this.avoidDistance, 6D, this.avoidDistance), EntitySelector.NO_CREATIVE_OR_SPECTATOR);

            if (list.isEmpty())
                return false;

            this.closestLivingEntity = list.get(0);
            Vec3 Vector3d = DefaultRandomPos.getPosAway(this.entity, 20, 7, new Vec3(this.closestLivingEntity.getX(), this.closestLivingEntity.getY(), this.closestLivingEntity.getZ()));

            if (Vector3d == null) {
                return false;
            } else if (this.closestLivingEntity.distanceToSqr(Vector3d) < this.closestLivingEntity.distanceToSqr(this.entity)) {
                return false;
            } else {
                this.path = this.entity.getNavigation().createPath(Vector3d.x, Vector3d.y, Vector3d.z, 0);
                return this.path != null;
            }

        } else {
            list = IAFMath.emptyPlayerEntityList;
            return false;
        }
    }

