@Override
    public void tick() {
        if (this.dragon.getOwner() != null) {
            final float dist = this.dragon.distanceTo(this.dragon.getOwner());
            if (dist > maxRange) {
                return;
            }
            if (dist > this.dragon.getBoundingBox().getSize() && (!this.dragon.isFlying() && !this.dragon.isHovering() || !dragon.isAllowedToTriggerFlight())) {
                if (previousPosition == null || previousPosition.distSqr(this.dragon.getOwner().blockPosition()) > 9) {
                    this.dragon.getNavigation().moveTo(this.dragon.getOwner(), 1F);
                    previousPosition = this.dragon.getOwner().blockPosition();
                }
            }
            if ((dist > 30F || this.dragon.getOwner().getY() - this.dragon.getY() > 8) && !this.dragon.isFlying() && !this.dragon.isHovering() && dragon.isAllowedToTriggerFlight()) {
                this.dragon.setHovering(true);
                this.dragon.setInSittingPose(false);
                this.dragon.setOrderedToSit(false);
                this.dragon.flyTicks = 0;
            }
        }

    }

@Override
    public boolean canUse() {
        return this.dragon.canMove() && this.dragon.lookingForRoostAIFlag
            && (dragon.getTarget() == null || !dragon.getTarget().isAlive())
            && dragon.getRestrictCenter() != null
            && DragonUtils.isInHomeDimension(dragon)
            && dragon.getDistanceSquared(Vec3.atCenterOf(dragon.getRestrictCenter())) > dragon.getBbWidth()
            * dragon.getBbWidth();
    }

@Override
    public void tick() {
        dragon.getNavigation().stop();
        dragon.setTarget(null);
        double x = dragon.getX();
        double y = dragon.getY();
        double z = dragon.getZ();
        double speed = 1.8F * dragon.getFlightSpeedModifier();
        Vec3 lookVec = player.getLookAngle();
        if (player.zza < 0) {
            lookVec = lookVec.yRot((float) Math.PI);
        } else if (player.xxa > 0) {
            lookVec = lookVec.yRot((float) Math.PI * 0.5f);
        } else if (player.xxa < 0) {
            lookVec = lookVec.yRot((float) Math.PI * -0.5f);
        }
        if (Math.abs(player.xxa) > 0.0) {
            speed *= 0.25D;
        }
        if (player.zza < 0.0) {
            speed *= 0.15D;
        }
        if (dragon.isGoingUp()) {
            lookVec = lookVec.add(0, 1, 0);
        } else if (dragon.isGoingDown()) {
            lookVec = lookVec.add(0, -1, 0);
        }
        if (player.xxa != 0 || player.zza != 0 || (dragon.fliesLikeElytra())) {
            x += lookVec.x * 10;
            z += lookVec.z * 10;
        }
        if ((dragon.isFlying() || hovering()) && (dragon.fliesLikeElytra() || dragon.isGoingUp() || dragon.isGoingDown())) {
            y += lookVec.y * dragon.getYSpeedMod();
        }
        if (dragon.fliesLikeElytra() && lookVec.y == -1 || !(dragon.isFlying() || hovering()) && !dragon.isOnGround()) {
            y -= 1;
        }
        dragon.getMoveControl().setWantedPosition(x, y, z, speed);
    }

