@Override
	public void onKillEntity(EntityLivingBase victim){
		// If the silverfish has a summoner, this is actually called from Wizardry's event handler rather than by
		// Minecraft itself, because the damagesource being changed causes it not to get called.
		if(!this.world.isRemote && generation < MAX_GENERATIONS){
			// Summons 1-4 more silverfish
			int alliesToSummon = rand.nextInt(4) + 1;

			for(int i = 0; i < alliesToSummon; i++){
				EntitySilverfishMinion silverfish = new EntitySilverfishMinion(this.world);
				silverfish.setPosition(victim.posX, victim.posY, victim.posZ);
				silverfish.setCaster(this.getCaster());
				silverfish.setLifetime(this.getLifetime());
				silverfish.generation = this.generation + 1;
				this.world.spawnEntity(silverfish);
			}
		}
	}

private boolean selectMinionTarget(EntityPlayer player, World world){

		RayTraceResult rayTrace = RayTracer.standardEntityRayTrace(world, player, 16, false);

		if(rayTrace != null && EntityUtils.isLiving(rayTrace.entityHit)){

			EntityLivingBase entity = (EntityLivingBase)rayTrace.entityHit;

			// Sets the selected minion's target to the right-clicked entity
			if(player.isSneaking() && WizardData.get(player) != null && WizardData.get(player).selectedMinion != null){

				ISummonedCreature minion = WizardData.get(player).selectedMinion.get();

				if(minion instanceof EntityLiving && minion != entity){
					// There is now only the new AI! (which greatly improves things)
					((EntityLiving)minion).setAttackTarget(entity);
					// Deselects the selected minion
					WizardData.get(player).selectedMinion = null;
					return true;
				}
			}
		}

		return false;
	}

@Override
	public void onUpdate(){

		super.onUpdate();

		if(ticksExisted == 1 && world.isRemote){
			Wizardry.proxy.playMovingSound(this, WizardrySounds.ENTITY_FORCEFIELD_AMBIENT, WizardrySounds.SPELLS, 0.5f, 1, true);
		}

		// New forcefield repulsion system:
		// Searches for all entities near the forcefield and determines where they will be next tick.
		// If they will be inside the forcefield next tick, sets their position and velocity such that they appear to
		// bounce off the forcefield and creates impact particle effects and sounds where they hit it

		List<Entity> targets = EntityUtils.getEntitiesWithinRadius(radius + SEARCH_BORDER_SIZE, posX, posY, posZ, world, Entity.class);

		targets.remove(this);
		targets.removeIf(t -> t instanceof EntityXPOrb); // Gets annoying since they're attracted to the player

		// Ring of the defender allows players to shoot through their own forcefields
		if(getCaster() instanceof EntityPlayer && ItemArtefact.isArtefactActive((EntityPlayer)getCaster(),
				WizardryItems.ring_defender)){
			targets.removeIf(t -> t instanceof EntityMagicArrow && !this.isValidTarget(((EntityMagicArrow)t).getCaster())
								|| t instanceof EntityThrowable && !this.isValidTarget(((EntityThrowable)t).getThrower())
								|| t instanceof EntityArrow && !this.isValidTarget(((EntityArrow)t).shootingEntity));
		}

		for(Entity target : targets){

			if(this.isValidTarget(target)){

				Vec3d currentPos = Arrays.stream(GeometryUtils.getVertices(target.getEntityBoundingBox()))
						.min(Comparator.comparingDouble(v -> v.distanceTo(this.getPositionVector())))
						.orElse(target.getPositionVector()); // This will never happen, it's just here to make the compiler happy

				double currentDistance = target.getDistance(this);

				// Estimate the target's position next tick
				// We have to assume the same vertex is closest or the velocity will be wrong
				Vec3d nextTickPos = currentPos.add(target.motionX, target.motionY, target.motionZ);
				double nextTickDistance = nextTickPos.distanceTo(this.getPositionVector());

				boolean flag;

				if(EntityUtils.isLiving(target)){
					// Non-allied living entities shouldn't be inside at all
					flag = nextTickDistance <= radius;
				}else{
					// Non-living entities will bounce off if they hit the forcefield within the next tick...
					flag = (currentDistance > radius && nextTickDistance <= radius) // ...from the outside...
							|| (currentDistance < radius && nextTickDistance >= radius); // ...or from the inside
				}

				if(flag){

					// Ring of interdiction
					if(getCaster() instanceof EntityPlayer && ItemArtefact.isArtefactActive((EntityPlayer)getCaster(),
							WizardryItems.ring_interdiction) && EntityUtils.isLiving(target)){
						target.attackEntityFrom(MagicDamage.causeIndirectMagicDamage(this, getCaster(),
								MagicDamage.DamageType.MAGIC), 1);
					}

					Vec3d targetRelativePos = currentPos.subtract(this.getPositionVector());

					double nudgeVelocity = this.contains(target) ? -0.1 : 0.1;
					if(EntityUtils.isLiving(target)) nudgeVelocity = 0.25;
					Vec3d extraVelocity = targetRelativePos.normalize().scale(nudgeVelocity);

					//Moved up the check by "19" so that way allied players aren't being moved out of the forcefield because
					//allied players aren't synced to client like minions. Minions are only synced because it's saved to their
					//entity data which is synced in their serialize/deserialize methods
					if(!world.isRemote){
						// ...make it bounce off!

						target.motionX = target.motionX * -BOUNCINESS + extraVelocity.x;
						target.motionY = target.motionY * -BOUNCINESS + extraVelocity.y;
						target.motionZ = target.motionZ * -BOUNCINESS + extraVelocity.z;

						// Prevents the forcefield bouncing things into the floor
						if(target.onGround && target.motionY < 0) target.motionY = 0.1;

						// How far the target needs to move towards the centre (negative means away from the centre)
						double distanceTowardsCentre = -(targetRelativePos.length() - radius) - (radius - nextTickDistance);
						Vec3d targetNewPos = target.getPositionVector().add(targetRelativePos.normalize().scale(distanceTowardsCentre));
						target.setPosition(targetNewPos.x, targetNewPos.y, targetNewPos.z);

						world.playSound(target.posX, target.posY, target.posZ, WizardrySounds.ENTITY_FORCEFIELD_DEFLECT,
								WizardrySounds.SPELLS, 0.3f, 1.3f, false);


						// Player motion is handled on that player's client so needs packets
						if(target instanceof EntityPlayerMP){
							((EntityPlayerMP)target).connection.sendPacket(new SPacketEntityVelocity(target));
						}

						if (this.ticksExisted % 5 == 0) {
							this.lifetime = (int) (lifetime * 0.99);
						}

					}else{

						//This is a super lazy way to make sure the visual isn't playing for players and probably won't display the visual
						//for players if their velocity towards the forcefield is high. But it prevents the visual being spammed when ally player
						//is in forcefield so it's fine #19
						if(target instanceof EntityPlayer && target.getPositionVector().distanceTo(this.getPositionVector()) < this.getRadius()) return;

						Vec3d relativeImpactPos = targetRelativePos.normalize().scale(radius);

						float yaw = (float)Math.atan2(relativeImpactPos.x, -relativeImpactPos.z);
						float pitch = (float)Math.asin(relativeImpactPos.y/ radius);

						ParticleBuilder.create(Type.FLASH).pos(this.getPositionVector().add(relativeImpactPos))
						.time(6).face((float)(yaw * 180/Math.PI), (float)(pitch * 180/Math.PI))
						.clr(0.9f, 0.95f, 1).spawn(world);

						for(int i = 0; i < 12; i++){

							float yaw1 = yaw + 0.3f * (rand.nextFloat() - 0.5f) - (float)Math.PI/2;
							float pitch1 = pitch + 0.3f * (rand.nextFloat() - 0.5f);

							float brightness = rand.nextFloat();

							double r = radius + 0.05;
							double x = this.posX + r * MathHelper.cos(yaw1) * MathHelper.cos(pitch1);
							double y = this.posY + r * MathHelper.sin(pitch1);
							double z = this.posZ + r * MathHelper.sin(yaw1) * MathHelper.cos(pitch1);

							ParticleBuilder.create(Type.DUST).pos(x, y, z).time(6 + rand.nextInt(6))
							.face((float)(yaw1 * 180/Math.PI) + 90, (float)(pitch1 * 180/Math.PI)).scale(1.5f)
							.clr(0.7f + 0.3f * brightness, 0.85f + 0.15f * brightness, 1).spawn(world);
						}
					}
				}
			}
		}
	}

@SubscribeEvent
	public static void onLivingAttackEvent(LivingAttackEvent event){

		if(event.getSource().getTrueSource() instanceof EntityPlayer && event.getSource().isProjectile()
				&& ItemArtefact.isArtefactActive((EntityPlayer)event.getSource().getTrueSource(), WizardryItems.ring_defender)){
				return; // Players wearing a ring of the defender can shoot stuff as normal, so don't cancel the event
		}

		if(!event.getSource().isUnblockable() && event.getSource().getTrueSource() != null && event.getEntityLiving() != null
			&& !(event.getSource().getImmediateSource() instanceof EntityForcefield)){ // If the damage was from a forcefield that's ok
			// This condition will be false if both entities are outside a forcefield or both are in the same one
			if(getSurroundingForcefield(event.getEntityLiving()) != getSurroundingForcefield(event.getSource().getTrueSource())){
				event.setCanceled(true);
			}
		}
	}

@Override
	public void onUpdate(){

		super.onUpdate();

		if(lifetime - ticksExisted > 10 && spawnTimer-- == 0){

			this.playSound(WizardrySounds.ENTITY_ZOMBIE_SPAWNER_SPAWN, 1, 1);

			if(!world.isRemote){

				EntityZombieMinion zombie = spawnHusks ? new EntityHuskMinion(world) : new EntityZombieMinion(world);

				zombie.setPosition(this.posX + (rand.nextDouble() * 2 - 1) * MAX_NUDGE_DISTANCE, this.posY,
						this.posZ + (rand.nextDouble() * 2 - 1) * MAX_NUDGE_DISTANCE);
				zombie.setCaster(this.getCaster());
				// Modifier implementation
				// Attribute modifiers are pretty opaque, see https://minecraft.gamepedia.com/Attribute#Modifiers
				zombie.setLifetime(Spells.zombie_apocalypse.getProperty(SpellMinion.MINION_LIFETIME).intValue());
				IAttributeInstance attribute = zombie.getEntityAttribute(SharedMonsterAttributes.ATTACK_DAMAGE);
				attribute.applyModifier(new AttributeModifier(SpellMinion.POTENCY_ATTRIBUTE_MODIFIER,
						damageMultiplier - 1, EntityUtils.Operations.MULTIPLY_CUMULATIVE));
				zombie.setHealth(zombie.getMaxHealth()); // Need to set this because we may have just modified the value
				zombie.hurtResistantTime = 30; // Prevent fall damage
				zombie.hideParticles(); // Hide spawn particles or they pop out the top of the hidden box

				world.spawnEntity(zombie);
			}

			spawnTimer += Spells.zombie_apocalypse.getProperty(ZombieApocalypse.MINION_SPAWN_INTERVAL).intValue() + rand.nextInt(20);
		}

		if(world.isRemote){

			float b = 0.15f;

			for(double r = 1.5; r < 4; r += 0.2){
				ParticleBuilder.create(Type.CLOUD).clr(b-=0.02, 0, 0).pos(posX, posY - 0.3, posZ).scale(0.5f / (float)r)
						.spin(r, 0.02/r * (1 + world.rand.nextDouble())).spawn(world);
			}

		}

	}

@Override
	public void onSuccessfulAttack(EntityLivingBase target){

		target.motionY += 0.2;
		target.motionX += this.getLookVec().x * 0.2;
		target.motionZ += this.getLookVec().z * 0.2;

		if(!target.world.isRemote) target.addPotionEffect(new PotionEffect(WizardryPotions.frost, 300, 0));

		this.applyEnchantments(this, target);

		this.playSound(WizardrySounds.ENTITY_ICE_GIANT_ATTACK, 1.0F, 1.0F);
	}

@Override
	public void onLivingUpdate(){

		// Makes the phoenix hover.
		Integer floorLevel = BlockUtils.getNearestFloor(world, new BlockPos(this), 4);

		if(floorLevel == null || this.posY - floorLevel > 3){
			this.motionY = -0.1;
		}else if(this.posY - floorLevel < 2){
			this.motionY = 0.1;
		}else{
			this.motionY = 0.0;
		}

		// Living sound
		if(this.rand.nextInt(24) == 0){
			this.playSound(WizardrySounds.ENTITY_PHOENIX_BURN, 1.0F + this.rand.nextFloat(),
					this.rand.nextFloat() * 0.7F + 0.3F);
		}

		// Flapping sound effect
		if(this.ticksExisted % 22 == 0){
			this.playSound(WizardrySounds.ENTITY_PHOENIX_FLAP, 1.0F, 1.0f);
		}

		for(int i = 0; i < 2; i++){
			this.world.spawnParticle(EnumParticleTypes.FLAME,
					this.posX + (this.rand.nextDouble() - 0.5D) * (double)this.width,
					this.posY + this.height / 2 + this.rand.nextDouble() * (double)this.height / 2,
					this.posZ + (this.rand.nextDouble() - 0.5D) * (double)this.width, 0.0D, -0.1D, 0.0D);
		}

		// Adding this allows the phoenix to attack despite being in the air. However, for some strange reason
		// it will only attack when within about 3 blocks of the ground. Any higher and it just sits there, not even
		// attempting to find targets.

		this.onGround = true;

		super.onLivingUpdate();
	}

public boolean findTarget() {
		LivingEntity target = getTargetEntity();
		if (target != null) {
			if (target.isAlive()) {
				return true;
			} else {
				target = null;
				setTarget(null);
			}
		}

		double range = 12;
		AABB bounds = new AABB(getX() - range, getY() - range, getZ() - range, getX() + range, getY() + range, getZ() + range);
		DamageSource source = this.getDamageSource();
		Predicate<Entity> vulnerableTo = e -> !e.isInvulnerableTo(source);
		List<? extends LivingEntity> entities;
		if (isEvil()) {
			entities = level().getEntitiesOfClass(Player.class, bounds,
					EntitySelector.LIVING_ENTITY_STILL_ALIVE.and(vulnerableTo));
		} else {
			Entity owner = getOwner();
			Predicate<Entity> pred = EntitySelector.LIVING_ENTITY_STILL_ALIVE
					.and(targetPredicate(owner)).and(vulnerableTo);
			entities = level().getEntitiesOfClass(LivingEntity.class, bounds, pred);
		}

		if (!entities.isEmpty()) {
			target = entities.get(level().random.nextInt(entities.size()));
			setTarget(target);
		}

		return target != null;
	}

public static boolean shouldTarget(Entity owner, LivingEntity e) {
		// always defend yourself
		if (e instanceof Mob mob && isHostile(owner, mob.getTarget())) {
			return true;
		}
		// don't target tamed creatures...
		if (e instanceof TamableAnimal animal && animal.isTame() || e instanceof AbstractHorse horse && horse.isTamed()) {
			return false;
		}

		// ...but other mobs die
		return e instanceof Enemy;
	}

public static boolean isHostile(Entity owner, Entity attackTarget) {
		// if the owner can attack the target thru PvP...
		if (owner instanceof Player ownerPlayer && attackTarget instanceof Player targetedPlayer && ownerPlayer.canHarmPlayer(targetedPlayer)) {
			// ... then only defend self
			return owner == attackTarget;
		}
		// otherwise, kill any player-hostiles
		return attackTarget instanceof Player;
	}

@Override
	public void tick() {
		double lastTickPosX = this.xOld;
		double lastTickPosY = this.yOld;
		double lastTickPosZ = this.zOld;

		super.tick();

		if (!level().isClientSide && (!findTarget() || time > 40)) {
			discard();
			return;
		}

		boolean evil = isEvil();
		Vec3 thisVec = VecHelper.fromEntityCenter(this);
		Vec3 oldPos = new Vec3(lastTickPosX, lastTickPosY, lastTickPosZ);
		Vec3 diff = thisVec.subtract(oldPos);
		Vec3 step = diff.normalize().scale(0.05);
		int steps = (int) (diff.length() / step.length());
		Vec3 particlePos = oldPos;

		SparkleParticleData data = evil ? SparkleParticleData.corrupt(0.8F, 1F, 0.0F, 1F, 2)
				: SparkleParticleData.sparkle(0.8F, 1F, 0.4F, 1F, 2);
		for (int i = 0; i < steps; i++) {
			level().addParticle(data, particlePos.x, particlePos.y, particlePos.z, 0, 0, 0);

			if (level().random.nextInt(steps) <= 1) {
				level().addParticle(data, particlePos.x + (Math.random() - 0.5) * 0.4, particlePos.y + (Math.random() - 0.5) * 0.4, particlePos.z + (Math.random() - 0.5) * 0.4, 0, 0, 0);
			}

			particlePos = particlePos.add(step);
		}

		LivingEntity target = getTargetEntity();
		if (target != null) {
			if (lockY == Integer.MIN_VALUE) {
				lockX = target.getX();
				lockY = target.getY();
				lockZ = target.getZ();
			}

			Vec3 targetVec = evil ? new Vec3(lockX, lockY, lockZ) : VecHelper.fromEntityCenter(target);
			Vec3 diffVec = targetVec.subtract(thisVec);
			Vec3 motionVec = diffVec.normalize().scale(evil ? 0.5 : 0.6);
			setDeltaMovement(motionVec);
			if (time < 10) {
				setDeltaMovement(getDeltaMovement().x(), Math.abs(getDeltaMovement().y()), getDeltaMovement().z());
			}

			List<LivingEntity> targetList = level().getEntitiesOfClass(LivingEntity.class, new AABB(getX() - 0.5, getY() - 0.5, getZ() - 0.5, getX() + 0.5, getY() + 0.5, getZ() + 0.5));
			if (targetList.contains(target)) {
				target.hurt(this.getDamageSource(), evil ? 12 : 7);
				discard();
			}

			if (evil && diffVec.length() < 1) {
				discard();
			}
		}

		time++;
	}

private DamageSource getDamageSource() {
		Entity owner = this.getOwner();
		if (owner instanceof LivingEntity livingOwner) {
			return owner instanceof Player playerOwner
					? damageSources().playerAttack(playerOwner)
					: damageSources().mobAttack(livingOwner);
		} else {
			return damageSources().generic();
		}
	}

public void setProps(LivingEntity target, LivingEntity summoner, int type, float damage) {
		setTarget(target);
		this.summoner = summoner;
		this.damage = damage;
		setPixieType(type);
	}

@Override
	protected void customServerAiStep() {
		LivingEntity target = getTarget();
		if (target != null) {
			double d0 = target.getX() + target.getBbWidth() / 2 - getX();
			double d1 = target.getY() + target.getBbHeight() / 2 - getY();
			double d2 = target.getZ() + target.getBbWidth() / 2 - getZ();
			double d3 = d0 * d0 + d1 * d1 + d2 * d2;

			float mod = 0.45F;
			if (getPixieType() == 1) {
				mod = 0.1F;
			}

			setDeltaMovement(d0 / d3 * mod, d1 / d3 * mod, d2 / d3 * mod);

			if (Math.sqrt(d3) < 1F) {
				if (summoner != null) {
					if (summoner instanceof Player player) {
						target.hurt(damageSources().playerAttack(player), damage);
					} else {
						target.hurt(damageSources().mobAttack(summoner), damage);
					}
				} else {
					target.hurt(damageSources().mobAttack(this), damage);
				}
				if (effect != null && !(target instanceof Player)) {
					target.addEffect(effect);
				}
				discard();
			}
		}

		yBodyRot = -((float) Math.atan2(getDeltaMovement().x(), getDeltaMovement().z()))
				* 180.0F / (float) Math.PI;
		setYRot(yBodyRot);
	}

@Override
	public boolean isInvulnerableTo(@NotNull DamageSource source) {
		if (getPixieType() == 0 && source.getEntity() == summoner) {
			return true;
		}

		if (getPixieType() == 1 && !(source.getEntity() instanceof Player)) {
			return true;
		}

		return super.isInvulnerableTo(source);
	}

@Override
	public void baseTick() {
		super.baseTick();

		if (!level().isClientSide
				&& (getTarget() == null || tickCount > 200)) {
			discard();
		}

		boolean dark = getPixieType() == 1;
		if (level().isClientSide) {
			for (int i = 0; i < 4; i++) {
				float r = dark ? 0.1F : 1F;
				float g = dark ? 0.025F : 0.25F;
				float b = dark ? 0.09F : 0.9F;
				SparkleParticleData data = SparkleParticleData.sparkle(0.1F + (float) Math.random() * 0.25F, r, g, b, 12);
				level().addParticle(data, getX() + (Math.random() - 0.5) * 0.25, getY() + 0.5 + (Math.random() - 0.5) * 0.25, getZ() + (Math.random() - 0.5) * 0.25, 0, 0, 0);
			}
		}
	}

public static boolean isValidTarget(Entity attacker, Entity target){

		// Owned entities inherit their owner's allies
		if(attacker instanceof IEntityOwnable && !isValidTarget(((IEntityOwnable)attacker).getOwner(), target)) return false;

		// Always return false if the target is null
		if(target == null) return false;

		// Always return true if the attacker is null - this must be after the target null check!
		if(attacker == null) return true;

		// Teammates are allies
		if(attacker.isOnSameTeam(target)) return false;

		// Tests whether the target is the attacker
		if(target == attacker) return false;

		// I really shouldn't need to do this, but fake players seem to break stuff...
		if(target instanceof FakePlayer) return false;

		// Use a positive check for these rather than a negative check for monsters, because we only want mobs
		// that are definitely passive
		if(Wizardry.settings.passiveMobsAreAllies && (target.isCreatureType(EnumCreatureType.AMBIENT, false)
				|| target.isCreatureType(EnumCreatureType.CREATURE, false)
				|| target.isCreatureType(EnumCreatureType.WATER_CREATURE, false))){
			return false;
		}

		// Tests whether the target is a creature that was summoned by the attacker
//		if(target instanceof ISummonedCreature && ((ISummonedCreature)target).getCaster() == attacker){
//			return false;
//		}

		// Tests whether the target is a creature that was summoned/tamed (or is otherwise owned) by the attacker
		if(target instanceof IEntityOwnable && ((IEntityOwnable)target).getOwner() == attacker){
			return false;
		}

		// Tests whether the target is a creature that was summoned/tamed (or is otherwise owned) by the attacker
		if(target instanceof IEntityOwnable && attacker instanceof EntityLiving && !(((EntityLiving)attacker).getRevengeTarget() == ((IEntityOwnable)target).getOwner() || ((EntityLiving)attacker).getAttackTarget() == ((IEntityOwnable)target).getOwner())){
			return false;
		}

		// Tests whether the target is a creature that was mind controlled by the attacker
		if(target instanceof EntityLiving && ((EntityLivingBase)target).isPotionActive(WizardryPotions.mind_control)){

			NBTTagCompound entityNBT = target.getEntityData();

			if(entityNBT != null && entityNBT.hasUniqueId(MindControl.NBT_KEY)){
				if(attacker == EntityUtils.getEntityByUUID(target.world,
						entityNBT.getUniqueId(MindControl.NBT_KEY))){
					return false;
				}
			}
		}

		// Ally section
		if(attacker instanceof EntityPlayer && WizardData.get((EntityPlayer)attacker) != null){

			if(target instanceof EntityPlayer){
				// Tests whether the target is an ally of the attacker
				if(WizardData.get((EntityPlayer)attacker).isPlayerAlly((EntityPlayer)target)){
					return false;
				}

//			}else if(target instanceof ISummonedCreature){
//				// Tests whether the target is a creature that was summoned by an ally of the attacker
//				if(((ISummonedCreature)target).getCaster() instanceof EntityPlayer && WizardData.get((EntityPlayer)attacker)
//								.isPlayerAlly((EntityPlayer)((ISummonedCreature)target).getCaster())){
//					return false;
//				}

			}else if(target instanceof IEntityOwnable){
				// Tests whether the target is a creature that was summoned/tamed by an ally of the attacker
				if(isOwnerAlly((EntityPlayer)attacker, (IEntityOwnable)target)) return false;

			}else if(target instanceof EntityLiving && ((EntityLivingBase)target).isPotionActive(WizardryPotions.mind_control)){
				// Tests whether the target is a creature that was mind controlled by an ally of the attacker
				NBTTagCompound entityNBT = target.getEntityData();

				if(entityNBT != null && entityNBT.hasKey(MindControl.NBT_KEY)){

					Entity controller = EntityUtils.getEntityByUUID(target.world, entityNBT.getUniqueId(MindControl.NBT_KEY));

					if(controller instanceof EntityPlayer && WizardData.get((EntityPlayer)attacker).isPlayerAlly((EntityPlayer)controller)){
						return false;
					}
				}
			}
		}

		// Addon predicate registry — only evaluated at the root of the ownership recursion (i.e. when the attacker is
		// not itself an IEntityOwnable). Owned attackers already delegate upward via the recursive call at the top of
		// this method, so skipping them here ensures each logical query fires the predicates exactly once.
		if(!validTargetPredicates.isEmpty() && !(attacker instanceof IEntityOwnable)){
			for(BiPredicate<Entity, Entity> predicate : validTargetPredicates){
				if(predicate.test(attacker, target)) return false;
			}
		}

		return true;
	}

public static boolean isAllied(EntityLivingBase allyOf, EntityLivingBase possibleAlly){

        if (allyOf == null || possibleAlly == null) {
            return false;
        }

		// Owned entities inherit their owner's allies
		if(allyOf instanceof IEntityOwnable){
			Entity owner = ((IEntityOwnable)allyOf).getOwner();
			if(owner instanceof EntityLivingBase && (owner == possibleAlly || isAllied((EntityLivingBase)owner, possibleAlly))) return true;
		}

		if(allyOf instanceof EntityPlayer && possibleAlly instanceof EntityPlayer
				&& isPlayerAlly((EntityPlayer)allyOf, (EntityPlayer)possibleAlly)){
			return true;
		}

		if(possibleAlly instanceof IEntityOwnable){
			IEntityOwnable pet = (IEntityOwnable)possibleAlly;
			if(pet.getOwner() == allyOf) return true;
			if(allyOf instanceof EntityPlayer && isOwnerAlly((EntityPlayer)allyOf, pet)) return true;
		}

		if(possibleAlly.isOnSameTeam(allyOf)) {
			return true;
		}

		// Check if the possibleAlly is mind controlled by the allyOf entity
		if(possibleAlly instanceof EntityLiving && possibleAlly.isPotionActive(WizardryPotions.mind_control)){
			NBTTagCompound entityNBT = possibleAlly.getEntityData();

			if(entityNBT != null && entityNBT.hasUniqueId(MindControl.NBT_KEY)){
				Entity controller = EntityUtils.getEntityByUUID(possibleAlly.world, entityNBT.getUniqueId(MindControl.NBT_KEY));
				return controller == allyOf;
			}
		}

		// Addon predicate registry — runs after all built-in rules; additive only.
		if(!allyPredicates.isEmpty()){
			for(BiPredicate<EntityLivingBase, EntityLivingBase> predicate : allyPredicates){
				if(predicate.test(allyOf, possibleAlly)) return true;
			}
		}

		return false;
	}

public static boolean isOwnerAlly(EntityPlayer allyOf, IEntityOwnable ownable){
		WizardData data = WizardData.get(allyOf);
		if(data == null) return false;
		Entity owner = ownable.getOwner();
		if(owner == null) return data.isPlayerAlly(ownable.getOwnerId()); // offline owner
		if(owner instanceof EntityPlayer) return data.isPlayerAlly((EntityPlayer)owner);
		if(owner instanceof IEntityOwnable) return isOwnerAlly(allyOf, (IEntityOwnable)owner); // recurse
		return false;
	}

@SubscribeEvent
	public static void onLivingAttackEvent(LivingAttackEvent event){

		if(event.getSource() != null && event.getSource().getTrueSource() instanceof EntityPlayer
				&& event.getSource() instanceof IElementalDamage){

			if(event.getEntity() instanceof EntityPlayer){
				// Prevents any magic damage to allied players if friendly fire is disabled for players
				if(Wizardry.settings.friendlyFire.blockPlayers && isPlayerAlly((EntityPlayer)event.getSource().getTrueSource(), (EntityPlayer)event.getEntity())){
					event.setCanceled(true);
				}
			}else{
				// Prevents any magic damage to entities owned by allied players if friendly fire is disabled for owned creatures
				// Since we're dealing with players separately we might as well just use isAllied
				if(Wizardry.settings.friendlyFire.blockOwned && isAllied((EntityPlayer)event.getSource().getTrueSource(), event.getEntityLiving())){
					event.setCanceled(true);
				}
			}
		}
	}

@Override
	public boolean shouldExecute(){

		EntityLivingBase entitylivingbase = this.attacker.getAttackTarget();

		if(entitylivingbase == null){
			return false;
		}else{
			this.target = entitylivingbase;
			return true;
		}
	}

@Override
	public void resetTask(){
		this.target = null;
		this.seeTime = 0;
		this.cooldown = -1;
		this.setContinuousSpellAndNotify(Spells.none, new SpellModifiers());
		this.continuousSpellTimer = 0;
	}

@Override
	public void updateTask(){

		// Only executed server side.

		double distanceSq = this.attacker.getDistanceSq(this.target.posX, this.target.posY,
				this.target.posZ);
		boolean targetIsVisible = this.attacker.getEntitySenses().canSee(this.target);

		if(targetIsVisible){
			++this.seeTime;
		}else{
			this.seeTime = 0;
		}

		if(distanceSq <= (double)this.maxAttackDistance && this.seeTime >= 20){
			this.attacker.getNavigator().clearPath();
		}else{
			this.attacker.getNavigator().tryMoveToEntityLiving(this.target, this.speed);
		}

		this.attacker.getLookHelper().setLookPositionWithEntity(this.target, 30.0F, 30.0F);

		if(this.continuousSpellTimer > 0){

			this.continuousSpellTimer--;

			// If the target goes out of range or out of sight...
			if(distanceSq > (double)this.maxAttackDistance || !targetIsVisible
			// ...or the spell is cancelled via events...
					|| MinecraftForge.EVENT_BUS
							.post(new SpellCastEvent.Tick(Source.NPC, attacker.getContinuousSpell(), attacker,
									attacker.getModifiers(), this.continuousSpellDuration - this.continuousSpellTimer))
					// ...or the spell no longer succeeds...
					|| !attacker.getContinuousSpell().cast(attacker.world, attacker, EnumHand.MAIN_HAND,
							this.continuousSpellDuration - this.continuousSpellTimer, target, attacker.getModifiers())
					// ...or the time has elapsed...
					|| this.continuousSpellTimer == 0){

				// ...reset the continuous spell timer and start the cooldown.
				this.continuousSpellTimer = 0;
				this.cooldown = attacker.getContinuousSpell().getCooldown() + this.baseCooldown;
				setContinuousSpellAndNotify(Spells.none, new SpellModifiers());
				return;

			}else if(this.continuousSpellDuration - this.continuousSpellTimer == 1){
				// On the first tick, if the spell did succeed, fire SpellCastEvent.Post.
				MinecraftForge.EVENT_BUS.post(new SpellCastEvent.Post(Source.NPC, attacker.getContinuousSpell(),
						attacker, attacker.getModifiers()));
			}

		}else if(--this.cooldown == 0){

			if(distanceSq > (double)this.maxAttackDistance || !targetIsVisible){
				return;
			}

			double dx = target.posX - attacker.posX;
			double dz = target.posZ - attacker.posZ;

			List<Spell> spells = new ArrayList<Spell>(attacker.getSpells());

			if(spells.size() > 0){

				if(!attacker.world.isRemote){

					// New way of choosing a spell; keeps trying until one works or all have been tried

					Spell spell;

					while(!spells.isEmpty()){

						spell = spells.get(attacker.world.rand.nextInt(spells.size()));

						SpellModifiers modifiers = attacker.getModifiers();

						if(spell != null && attemptCastSpell(spell, modifiers)){
							// The spell worked, so we're done!
							attacker.rotationYaw = (float)(Math.atan2(dz, dx) * 180.0D / Math.PI) - 90.0F;
							return;
						}else{
							spells.remove(spell);
						}
					}
				}
			}

		}else if(this.cooldown < 0){
			// This should only be reached when the entity first starts attacking. Stops it attacking instantly.
			this.cooldown = this.baseCooldown;
		}
	}

private boolean attemptCastSpell(Spell spell, SpellModifiers modifiers){

		// If anything stops the spell working at this point, nothing else happens.
		if(MinecraftForge.EVENT_BUS.post(new SpellCastEvent.Pre(Source.NPC, spell, attacker, modifiers))){
			return false;
		}

		// This is only called when spell casting starts so ticksInUse is always zero
		if(spell.cast(attacker.world, attacker, EnumHand.MAIN_HAND, 0, target, modifiers)){

			if(spell.isContinuous){
				// -1 because the spell has been cast once already!
				this.continuousSpellTimer = this.continuousSpellDuration - 1;
				setContinuousSpellAndNotify(spell, modifiers);

			}else{

				MinecraftForge.EVENT_BUS.post(new SpellCastEvent.Post(Source.NPC, spell, attacker, modifiers));

				// For now, the cooldown is just added to the constant base cooldown. I think this
				// is a reasonable way of doing things; it's certainly better than before.
				this.cooldown = this.baseCooldown + spell.getCooldown();

				if(spell.requiresPacket()){
					// Sends a packet to all players in dimension to tell them to spawn particles.
					IMessage msg = new PacketNPCCastSpell.Message(attacker.getEntityId(), target.getEntityId(),
							EnumHand.MAIN_HAND, spell, modifiers);
					WizardryPacketHandler.net.sendToDimension(msg, attacker.world.provider.getDimension());
				}
			}

			return true;
		}

		return false;
	}

@Override
		public void updateTask(){
			--this.attackTime;
			EntityLivingBase entitylivingbase = this.blaze.getAttackTarget();
			if(entitylivingbase == null) return; // Dynamic stealth breaks things, let's un-break them
			double d0 = this.blaze.getDistanceSq(entitylivingbase);

			if(d0 < 4.0D){
				if(this.attackTime <= 0){
					this.attackTime = 20;
					this.blaze.attackEntityAsMob(entitylivingbase);
				}

				this.blaze.getMoveHelper().setMoveTo(entitylivingbase.posX, entitylivingbase.posY,
						entitylivingbase.posZ, 1.0D);
			}else if(d0 < 256.0D){
				if(this.attackTime <= 0){
					++this.attackStep;

					if(this.attackStep == 1){
						this.attackTime = 60;
						this.blaze.setOnFire(true);
					}else if(this.attackStep <= 4){
						this.attackTime = 6;
					}else{
						this.attackTime = 100;
						this.attackStep = 0;
						this.blaze.setOnFire(false);
					}

					if(this.attackStep > 1){
						// Proof, if it were at all needed, of the elegance and versatility of the spell system.
						Spells.ice_shard.cast(this.blaze.world, this.blaze, EnumHand.MAIN_HAND, 0, entitylivingbase,
								new SpellModifiers());
					}
				}

				this.blaze.getLookHelper().setLookPositionWithEntity(entitylivingbase, 10.0F, 10.0F);
			}else{
				this.blaze.getNavigator().clearPath();
				this.blaze.getMoveHelper().setMoveTo(entitylivingbase.posX, entitylivingbase.posY,
						entitylivingbase.posZ, 1.0D);
			}

			super.updateTask();
		}

@Override
    public boolean hurt(DamageSource source, float amount) {
        if (MobsConfig.PrisonerUnshackleDamage.get()) {
            if (source.getEntity() != null) {
                boolean flag = false;
                LivingEntity owner = this.getLeader();
                if (this.getLeader() == null || this.getLeader().distanceTo(this) >= 8.0D) {
                    owner = this.getMasterOwner();
                }
                if (owner != null) {
                    if (!MobUtil.areAllies(source.getEntity(), owner)) {
                        if (this.distanceTo(owner) >= 8.0D) {
                            flag = true;
                        }
                    }
                }
                if (flag) {
                    if ((this.getHealth() - amount) > 0.0F) {
                        if (this.level.getRandom().nextFloat() <= (amount / this.getHealth())) {
                            Player player = null;
                            if (source.getEntity() instanceof Player player1) {
                                player = player1;
                            }
                            this.unshackle(player);
                        }
                    }
                }
            }
        }
        return super.hurt(source, amount);
    }

public void unshackle(@Nullable Player player) {
        if (this.level instanceof ServerLevel serverLevel) {
            int currentHunger = MiscCapHelper.getCustomFoodLevel(this);
            serverLevel.playSound(null, this.getX(), this.getY(), this.getZ(), SoundEvents.CHAIN_BREAK, this.getSoundSource(), 1.0F, 2.0F);
            AbstractVillager villager;
            if (this.isTrader()) {
                villager = this.convertTo(EntityType.WANDERING_TRADER, true);
            } else {
                villager = this.convertTo(EntityType.VILLAGER, true);
            }
            if (villager == null) {
                return;
            }
            for (EquipmentSlot equipmentslot : EquipmentSlot.values()) {
                ItemStack itemstack = this.getItemBySlot(equipmentslot);
                if (!itemstack.isEmpty()) {
                    if (EnchantmentHelper.hasBindingCurse(itemstack)) {
                        villager.getSlot(equipmentslot.getIndex() + 300).set(itemstack);
                    } else {
                        double d0 = this.getEquipmentDropChance(equipmentslot);
                        if (d0 > 1.0D) {
                            this.spawnAtLocation(itemstack);
                        }
                    }
                }
            }
            if (villager instanceof Villager villager1) {
                villager1.setVillagerData(this.getVillagerData());
                if (this.gossips != null) {
                    villager1.setGossips(this.gossips);
                }

                if (this.tradeOffers != null) {
                    villager1.setOffers(new MerchantOffers(this.tradeOffers));
                }
                villager1.setVillagerXp(this.villagerXp);
                villager1.refreshBrain(serverLevel);
                if (player instanceof ServerPlayer
                        && player != this.getMasterOwner()
                        && !MobUtil.areAllies(player, this.getMasterOwner())) {
                    serverLevel.onReputationEvent(ReputationEventType.ZOMBIE_VILLAGER_CURED, player, villager1);
                    villager1.playSound(SoundEvents.VILLAGER_CELEBRATE);
                    ServerParticleUtil.addParticlesAroundSelf(serverLevel, ParticleTypes.HAPPY_VILLAGER, villager1);
                }
                if (this.getMasterOwner() instanceof Player player1) {
                    villager1.getGossips().add(player1.getUUID(), GossipType.MAJOR_NEGATIVE, 200);
                }
                //Set max to 11 to prevent Villager breeding exploit
                villager1.foodLevel = Mth.clamp(currentHunger, 0, 11);
            } else if (villager instanceof WanderingTrader) {
                if (player instanceof ServerPlayer
                        && player != this.getMasterOwner()
                        && !MobUtil.areAllies(player, this.getMasterOwner())) {
                    villager.playSound(SoundEvents.WANDERING_TRADER_YES);
                    ServerParticleUtil.addParticlesAroundSelf(serverLevel, ParticleTypes.HAPPY_VILLAGER, villager);
                }
                if (this.getMasterOwner() instanceof Player player1) {
                    villager.setLastHurtByPlayer(player1);
                } else if (this.getMasterOwner() != null) {
                    villager.setLastHurtByMob(this.getMasterOwner());
                }
                villager.setCanPickUpLoot(false);
            }
            if (player != null) {
                ItemStack offhand = ItemStack.EMPTY;
                if (this.getOffhandItem().is(ModItems.OMINOUS_SHACKLES.get())) {
                    offhand = this.getOffhandItem().copyAndClear();
                } else if (villager.getOffhandItem().is(ModItems.OMINOUS_SHACKLES.get())) {
                    offhand = villager.getOffhandItem().copyAndClear();
                }
                if (!offhand.isEmpty()) {
                    if (player == this.getMasterOwner() || player == this.getTrueOwner()) {
                        if (player.getItemInHand(InteractionHand.MAIN_HAND).isEmpty()) {
                            player.setItemInHand(InteractionHand.MAIN_HAND, offhand);
                        } else if (!player.addItem(offhand)) {
                            this.spawnAtLocation(offhand);
                        }
                    }
                }
            }
            ServerParticleUtil.addParticlesAroundMiddleSelf(serverLevel, new BlockParticleOption(ParticleTypes.BLOCK, Blocks.CHAIN.defaultBlockState()), villager);
            villager.finalizeSpawn(serverLevel, serverLevel.getCurrentDifficultyAt(villager.blockPosition()), MobSpawnType.CONVERSION, (SpawnGroupData) null, (CompoundTag) null);
            villager.setHealth(this.getHealth());
            net.minecraftforge.event.ForgeEventFactory.onLivingConvert(this, villager);
        }
    }

public void setLeader(@Nullable RaiderServant livingEntity){
        if (livingEntity != null && livingEntity != this) {
            this.setLeaderId(livingEntity.getUUID());
            this.setLeaderClientId(livingEntity.getId());
            this.getNavigation().stop();
        } else {
            this.setLeaderId(null);
            this.setLeaderClientId(-1);
        }
    }

@Override
    public void onCeaseFire(ServerPlayer player) {
        super.onCeaseFire(player);
        if (player.getMainHandItem().is(ItemTags.BANNERS) || player.getOffhandItem().is(ItemTags.BANNERS)){
            if (this.getRaidPos() != null) {
                if (this.isLeader()) {
                    player.displayClientMessage(Component.translatable("info.goety.servant.stopRaid", this.getRaidPos().getX(), this.getRaidPos().getY(), this.getRaidPos().getZ()), false);
                }
                this.setRaidPos(null);
            }
        }
    }

@Override
    public void tick() {
        super.tick();
        if (!this.level.isClientSide) {
            if (this.celebrationTime > 0) {
                --this.celebrationTime;
            } else {
                if (this.missionComplete) {
                    if (this.getTrueOwner() != null
                            && this.getTrueOwner().distanceTo(this) > 32.0D
                            && MobUtil.sameDimension(this, this.getTrueOwner())) {
                        this.teleportTowards(this.getTrueOwner());
                    }
                    this.missionComplete = false;
                }
            }
            if (this.getLeader() != null) {
                if ((this.getLeader().tickCount >= 100 && !this.getLeader().isLeader()) || this.getLeader().isDeadOrDying() || this.isLeader()) {
                    this.setLeader(null);
                } else {
                    if (this.getLeader().tickCount < 20) {
                        Entity entity = this.level.getEntity(this.getOwnerClientId());
                        if (entity instanceof RaiderServant raiderServant) {
                            if (raiderServant != this.getLeader()) {
                                this.setLeaderClientId(this.getLeader().getId());
                            }
                        } else {
                            this.setLeaderClientId(this.getLeader().getId());
                        }
                    }
                    if (this.canLinkToIdol()) {
                        if (this.getLeader().getIdol() != null) {
                            OminousIdolBlockEntity idol = this.getLeader().getIdol();
                            if (idol != null) {
                                if (this.getIdol() == null || this.getIdol() != idol) {
                                    if (idol.hasSpace()) {
                                        if (this.getIdol() != null) {
                                            this.getIdol().removeIllager(this);
                                        }
                                        idol.addIllager(this);
                                        this.setRevivePos(idol.getBlockPos());
                                        if (idol.getLevel() != null) {
                                            this.setReviveDim(idol.getLevel().dimension());
                                        } else {
                                            this.setReviveDim(this.getLeader().getReviveDim());
                                        }
                                    }
                                }
                            }
                        }
                    }
                    if (!(this instanceof ITrainable trainable && trainable.isTraining())
                            && !this.isWoundedOrCrippled()) {
                        if (this.getLeader().getMarked() != null && this.getLeader().getMarked() != this.getMarked()) {
                            this.setMarked(this.getLeader().getMarked());
                        }
                        if (this.getLeader().getRaidPos() != null && !BlockFinder.samePos(this.getLeader().getRaidPos(), this.getRaidPos())) {
                            this.setRaidPos(this.getLeader().getRaidPos());
                        } else if (this.getLeader().getTarget() != null && this.getPriorityTarget() == null && this.getTarget() == null) {
                            this.setTarget(this.getLeader().getTarget());
                        }
                    }
                    this.setCaptureMode(this.getLeader().isCapturing());
                    if (this.getLeader().getTrueOwner() != null) {
                        if (this.getTrueOwner() == null || this.getTrueOwner() != this.getLeader().getTrueOwner()) {
                            this.setTrueOwner(this.getLeader().getTrueOwner());
                        }
                    }
                }
            }
            this.updateIdol();
            this.markedTick();
            this.raidTick();
        }
    }

public void raidTick(){
        if (this.level instanceof ServerLevel serverLevel) {
            BlockPos raidPos = this.getRaidPos();
            if (raidPos != null) {
                if (this.level.dimension() != this.getRaidLevel()){
                    this.setRaidPos(null);
                    if (this.getTrueOwner() != null
                            && this.getTrueOwner().distanceTo(this) > 32.0D
                            && MobUtil.sameDimension(this, this.getTrueOwner())) {
                        this.teleportTowards(this.getTrueOwner());
                    }
                }

                if (!serverLevel.isVillage(raidPos)) {
                    this.moveRaidCenterToNearbyVillageSection();
                }

                if (!serverLevel.isVillage(raidPos) || (this.getRaidVillagers().isEmpty() && this.raidTime >= 100)) {
                    this.celebrationTime = 600;
                    this.missionComplete = true;
                    this.setRaidPos(null);
                    if (this.getTrueOwner() instanceof ServerPlayer serverPlayer){
                        ModCriteriaTriggers.SERVANT_RAID_VICTORY.trigger(serverPlayer);
                    }
                }
                ++this.raidTime;

                this.chunkLoadTarget(raidPos);

                if (this.raidTime >= 48000){
                    this.setRaidPos(null);
                    if (this.getTrueOwner() != null
                            && this.getTrueOwner().distanceTo(this) > 32.0D
                            && MobUtil.sameDimension(this, this.getTrueOwner())) {
                        this.teleportTowards(this.getTrueOwner());
                    }
                }
                boolean raidFlag = this.isAllyWithType(EntityType.VILLAGER);
                if (raidFlag) {
                    this.setRaidPos(null);
                    if (this.getTrueOwner() != null) {
                        if (this.getTrueOwner().distanceTo(this) > 32.0D
                                && MobUtil.sameDimension(this, this.getTrueOwner())) {
                            this.teleportTowards(this.getTrueOwner());
                        }
                    }
                }
                if (this.isLeader()) {
                    for (RaiderServant servant : this.getNearbyCompanions()) {
                        if (servant.getLeader() == null && servant.getRaidPos() == raidPos) {
                            servant.setLeader(this);
                            servant.setFollowing();
                        }
                    }
                }
            } else {
                if (this.raidTime > 0){
                    this.raidTime = 0;
                }
            }
        }
    }

@Override
    public void followGoal() {
        this.goalSelector.addGoal(6, new FollowOwnerGoal<>(this, this.getFollowSpeed(), 10.0F, 2.0F){
            @Override
            public boolean canUse() {
                if (RaiderServant.this.isRaiding()){
                    return false;
                }
                if (RaiderServant.this instanceof ITrainable trainable) {
                    if (trainable.isTraining()) {
                        return false;
                    }
                }
                if (RaiderServant.this.getLeader() != null){
                    LivingEntity livingentity = RaiderServant.this.getLeader();
                    if (livingentity == null) {
                        return false;
                    } else if (livingentity.isSpectator()) {
                        return false;
                    } else if (RaiderServant.this.distanceToSqr(livingentity) < (double)(Mth.square(this.startDistance))) {
                        return false;
                    } else if (!RaiderServant.this.isFollowing() || RaiderServant.this.isCommanded()) {
                        return false;
                    } else if (RaiderServant.this.getTarget() != null) {
                        return false;
                    } else if (RaiderServant.this.isWoundedOrCrippled()) {
                        return false;
                    } else {
                        this.owner = livingentity;
                        return true;
                    }
                }
                return super.canUse();
            }

            @Override
            public boolean canContinueToUse() {
                if (RaiderServant.this instanceof ITrainable trainable) {
                    if (trainable.isTraining()) {
                        return false;
                    }
                }
                return super.canContinueToUse();
            }
        });
    }

public InteractionResult mobInteract(Player pPlayer, InteractionHand pHand) {
        ItemStack itemstack = pPlayer.getItemInHand(pHand);
        if (this.getTrueOwner() != null && pPlayer == this.getTrueOwner()) {
            ItemStack leaderBanner = this.getLeaderBannerInstance();
            if (pHand == InteractionHand.MAIN_HAND
                    && this.canBeLeader()
                    && !leaderBanner.isEmpty()
                    && ItemHelper.sameBanner(itemstack, leaderBanner)
                    && !ItemHelper.sameBanner(this.getItemBySlot(EquipmentSlot.HEAD), leaderBanner)) {
                ItemStack helmet = this.getItemBySlot(EquipmentSlot.HEAD);
                this.playSound(SoundEvents.ARMOR_EQUIP_GENERIC, 1.0F, 1.0F);
                this.playSound(this.getCelebrateSound(), 1.0F, this.getVoicePitch());
                this.dropEquipment(EquipmentSlot.HEAD, helmet);
                this.setItemSlot(EquipmentSlot.HEAD, this.getLeaderBannerWithNameInstance());
                this.setGuaranteedDrop(EquipmentSlot.HEAD);
                if (!pPlayer.getAbilities().instabuild) {
                    itemstack.shrink(1);
                }
                for (int i = 0; i < 7; ++i) {
                    double d0 = this.random.nextGaussian() * 0.02D;
                    double d1 = this.random.nextGaussian() * 0.02D;
                    double d2 = this.random.nextGaussian() * 0.02D;
                    this.level.addParticle(ParticleTypes.HAPPY_VILLAGER, this.getRandomX(1.0D), this.getRandomY() + 0.5D, this.getRandomZ(1.0D), d0, d1, d2);
                }
                return InteractionResult.SUCCESS;
            } else if (pPlayer.getMainHandItem().getItem() instanceof TaglockKit
                    && TaglockKit.hasEntity(pPlayer.getMainHandItem())
                    && !MobUtil.areAllies(pPlayer, TaglockKit.getEntity(pPlayer.getMainHandItem()))
                    && this.isLeader()){
                this.setMarked(TaglockKit.getEntity(pPlayer.getMainHandItem()));
                this.setTarget(this.getMarked());
                if (!pPlayer.getAbilities().instabuild) {
                    TaglockKit.removeEntity(pPlayer.getMainHandItem());
                }
                if (!this.level.isClientSide) {
                    if (this.getMarked() instanceof ServerPlayer player) {
                        if (CuriosFinder.hasCurio(player, ModItems.ALARMING_CHARM.get())) {
                            player.displayClientMessage(Component.translatable("info.goety.summon.hunt").withStyle(ChatFormatting.RED), true);
                            ModNetwork.sendToClient(player, new SPlayPlayerSoundPacket(SoundEvents.RAID_HORN.get(), 64.0F, 1.0F));
                        }
                    }
                }

                if (this.isStaying()){
                    this.setStaying(false);
                }
                if (this.isGuardingArea()){
                    this.setBoundPos(null);
                }
                for (RaiderServant servant : this.getNearbyCompanions()) {
                    servant.setMarked(this.getMarked());
                    servant.setTarget(this.getMarked());
                    if (servant.getLeader() == null){
                        servant.setLeader(this);
                        servant.setFollowing();
                    }
                    if (MobUtil.sameDimension(servant, this.getMarked())) {
                        servant.teleportTowards(this.getMarked());
                    }
                }
                if (MobUtil.sameDimension(this, this.getMarked())) {
                    this.teleportTowards(this.getMarked());
                }
                return InteractionResult.SUCCESS;
            } else if (pPlayer.getMainHandItem().is(ModItems.WAYSTONE.get())
                    && WaystoneItem.hasBlock(pPlayer.getMainHandItem())
                    && WaystoneItem.isSameDimension(this, pPlayer.getMainHandItem())
                    && (pPlayer.getOffhandItem().is(Items.GOAT_HORN) || pPlayer.getOffhandItem().is(ModItems.RAIDING_HORN.get()))
                    && !SEHelper.getFocusCoolDown(pPlayer).isOnCooldown(ModItems.WAYSTONE.get())
                    && this.isLeader()){
                if (this.level instanceof ServerLevel serverLevel) {
                    GlobalPos globalPos = WaystoneItem.getPosition(pPlayer.getMainHandItem());
                    if (globalPos != null){
                        BlockPos blockPos = globalPos.pos();
                        if (!serverLevel.isLoaded(blockPos)){
                            pPlayer.displayClientMessage(Component.translatable("info.goety.waystone.unloaded"), true);
                            return InteractionResult.FAIL;
                        }
                        if (serverLevel.isVillage(blockPos)){
                            if (this.isAllyWithType(EntityType.VILLAGER)) {
                                return InteractionResult.FAIL;
                            }
                            this.setRaidPos(blockPos);
                            this.setRaidDim(serverLevel.dimension());
                            if (this.isStaying()){
                                this.setStaying(false);
                            }
                            if (this.isGuardingArea()){
                                this.setBoundPos(null);
                            }
                            boolean flag = this.position().distanceToSqr(blockPos.getCenter()) <= Mth.square(32);
                            if (!flag) {
                                int k = 0;
                                BlockPos blockPos1 = this.findRandomSpawnPos(k, 20);
                                if (blockPos1 != null) {
                                    for (RaiderServant servant : this.getNearbyCompanions()) {
                                        servant.setRaidPos(blockPos);
                                        servant.setRaidDim(serverLevel.dimension());
                                        if (servant.getLeader() == null) {
                                            servant.setLeader(this);
                                            servant.setFollowing();
                                        }
                                        servant.moveTo(blockPos1, 0.0F, 0.0F);
                                    }
                                    this.moveTo(blockPos1, 0.0F, 0.0F);
                                    flag = true;
                                } else {
                                    ++k;
                                }
                            }
                            if (flag) {
                                long j = serverLevel.getRandom().nextLong();
                                for(ServerPlayer serverplayer : serverLevel.players()) {
                                    Vec3 vec3 = serverplayer.position();
                                    Vec3 vec31 = this.position();
                                    double d0 = Math.sqrt((vec31.x - vec3.x) * (vec31.x - vec3.x) + (vec31.z - vec3.z) * (vec31.z - vec3.z));
                                    double d1 = vec3.x + 13.0D / d0 * (vec31.x - vec3.x);
                                    double d2 = vec3.z + 13.0D / d0 * (vec31.z - vec3.z);
                                    if (d0 <= 64.0D) {
                                        serverplayer.connection.send(new ClientboundSoundPacket(SoundEvents.RAID_HORN, SoundSource.NEUTRAL, d1, serverplayer.getY(), d2, 64.0F, 1.0F, j));
                                    }
                                }
                                if (this.getTrueOwner() instanceof Player player) {
                                    SEHelper.addCooldown(player, ModItems.WAYSTONE.get(), 300);
                                }
                                return InteractionResult.SUCCESS;
                            }
                        }
                    }
                }
                return InteractionResult.CONSUME;
            } else if (pPlayer.getMainHandItem().is(ModItems.OMINOUS_SHACKLES.get())
                    && !this.isCapturing()
                    && !this.isFollower()){
                if (!this.level.isClientSide) {
                    this.setCaptureMode(true);
                    this.playSound(SoundEvents.CHAIN_PLACE, 1.0F, 1.0F);
                }

                return InteractionResult.SUCCESS;
            } else if (pPlayer.getMainHandItem().is(Tags.Items.SHEARS)
                    && this.isCapturing()
                    && !this.isFollower()){
                if (!this.level.isClientSide) {
                    this.setCaptureMode(false);
                    this.playSound(SoundEvents.CHAIN_BREAK, 1.0F, 0.5F);
                }

                return InteractionResult.SUCCESS;
            } else if (pPlayer.getMainHandItem().isEmpty() && this.isLeader() && !this.getBindPrisoners().isEmpty()){
                for (Prisoner prisoner : this.getBindPrisoners()) {
                    prisoner.setLeader(this);
                }
                this.playSound(SoundEvents.CHAIN_PLACE, 1.0F, 1.0F);
                return InteractionResult.SUCCESS;
            } else if (pPlayer.getMainHandItem().isEmpty() && this.getItemBySlot(EquipmentSlot.HEAD).getItem() instanceof BannerItem){
                ItemStack helmet = this.getItemBySlot(EquipmentSlot.HEAD);
                this.setItemSlot(EquipmentSlot.HEAD, ItemStack.EMPTY);
                this.dropEquipment(EquipmentSlot.HEAD, helmet);
                return InteractionResult.SUCCESS;
            } else if (this.canLinkToIdol()) {
                return this.linkToIdol(pPlayer, pHand);
            }
        }
        return super.mobInteract(pPlayer, pHand);
    }

