				if(target.ticksExisted % target.maxHurtResistantTime == 1){

					float damage = Spells.withering_totem.getProperty(Spell.DAMAGE).floatValue();

					if(EntityUtils.attackEntityWithoutKnockback(target, MagicDamage.causeIndirectMagicDamage(this,
							getCaster(), DamageType.WITHER), damage)){
						addHealthDrained(damage);
					}
				}

				targetsRemaining--;

				if(world.isRemote){

					Vec3d centre = GeometryUtils.getCentre(this);
					Vec3d pos = GeometryUtils.getCentre(target);

					ParticleBuilder.create(Type.BEAM).pos(centre).target(target)
							.clr(0.1f + 0.2f * world.rand.nextFloat(), 0, 0.3f).spawn(world);

					for(int i = 0; i < 3; i++){
						ParticleBuilder.create(Type.DUST, rand, pos.x, pos.y, pos.z, 0.3, false)
								.vel(pos.subtract(centre).normalize().scale(-0.1)).clr(0x0c0024).fade(0x610017).spawn(world);
					}
				}
			}
		}
	}

@Override
	public void despawn(){

		double radius = Spells.withering_totem.getProperty(Spell.EFFECT_RADIUS).floatValue() * sizeMultiplier;

		List<EntityLivingBase> nearby = EntityUtils.getLivingWithinRadius(radius, posX, posY, posZ, world);
		nearby.removeIf(e -> !isValidTarget(e));

		float damage = Math.min(getHealthDrained() * 0.2f, Spells.withering_totem.getProperty(WitheringTotem.MAX_EXPLOSION_DAMAGE).floatValue());

		for(EntityLivingBase target : nearby){

			if(!world.isRemote && EntityUtils.attackEntityWithoutKnockback(target, MagicDamage.causeIndirectMagicDamage(this,
					getCaster(), DamageType.MAGIC), damage)){
				target.addPotionEffect(new PotionEffect(MobEffects.WITHER, Spells.withering_totem.getProperty(Spell.EFFECT_DURATION).intValue(),
						Spells.withering_totem.getProperty(Spell.EFFECT_STRENGTH).intValue()));
			}
		}

		if(world.isRemote) ParticleBuilder.create(Type.SPHERE).pos(GeometryUtils.getCentre(this)).scale((float)radius).clr(0xbe1a53)
				.fade(0x210f4a).spawn(world);

		this.playSound(WizardrySounds.ENTITY_WITHERING_TOTEM_EXPLODE, 1, 1);
		super.despawn();
	}

@Override
	public boolean processInteract(EntityPlayer player, EnumHand hand){

		ItemStack itemstack = player.getHeldItem(hand);

		// Allows the owner (but not other players) to dispel the spirit horse using a wand (shift-clicking, because
		// clicking mounts the horse in this case).
		if(itemstack.getItem() instanceof ISpellCastingItem && this.getOwner() == player && player.isSneaking()){
			// Prevents accidental double clicking.
			if(this.ticksExisted > 20 && dispelTimer == 0){

				this.dispelTimer++;

				this.playSound(WizardrySounds.ENTITY_SPIRIT_HORSE_VANISH, 0.7F, rand.nextFloat() * 0.4F + 1.0F);
				// This is necessary to prevent the wand's spell being cast when performing this action.
				return true;
			}
			return false;
		}

		return super.processInteract(player, hand);
	}

@Override
	public void onUpdate(){

		super.onUpdate();

		if(dispelTimer > 0){
			if(dispelTimer++ > DISPEL_TIME){
				this.setDead();
			}
		}

		// Adds a dust particle effect
		if(this.world.isRemote){
			double x = this.posX - this.width / 2 + this.rand.nextFloat() * width;
			double y = this.posY + this.height * this.rand.nextFloat() + 0.2f;
			double z = this.posZ - this.width / 2 + this.rand.nextFloat() * width;
			ParticleBuilder.create(Type.DUST).pos(x, y, z).clr(0.8f, 0.8f, 1.0f).shaded(true).spawn(world);
		}

		// Spirit horse disappears a short time after being dismounted.
		if(!this.isBeingRidden()){
			this.idleTimer++;
		}else if(this.idleTimer > 0){
			this.idleTimer = 0;
		}

		if(this.idleTimer > 200 && dispelTimer == 0){

			this.playSound(WizardrySounds.ENTITY_SPIRIT_HORSE_VANISH, 0.7F, rand.nextFloat() * 0.4F + 1.0F);

			this.dispelTimer++;
		}
	}

public HereticServant(EntityType<? extends Owned> type, Level worldIn) {
        super(type, worldIn);
        this.gameEventListener = new DynamicGameEventListener<>(new GameEventListener() {
            public PositionSource getListenerSource() {
                return new BlockPositionSource(HereticServant.this.blockPosition());
            }

            public int getListenerRadius() {
                return 32;
            }

            public GameEventListener.DeliveryMode getDeliveryMode() {
                return GameEventListener.DeliveryMode.BY_DISTANCE;
            }

            public boolean handleGameEvent(ServerLevel serverLevel, GameEvent p_282184_, GameEvent.Context p_283014_, Vec3 p_282350_) {
                if (!HereticServant.this.isRemoved()) {
                    if (p_282184_ == GameEvent.ENTITY_DIE) {
                        Entity sourceEntity = p_283014_.sourceEntity();
                        if (sourceEntity instanceof Mob mob && !(mob instanceof IOwned) && !(mob instanceof IHeretic)) {
                            HereticServant.this.getConvokePos().add(mob.position());
                            return true;
                        }
                    }

                }
                return false;
            }
        });
    }

@Override
        public boolean canUse() {
            if (this.heretic.getChantCoolDown() > 0){
                return false;
            }
            LivingEntity target = this.heretic.getTarget();
            return target != null && target.isAlive() && this.heretic.distanceTo(target) <= this.heretic.getAttributeValue(Attributes.FOLLOW_RANGE) && this.heretic.hasLineOfSight(target);
        }

@Override
        public void tick() {
            ++this.chantTime;
            this.heretic.getNavigation().stop();
            this.heretic.getMoveControl().strafe(0.0F, 0.0F);
            if (this.heretic.getTarget() != null) {
                LivingEntity target = this.heretic.getTarget();
                MobUtil.instaLook(this.heretic, target.position().add(0, target.getBbHeight() / 2, 0));
            }
            if (this.chantTime % 10 == 0) {
                HellChant hellChant = ModEntityType.HELL_CHANT.get().create(this.heretic.level);
                if (hellChant != null) {
                    if (this.heretic.level.getDifficulty() == Difficulty.HARD){
                        hellChant.setBurning(1);
                    }
                    hellChant.chant(this.heretic);
                    this.heretic.level.addFreshEntity(hellChant);
                }
            }
            super.tick();
        }

public void findTargetPos(){
            double hitDist = 0.0D;
            if (!this.heretic.getConvokePos().isEmpty()) {
                for (Vec3 vec31 : this.heretic.getConvokePos()) {
                    if (this.heretic.getNavigation().isStableDestination(BlockPos.containing(vec31))) {
                        Optional<Vec3> interceptPos = this.heretic.getBoundingBox().clip(vec31, vec31.add(1.0D, 1.0D, 1.0D));
                        if (this.heretic.getBoundingBox().inflate(this.heretic.getAttributeValue(Attributes.FOLLOW_RANGE)).contains(vec31)) {
                            if (0.0D <= hitDist) {
                                this.targetPos = vec31;
                                hitDist = 0.0D;
                            }
                        } else if (interceptPos.isPresent()) {
                            double possibleDist = vec31.distanceTo(interceptPos.get());

                            if (possibleDist < hitDist || hitDist == 0.0D) {
                                this.targetPos = vec31;
                                hitDist = possibleDist;
                            }
                        }
                    }
                }
                try {
                    if (this.targetPos != null) {
                        try {
                            for (LivingEntity livingEntity : this.heretic.level.getEntitiesOfClass(LivingEntity.class, this.heretic.getBoundingBox().inflate(this.heretic.getAttributeValue(Attributes.FOLLOW_RANGE)), livingEntity -> livingEntity instanceof IHeretic)){
                                if (livingEntity instanceof IHeretic heretic1) {
                                    if (heretic1 != this.heretic) {
                                        if (!heretic1.getConvokePos().isEmpty()) {
                                            heretic1.getConvokePos().remove(this.targetPos);
                                        }
                                    }
                                }
                            }
                        } catch (ConcurrentModificationException ignored) {
                        }
                    }
                } catch (NullPointerException ignored) {
                }
            } else {
                this.targetPos = null;
            }
        }

@Override
        public void tick() {
            if (this.targetPos != null) {
                if (this.heretic.level instanceof ServerLevel serverLevel) {
                    ColorUtil colorUtil = new ColorUtil(ChatFormatting.DARK_PURPLE);
                    ServerParticleUtil.circularParticles(serverLevel, ModParticleTypes.RISING_ENCHANT.get(), this.targetPos.x, this.targetPos.y, this.targetPos.z, colorUtil.red, colorUtil.green, colorUtil.blue, 1.0F);
                }
                if (this.heretic.distanceToSqr(this.targetPos) > Mth.square(4.0D)){
                    ++this.movingTime;
                    this.heretic.getNavigation().moveTo(this.targetPos.x, this.targetPos.y, this.targetPos.z, 1.0F);
                } else {
                    MobUtil.instaLook(this.heretic, this.targetPos);
                    ++this.castingTime;
                    if (!this.heretic.isCasting()){
                        this.heretic.setCasting(true);
                        this.heretic.level.broadcastEntityEvent(this.heretic, (byte) 6);
                    }
                    if (this.castingTime == TOTAL_CAST_TIME){
                        Summoned summon = new ZPiglinServant(ModEntityType.ZPIGLIN_SERVANT.get(), this.heretic.level);
                        if (this.heretic.getRandom().nextFloat() <= 0.5F){
                            summon = new Hellhound(ModEntityType.HELLHOUND.get(), this.heretic.level);
                        } else if (this.heretic.getRandom().nextFloat() <= 0.25F){
                            summon = new MagmaCubeServant(ModEntityType.MAGMA_CUBE_SERVANT.get(), this.heretic.level);
                        } else if (this.heretic.getRandom().nextFloat() <= 0.05F){
                            summon = new BlazeServant(ModEntityType.BLAZE_SERVANT.get(), this.heretic.level);
                        }
                        summon.moveTo(this.targetPos);
                        summon.setTrueOwner(this.heretic);
                        if (this.heretic.level instanceof ServerLevel serverLevel) {
                            summon.finalizeSpawn(serverLevel, this.heretic.level.getCurrentDifficultyAt(BlockPos.containing(this.targetPos)), MobSpawnType.MOB_SUMMONED, null, null);
                            ServerParticleUtil.addParticlesAroundMiddleSelf(serverLevel, ParticleTypes.FLAME, summon);
                        }
                        if (summon instanceof MagmaCubeServant cube){
                            cube.setSize(2, true);
                        }
                        if (this.heretic.getTarget() != null) {
                            summon.setTarget(this.heretic.getTarget());
                        }
                        summon.setLimitedLife(MathHelper.minecraftDayToTicks(5));
                        if (this.heretic.level.addFreshEntity(summon)){
                            summon.playSound(ModSounds.SUMMON_SPELL_FIERY.get(), 1.0F, 1.0F);
                            this.heretic.getConvokePos().remove(this.targetPos);
                            this.heretic.setCastCoolDown(100);
                        }
                    }
                }
            } else {
                this.findTargetPos();
            }
            super.tick();
        }

@Override
        public void tick() {
            if (this.heretic.getMonolith() != null) {
                if (this.heretic.distanceTo(this.heretic.getMonolith()) <= 8.0D && this.heretic.hasLineOfSight(this.heretic.getMonolith())) {
                    this.heretic.setTarget(null);
                    if (!this.heretic.isCasting()){
                        this.heretic.setCasting(true);
                    }
                    MobUtil.instaLook(this.heretic, this.heretic.getMonolith());
                    this.drawParticleBeam(this.heretic, this.heretic.getMonolith());
                    if (this.heretic.tickCount % 20 == 0){
                        this.heretic.getMonolith().heal(1.0F);
                    }
                    this.heretic.getMonolith().empowered = 10;
                    this.heretic.getNavigation().stop();
                    this.heretic.noActionTime = 0;
                } else {
                    if (this.heretic.isCasting()){
                        this.heretic.setCasting(false);
                    }
                    Vec3 vec3 = this.heretic.getMonolith().position();
                    this.heretic.getNavigation().moveTo(vec3.x, vec3.y, vec3.z, 1.0D);
                }
            }
        }

public boolean canUse() {
            if (this.nextScanTick > 0) {
                --this.nextScanTick;
            } else {
                this.nextScanTick = reducedTickDelay(60);
                List<LivingEntity> list = PhantomServant.this.level.getNearbyEntities(LivingEntity.class, this.attackTargeting, PhantomServant.this, PhantomServant.this.getBoundingBox().inflate(16.0D, 64.0D, 16.0D));
                if (!list.isEmpty()) {
                    list.sort(Comparator.<Entity, Double>comparing(Entity::getY).reversed());

                    for(LivingEntity livingEntity : list) {
                        if (!MobUtil.areAllies(PhantomServant.this, livingEntity)) {
                            PhantomServant.this.setTarget(livingEntity);
                            return true;
                        }
                    }
                }

            }
            return false;
        }

private void setAnchorAboveTarget() {
            if (PhantomServant.this.getTarget() != null) {
                boolean flag = true;
                if (PhantomServant.this.isGuardingArea() && PhantomServant.this.getBoundPos() != null){
                    if (PhantomServant.this.getTarget().distanceToSqr(PhantomServant.this.vec3BoundPos()) > Mth.square(GUARDING_RANGE)){
                        PhantomServant.this.anchorPoint = PhantomServant.this.getBoundPos();
                        flag = false;
                    }
                }
                if (flag) {
                    PhantomServant.this.anchorPoint = PhantomServant.this.getTarget().blockPosition().above(20 + PhantomServant.this.random.nextInt(20));
                    if (PhantomServant.this.anchorPoint.getY() < PhantomServant.this.level.getSeaLevel()) {
                        PhantomServant.this.anchorPoint = new BlockPos(PhantomServant.this.anchorPoint.getX(), PhantomServant.this.level.getSeaLevel() + 1, PhantomServant.this.anchorPoint.getZ());
                    }
                }
            }
        }

public void stop() {
            if (PhantomServant.this.isGuardingArea()){
                PhantomServant.this.anchorPoint = PhantomServant.this.getBoundPos();
            } else {
                PhantomServant.this.anchorPoint = PhantomServant.this.level.getHeightmapPos(Heightmap.Types.MOTION_BLOCKING, PhantomServant.this.anchorPoint).above(10 + PhantomServant.this.random.nextInt(20));
            }
        }

