public void tick() {
        super.tick();
        this.prevGroundProgress = groundProgress;
        this.prevSwimProgress = swimProgress;
        this.prevBaskingProgress = baskingProgress;
        this.prevGrabProgress = grabProgress;

        final boolean ground = !this.isInWater();
        final boolean groundAnimate = !this.isInWater();
        final boolean basking = groundAnimate && this.isSitting();
        final boolean grabbing = !this.getPassengers().isEmpty();

        if (!ground && this.isLandNavigator) {
            switchNavigator(false);
        }
        if (ground && !this.isLandNavigator) {
            switchNavigator(true);
        }

        if (groundAnimate) {
            if (this.groundProgress < 10F)
                this.groundProgress++;

            if (this.swimProgress > 0F)
                this.swimProgress--;
        } else {
            if (this.groundProgress > 0F)
                this.groundProgress--;

            if (this.swimProgress < 10F)
                this.swimProgress++;
        }

        if (basking) {
            if (this.baskingProgress < 10F)
                this.baskingProgress++;
        } else {
            if (this.baskingProgress > 0F)
                this.baskingProgress--;
        }

        if (grabbing) {
            if (this.grabProgress < 10F)
                this.grabProgress++;
        } else {
            if (this.grabProgress > 0F)
                this.grabProgress--;
        }

        if (this.getTarget() == null) {
            if (hasSpedUp) {
                hasSpedUp = false;
                this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.25F);
            }
        } else {
            if (!hasSpedUp) {
                hasSpedUp = true;
                this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.28F);
            }
        }

        if (!this.level().isClientSide) {
            this.setBesideClimbableBlock(this.horizontalCollision);
        }
        if (baskingTimer < 0) {
            baskingTimer++;
        }
        if (passengerTimer > 0 && this.getPassengers().isEmpty()) {
            passengerTimer = 0;
        }
        if (!this.level().isClientSide) {
            if (isInWater()) {
                swimTimer++;
                ticksSinceInWater = 0;
            } else {
                ticksSinceInWater++;
                swimTimer--;
            }

            if (!this.isInWater() && this.onGround()) {
                if (!this.isTame()) {
                    if (!this.isSitting() && baskingTimer == 0 && this.getTarget() == null && this.getNavigation().isDone()) {
                        this.setOrderedToSit(true);
                        this.baskingTimer = 1000 + random.nextInt(750);
                    }
                    if (this.isSitting() && (baskingTimer <= 0 || this.getTarget() != null || swimTimer < -1000)) {
                        this.setOrderedToSit(false);
                        this.baskingTimer = -2000 - random.nextInt(750);
                    }
                    if (this.isSitting() && baskingTimer > 0) {
                        baskingTimer--;
                    }
                }
            }
            if (this.getStunTicks() == 0 && this.isAlive() && this.getTarget() != null && this.getAnimation() == ANIMATION_LUNGE && (level().getDifficulty() != Difficulty.PEACEFUL || !(this.getTarget() instanceof Player)) && this.getAnimationTick() > 5 && this.getAnimationTick() < 9) {
                final float f1 = this.getYRot() * Mth.DEG_TO_RAD;
                this.setDeltaMovement(this.getDeltaMovement().add(-Mth.sin(f1) * 0.02F, 0.0D, Mth.cos(f1) * 0.02F));
                if (this.distanceTo(this.getTarget()) < 3.5F && this.hasLineOfSight(this.getTarget())) {
                    boolean flag = this.getTarget().isBlocking();
                    if (!flag) {
                        if (this.getTarget().getBbWidth() < this.getBbWidth() && this.getPassengers().isEmpty() && !this.getTarget().isShiftKeyDown()) {
                            this.getTarget().startRiding(this, true);
                        }
                    }
                    if (flag) {
                        if (this.getTarget() instanceof final Player player) {
                            this.damageShieldFor(player, (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue());
                        }
                        if (this.getStunTicks() == 0) {
                            this.setStunTicks(25 + random.nextInt(20));
                        }
                    } else {
                        this.getTarget().hurt(this.damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue());
                    }
                    this.playSound(AMSoundRegistry.CROCODILE_BITE.get(), this.getSoundVolume(), this.getVoicePitch());

                }
            }
            if (this.isAlive() && this.getTarget() != null && this.isInWater() && (level().getDifficulty() != Difficulty.PEACEFUL || !(this.getTarget() instanceof Player))) {
                if (this.getTarget().getVehicle() != null && this.getTarget().getVehicle() == this) {
                    if (this.getAnimation() == NO_ANIMATION) {
                        this.setAnimation(ANIMATION_DEATHROLL);
                    }
                    if (this.getAnimation() == ANIMATION_DEATHROLL && this.getAnimationTick() % 10 == 0 && this.distanceTo(this.getTarget()) < 5D) {
                        this.getTarget().hurt(this.damageSources().mobAttack(this), 5);
                    }
                }
            }
        }
        if (this.getAnimation() == ANIMATION_DEATHROLL) {
            this.getNavigation().stop();
        }
        if (this.isInLove() && this.getTarget() != null) {
            this.setTarget(null);
        }
        if (this.getStunTicks() > 0) {
            this.setStunTicks(this.getStunTicks() - 1);
            if (this.level().isClientSide) {
                final float angle = (Maths.STARTING_ANGLE * this.yBodyRot);
                final double headX = 1.5F * getScale() * Mth.sin(Mth.PI + angle);
                final double headZ = 1.5F * getScale() * Mth.cos(angle);
                for (int i = 0; i < 5; i++) {
                    final float innerAngle = (Maths.STARTING_ANGLE * (this.yBodyRot + tickCount * 5) * (i + 1));
                    final double extraX = 0.5F * Mth.sin((float) (Math.PI + innerAngle));
                    final double extraZ = 0.5F * Mth.cos(innerAngle);
                    level().addParticle(ParticleTypes.CRIT, true, this.getX() + headX + extraX, this.getEyeY() + 0.5F, this.getZ() + headZ + extraZ, 0, 0, 0);
                }
            }
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

public void tick() {
        super.tick();
        if (!this.getItemInHand(InteractionHand.MAIN_HAND).isEmpty() && this.canTargetItem(this.getItemInHand(InteractionHand.MAIN_HAND))) {
            this.setEating(true);
            this.setOrderedToSit(true);
            this.setStanding(false);
        }
        if (isEating() && !this.canTargetItem(this.getItemInHand(InteractionHand.MAIN_HAND))) {
            this.setEating(false);
            eatingTime = 0;
            if (!forcedSit) {
                this.setOrderedToSit(true);
            }
        }
        if (isEating()) {
            eatingTime++;
            if (!this.getMainHandItem().is(ItemTags.LEAVES)) {
                for (int i = 0; i < 3; i++) {
                    double d2 = this.random.nextGaussian() * 0.02D;
                    double d0 = this.random.nextGaussian() * 0.02D;
                    double d1 = this.random.nextGaussian() * 0.02D;
                    this.level().addParticle(new ItemParticleOption(ParticleTypes.ITEM, this.getItemInHand(InteractionHand.MAIN_HAND)), this.getX() + (double) (this.random.nextFloat() * this.getBbWidth()) - (double) this.getBbWidth() * 0.5F, this.getY() + this.getBbHeight() * 0.5F + (double) (this.random.nextFloat() * this.getBbHeight() * 0.5F), this.getZ() + (double) (this.random.nextFloat() * this.getBbWidth()) - (double) this.getBbWidth() * 0.5F, d0, d1, d2);
                }
            }
            if (eatingTime % 5 == 0) {
                this.gameEvent(GameEvent.EAT);
                this.playSound(SoundEvents.PANDA_EAT, this.getSoundVolume(), this.getVoicePitch());
            }
            if (eatingTime > 100) {
                ItemStack stack = this.getItemInHand(InteractionHand.MAIN_HAND);
                if (!stack.isEmpty()) {
                    this.heal(4);
                    if (isTameableFood(stack) && bananaThrowerID != null) {
                        if (getRandom().nextFloat() < 0.3F) {
                            this.setTame(true);
                            this.setOwnerUUID(this.bananaThrowerID);
                            Player player = level().getPlayerByUUID(bananaThrowerID);
                            if (player instanceof ServerPlayer) {
                                CriteriaTriggers.TAME_ANIMAL.trigger((ServerPlayer)player, this);
                            }
                            this.level().broadcastEntityEvent(this, (byte) 7);
                        } else {
                            this.level().broadcastEntityEvent(this, (byte) 6);
                        }
                    }
                    if (stack.hasCraftingRemainingItem()) {
                        this.spawnAtLocation(stack.getCraftingRemainingItem());
                    }
                    stack.shrink(1);
                }
                eatingTime = 0;
            }
        }
        prevSitProgress = sitProgress;
        prevStandProgress = standProgress;

        if (this.isSitting()) {
            if (sitProgress < 10F)
                sitProgress++;
        } else {
            if (sitProgress > 0F)
                sitProgress--;
        }

        if (this.isStanding()) {
            if (standProgress < 10F)
                standProgress++;
        } else {
            if (standProgress > 0F)
                standProgress--;
        }

        if (this.isPassenger() && this.getVehicle() instanceof EntityGorilla) {
            if(!this.isBaby()){
                this.removeVehicle();
            }else{
                EntityGorilla mount = (EntityGorilla) this.getVehicle();
                this.setYRot( mount.yBodyRot);
                this.yHeadRot = mount.yBodyRot;
                this.yBodyRot = mount.yBodyRot;
            }
        }
        if (isStanding() && ++standingTime > maxStandTime) {
            this.setStanding(false);
            standingTime = 0;
            maxStandTime = 75 + random.nextInt(50);
        }
        if (!forcedSit && isSitting() && ++sittingTime > maxSitTime) {
            this.setOrderedToSit(false);
            sittingTime = 0;
            maxSitTime = 75 + random.nextInt(50);
        }
        if (!forcedSit && this.isSitting() && (this.getTarget() != null || this.isStanding()) && !this.isEating()) {
            this.setOrderedToSit(false);
        }
        if (!this.level().isClientSide && this.getAnimation() == NO_ANIMATION && !this.isStanding() && !this.isSitting() && random.nextInt(1500) == 0) {
            maxSitTime = 300 + random.nextInt(250);
            this.setOrderedToSit(true);
        }
        if (this.forcedSit && !this.isVehicle() && this.isTame()) {
            this.setOrderedToSit(true);
        }
        if (sitProgress == 0 && poundChestCooldown <= 0 && this.isSilverback() && random.nextInt(800) == 0 && this.getAnimation() == NO_ANIMATION && !this.isSitting() && !this.isNoAi() && this.getMainHandItem().isEmpty()) {
            this.setAnimation(ANIMATION_POUNDCHEST);
        }
        if (!this.level().isClientSide && this.getTarget() != null && this.getAnimation() == ANIMATION_ATTACK && this.getAnimationTick() == 10) {
            float f1 = this.getYRot() * Mth.DEG_TO_RAD;
            this.setDeltaMovement(this.getDeltaMovement().add(-Mth.sin(f1) * 0.02F, 0.0D, Mth.cos(f1) * 0.02F));
            getTarget().knockback(1F, getTarget().getX() - this.getX(), getTarget().getZ() - this.getZ());
            this.getTarget().hurt(this.damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue());
        }
        if (!hasSilverbackAttributes && isSilverback() && !isBaby()) {
            hasSilverbackAttributes = true;
            refreshDimensions();
            this.getAttribute(Attributes.MAX_HEALTH).setBaseValue(50F);
            this.getAttribute(Attributes.ATTACK_DAMAGE).setBaseValue(10F);
            this.heal(50F);
        }
        if (hasSilverbackAttributes && !isSilverback() && !isBaby()) {
            hasSilverbackAttributes = false;
            refreshDimensions();
            this.getAttribute(Attributes.MAX_HEALTH).setBaseValue(30F);
            this.getAttribute(Attributes.ATTACK_DAMAGE).setBaseValue(8F);
            this.heal(30F);
        }
        if(poundChestCooldown > 0){
            poundChestCooldown--;
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

