@Override
    public void start() {
        LivingEntity target = this.worm.getTarget();
        if (target != null) {
            if (worm.isInSand()) {
                BlockPos topSand = worm.blockPosition();
                while (worm.level.getBlockState(topSand.above()).is(BlockTags.SAND)) {
                    topSand = topSand.above();
                }
                worm.setPos(worm.getX(), topSand.getY() + 0.5F, worm.getZ());
            }
            if (shouldJump()) {
                jumpAttack();
            } else {
                worm.getNavigation().moveTo(target, 1.0F);
            }

        }
    }

@Override
    public void tick() {
        if (jumpCooldown > 0) {
            jumpCooldown--;
        }
        LivingEntity target = this.worm.getTarget();
        if (target != null && this.worm.hasLineOfSight(target)) {
            if (this.worm.distanceTo(target) < 3F) {
                this.worm.doHurtTarget(target);
            }
        }

        Vec3 vector3d = this.worm.getDeltaMovement();
        if (vector3d.y * vector3d.y < 0.1F && this.worm.getXRot() != 0.0F) {
            this.worm.setXRot(Mth.rotLerp(this.worm.getXRot(), 0.0F, 0.2F));
        } else {
            final double d0 = vector3d.horizontalDistance();
            final double d1 = Math.signum(-vector3d.y) * Math.acos(d0 / vector3d.length()) * (180F / (float) Math.PI);
            this.worm.setXRot((float) d1);
        }
        if (shouldJump())
            jumpAttack();
        else if (worm.getNavigation().isDone()) {
            worm.getNavigation().moveTo(target, 1.0F);
        }
    }

@Override
    public boolean canUse() {
        if (this.pixie.getItemInHand(InteractionHand.MAIN_HAND).isEmpty() || this.pixie.isTame()) {
            list = Collections.emptyList();
            return false;
        }

        if (this.pixie.level.getGameTime() % 4 == 0) // only update the list every 4 ticks
            list = this.pixie.level.getEntitiesOfClass(this.classToAvoid, this.pixie.getBoundingBox().inflate(this.avoidDistance, 3.0D, this.avoidDistance), EntitySelector.NO_SPECTATORS);

        if (list.isEmpty())
            return false;

        this.closestLivingEntity = list.get(0);
        if (closestLivingEntity != null) {
            Vec3 Vector3d = DefaultRandomPos.getPosAway(this.pixie, 16, 4, new Vec3(this.closestLivingEntity.getX(), this.closestLivingEntity.getY(), this.closestLivingEntity.getZ()));

            if (Vector3d == null) {
                return false;
            } else {
                Vector3d = Vector3d.add(0, 1, 0);
                this.pixie.getMoveControl().setWantedPosition(Vector3d.x, Vector3d.y, Vector3d.z, calculateRunSpeed());
                this.pixie.getLookControl().setLookAt(Vector3d.x, Vector3d.y, Vector3d.z, 180.0F, 20.0F);
                hidePlace = Vector3d;
                pixie.slowSpeed = true;
                return true;
            }
        }
        return false;
    }

