            if (entity instanceof IOwned owned) {
                owned.setRevivingTime(20);
                owned.reviveOwned();
            }
            entity.invulnerableTime = 100;
        }
    }

@Nullable
    public static Entity getSingleTarget(Level pLevel, LivingEntity pSource, double pRange, double pRadius, Predicate<? super Entity> predicate) {
        Entity target = null;
        Vec3 srcVec = pSource.getEyePosition();
        Vec3 lookVec = pSource.getViewVector(1.0F);
        double[] lookRange = new double[] {lookVec.x() * pRange, lookVec.y() * pRange, lookVec.z() * pRange};
        Vec3 destVec = srcVec.add(lookRange[0], lookRange[1], lookRange[2]);
        List<Entity> possibleList = pLevel.getEntities(pSource, pSource.getBoundingBox().expandTowards(lookRange[0], lookRange[1], lookRange[2]).inflate(pRadius, pRadius, pRadius),
                predicate);
        double hitDist = 0.0D;

        for (Entity hit : possibleList) {
            if (pSource.hasLineOfSight(hit) && hit != pSource) {
                float borderSize = Math.max(0.8F, hit.getPickRadius());
                AABB collisionBB = hit.getBoundingBox().inflate(borderSize, borderSize, borderSize);
                Optional<Vec3> interceptPos = collisionBB.clip(srcVec, destVec);

                if (collisionBB.contains(srcVec)) {
                    if (0.0D <= hitDist) {
                        target = hit;
                        hitDist = 0.0D;
                    }
                } else if (interceptPos.isPresent()) {
                    double possibleDist = srcVec.distanceTo(interceptPos.get());

                    if (possibleDist < hitDist || hitDist == 0.0D) {
                        target = hit;
                        hitDist = possibleDist;
                    }
                }
            }
        }
        return target;
    }

public static boolean mobCanAttack(Mob attacker, LivingEntity target){
        if (attacker.getTarget() == target){
            return EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(target) && attacker.canAttack(target);
        }
        return canAttack(attacker, target);
    }

public static boolean ownedCanAttack(OwnableEntity attacker, LivingEntity target){
        if (attacker.getOwner() != null){
            LivingEntity owner = attacker.getOwner();
            if (owner instanceof Mob mob){
                return mobCanAttack(mob, target);
            } else {
                return canAttack(owner, target);
            }
        }
        if (attacker instanceof Mob mob) {
            return mobCanAttack(mob, target);
        }
        return false;
    }

@Override
    public @NotNull InteractionResult mobInteract(Player player, @NotNull InteractionHand hand) {
        ItemStack stack = player.getItemInHand(hand);
        if (!player.level().isClientSide) {
            if (this.isOwnedBy(player)) {

                if (stack.is(Tags.Items.DYES_YELLOW) && !this.getColor().equals("flashjack")) {
                    this.setColor("flashjack");
                    stack.shrink(1);
                    return InteractionResult.SUCCESS;
                }

                if (stack.is(Tags.Items.DYES_RED) && !this.getColor().equals("flapjack")) {
                    this.setColor("flapjack");
                    stack.shrink(1);
                    return InteractionResult.SUCCESS;
                }

                if (stack.is(Tags.Items.DYES_BLUE) && !this.getColor().equals("bluejay")) {
                    this.setColor("bluejay");
                    stack.shrink(1);
                    return InteractionResult.SUCCESS;
                }

                if (stack.getItem() == ModItems.FLASHING_POD.get().asItem()) {
                    var flash = new FlashLightning(this.level);
                    flash.setPos(this.getX(), this.getY(), this.getZ());
                    player.level().addFreshEntity(flash);
                    Networking.sendToNearbyClient(this.level, this, new PacketAnimEntity(this.getId(), 0));
                }

            } else if (stack.getItem() == ModItems.FLASHING_POD.get().asItem()) {
                entityData.set(BEING_TAMED, true);
                stack.shrink(1);
            }
        }
        if (!this.isFlying() && this.isTame() && this.isOwnedBy(player) && stack.isEmpty()) {
            if (!level().isClientSide())
                this.setOrderedToSit(!this.isOrderedToSit());
            return InteractionResult.sidedSuccess(this.level().isClientSide);
        }
        return InteractionResult.PASS;
    }

