@Override
    public void onResolve(HitResult rayTraceResult, Level world, @Nullable LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {
        if (!canSummon(shooter))
            return;

        Vec3 vector3d = safelyGetHitPos(rayTraceResult);
        int ticks = (int) (20 * (GENERIC_INT.get() + EXTEND_TIME.get() * spellStats.getDurationMultiplier()));
        BlockPos pos = BlockPos.containing(vector3d);
        if (ticks <= 0) return;
        int count = 3 + spellStats.getBuffCount(AugmentSplit.INSTANCE);
        for (int i = 0; i < count; ++i) {
            BlockPos blockpos = pos.offset(-2 + shooter.getRandom().nextInt(5), 2, -2 + shooter.getRandom().nextInt(5));

            ItemStack weapon = Items.IRON_SWORD.getDefaultInstance();
            if ((spellStats.hasBuff(AugmentPierce.INSTANCE))) {
                weapon = Items.BOW.getDefaultInstance();
                if (spellStats.getAmpMultiplier() > 0)
                    weapon.enchant(HolderHelper.unwrap(world, Enchantments.POWER), Math.max(4, (int) spellStats.getAmpMultiplier()) - 1);
            } else {
                if (spellStats.getAmpMultiplier() >= 3) {
                    weapon = Items.NETHERITE_AXE.getDefaultInstance();
                } else if (spellStats.getAmpMultiplier() > 2) {
                    weapon = Items.NETHERITE_SWORD.getDefaultInstance();
                } else if (spellStats.getAmpMultiplier() > 1) {
                    weapon = Items.DIAMOND_SWORD.getDefaultInstance();
                }
            }
            SummonSkeleton undeadentity = new SummonSkeleton(world, shooter, weapon);
            undeadentity.moveTo(blockpos, 0.0F, 0.0F);
            undeadentity.finalizeSpawn((ServerLevelAccessor) world, world.getCurrentDifficultyAt(blockpos), MobSpawnType.MOB_SUMMONED, null);
            undeadentity.setOwner(shooter);
            undeadentity.setLimitedLife(ticks);
            summonLivingEntity(rayTraceResult, world, shooter, spellStats, spellContext, resolver, undeadentity);
        }
        shooter.addEffect(new MobEffectInstance(ModPotions.SUMMONING_SICKNESS_EFFECT, ticks));
    }

@Override
    public void onResolve(HitResult rayTraceResult, Level world, @Nullable LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {

        if (!canSummon(shooter))
            return;

        int ticks = (int) (20 * (GENERIC_INT.get() + EXTEND_TIME.get() * spellStats.getDurationMultiplier()));
        if (ticks <= 0)
            ticks = 20; //leave at least one second of life, since summon sick doesn't depend on it and short life horses can be useful (?)
        Vec3 hit = rayTraceResult.getLocation();
        for (int i = 0; i < 1 + Math.round(spellStats.getAoeMultiplier()); i++) {
            SummonHorse horse = new SummonHorse(ModEntities.SUMMON_HORSE.get(), world);
            horse.setPos(hit.x(), hit.y(), hit.z());
            horse.ticksLeft = ticks;
            horse.tameWithName((Player) shooter);
            horse.getHorseInventory().setItem(0, new ItemStack(Items.SADDLE));
            horse.setOwnerID(shooter.getUUID());
            horse.setDropChance(EquipmentSlot.CHEST, 0.0F);
            summonLivingEntity(rayTraceResult, world, shooter, spellStats, spellContext, resolver, horse);
        }
        applySummoningSickness(shooter, 30 * 20);
    }

@Override
    public void onResolve(HitResult rayTraceResult, Level world, @Nullable LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {
        if (!canSummon(shooter) || shooter == null)
            return;
        Vec3 hit = rayTraceResult.getLocation();
        int ticks = (int) (20 * (GENERIC_INT.get() + EXTEND_TIME.get() * spellStats.getDurationMultiplier()));
        if (ticks <= 0) return;
        Holder<Biome> holder = world.getBiome(BlockPos.containing(rayTraceResult.getLocation()));
        var wolfVariant = WolfVariants.getSpawnVariant(world.registryAccess(), holder);
        for (int i = 0; i < 2; i++) {
            SummonWolf wolf = new SummonWolf(ModEntities.SUMMON_WOLF.get(), world);
            wolf.ticksLeft = ticks;
            wolf.setVariant(wolfVariant);
            wolf.setPos(hit.x(), hit.y(), hit.z());
            wolf.setTarget(shooter.getLastHurtMob() == null ? shooter.getLastHurtByMob() : shooter.getLastHurtMob());
            wolf.setAggressive(true);
            wolf.setTame(true, false);
            wolf.tame((Player) shooter);
            summonLivingEntity(rayTraceResult, world, shooter, spellStats, spellContext, resolver, wolf);
        }
        applySummoningSickness(shooter, ticks);
    }

@SubscribeEvent
    public static void castSpell(SpellCastEvent event) {
        if (!event.getWorld().isClientSide && event.getEntity() instanceof Player && SummoningFocus.containsThis(event.getWorld(), event.getEntity())) {
            if (event.spell.getCastMethod() != null && sympatheticMethods.contains(event.spell.getCastMethod())) {
                for (LivingEntity i : event.getWorld().getEntitiesOfClass(LivingEntity.class, new AABB(event.getEntity().blockPosition()).inflate(30), ISummon.class::isInstance)) {
                    if (event.getEntity().equals(((ISummon) i).getOwnerAlt())) {
                        EntitySpellResolver spellResolver = new EntitySpellResolver(event.context.clone().withWrappedCaster(new LivingCaster(i)));
                        spellResolver.onCast(ItemStack.EMPTY, i.level);
                    }
                }
            }
        }
    }

