@Override
        public boolean canStart() {
            Box box = this.guard.getBoundingBox().expand(10.0D, 8.0D, 10.0D);
            List<VillagerEntity> list = guard.getWorld().getNonSpectatingEntities(VillagerEntity.class, box);
            List<PlayerEntity> list1 = guard.getWorld().getNonSpectatingEntities(PlayerEntity.class, box);
            for (VillagerEntity villager : list) {
                for (PlayerEntity player : list1) {
                    int i = villager.getReputation(player);
                    if (i <= GuardVillagersConfig.reputationRequirementToBeAttacked) {
                        this.villageAggressorTarget = player;
                    }
                }
            }
            return villageAggressorTarget != null && !villageAggressorTarget.hasStatusEffect(StatusEffects.HERO_OF_THE_VILLAGE) && !this.villageAggressorTarget.isSpectator() && !((PlayerEntity) this.villageAggressorTarget).isCreative();
        }

@Override
    public void stop() {
        super.stop();
        this.mob.setAttacking(false);
        this.mob.setTarget(null);
        this.seeTime = 0;
        if (this.mob.isUsingItem()) {
            this.mob.stopUsingItem();
            this.mob.setCharging(false);
        }
        this.mob.setPose(EntityPose.STANDING);
    }

@Override
    public void tick() {
        LivingEntity livingentity = this.mob.getTarget();
        if (livingentity != null) {
            boolean canSee = this.mob.getVisibilityCache().canSee(livingentity);
            boolean hasSeenEntityRecently = this.seeTime > 0;
            if (canSee != hasSeenEntityRecently) {
                this.seeTime = 0;
            }
            if (canSee) {
                ++this.seeTime;
            } else {
                --this.seeTime;
            }
            double d0 = this.mob.squaredDistanceTo(livingentity);
            double d1 = livingentity.distanceTo(this.mob);
            if (d1 <= 4.0D) {
                this.mob.getMoveControl().strafeTo(this.mob.isUsingItem() ? -0.5F : -3.0F, 0.0F);
                this.mob.lookAtEntity(livingentity, 30.0F, 30.0F);
            }
            if (this.mob.getRandom().nextInt(50) == 0) {
                if (this.mob.isInPose(EntityPose.STANDING))
                    this.mob.setPose(EntityPose.CROUCHING);
                else
                    this.mob.setPose(EntityPose.STANDING);
            }
            boolean canSee2 = (d0 > (double) this.attackRadiusSqr || this.seeTime < 5) && this.attackDelay == 0;
            if (canSee2) {
                --this.updatePathDelay;
                if (this.updatePathDelay <= 0) {
                    this.mob.getNavigation().startMovingTo(livingentity, this.canRun() ? this.speedModifier : this.speedModifier * 0.5D);
                    this.updatePathDelay = PATHFINDING_DELAY_RANGE.get(this.mob.getRandom());
                }
            } else {
                this.updatePathDelay = 0;
                this.mob.getNavigation().stop();
            }
            this.mob.lookAtEntity(livingentity, 30.0F, 30.0F);
            this.mob.getLookControl().lookAt(livingentity, 30.0F, 30.0F);
            if (this.friendlyInLineOfSight() && GuardVillagersConfig.friendlyFire)
                this.crossbowState = CrossbowState.FIND_NEW_POSITION;
            if (this.crossbowState == CrossbowState.FIND_NEW_POSITION && GuardVillagersConfig.friendlyFire) {
                this.mob.stopUsingItem();
                this.mob.setCharging(false);
                if (this.findPosition())
                    this.mob.getNavigation().startMovingTo(this.wantedX, this.wantedY, this.wantedZ, this.mob.isSneaking() ? 0.5F : 1.2D);
                this.crossbowState = CrossbowState.UNCHARGED;
            } else if (this.crossbowState == CrossbowState.UNCHARGED) {
                if (hasSeenEntityRecently) {
                    this.mob.setCurrentHand(GuardVillagers.getHandWith(this.mob, item -> item instanceof CrossbowItem));
                    this.crossbowState = CrossbowState.CHARGING;
                    this.mob.setCharging(true);
                }
            } else if (this.crossbowState == CrossbowState.CHARGING) {
                if (!this.mob.isUsingItem()) {
                    this.crossbowState = CrossbowState.UNCHARGED;
                }
                int i = this.mob.getItemUseTime();
                ItemStack itemstack = this.mob.getActiveItem();
                if (i >= CrossbowItem.getPullTime(itemstack) || CrossbowItem.isCharged(itemstack)) {
                    this.mob.stopUsingItem();
                    this.crossbowState = CrossbowState.CHARGED;
                    this.attackDelay = 10 + this.mob.getRandom().nextInt(5);
                    this.mob.setCharging(false);
                }
            } else if (this.crossbowState == CrossbowState.CHARGED) {
                --this.attackDelay;
                if (this.attackDelay == 0) {
                    this.crossbowState = CrossbowState.READY_TO_ATTACK;
                }
            } else if (this.crossbowState == CrossbowState.READY_TO_ATTACK && canSee) {
                this.mob.attack(livingentity, 1.0F);
                ItemStack itemstack1 = this.mob.getStackInHand(GuardVillagers.getHandWith(this.mob, item -> item instanceof CrossbowItem));
                CrossbowItem.setCharged(itemstack1, false);
                this.crossbowState = CrossbowState.UNCHARGED;
            }
        }

    }

public static void handle(GuardFollowPacket guardFollowPacket, ServerPlayerEntity serverPlayerEntity, PacketSender packetSender) {
        int entityId = guardFollowPacket.id;

        Entity entity = serverPlayerEntity.getWorld().getEntityById(entityId);
        if (entity instanceof GuardEntity guardEntity) {
            guardEntity.setFollowing(!guardEntity.isFollowing());
            guardEntity.setOwnerId(serverPlayerEntity.getUuid());
            guardEntity.playSound(SoundEvents.ENTITY_VILLAGER_YES, 1, 1);
        }
    }

default void summonMinions(MobEntity pledgeable) {
		if (!pledgeable.getWorld().isClient && pledgeable.getWorld().getEntitiesByType(getMinionType(), new Box(pledgeable.getBlockPos()).expand(32), entity -> entity instanceof MobEntity mobEntity && !entity.isRemoved() && pledgeable.getUuid().equals(BWComponents.MINION_COMPONENT.get(mobEntity).getMaster())).size() < 3) {
			for (int i = 0; i < MathHelper.nextInt(pledgeable.getRandom(), 2, 3); i++) {
				Entity entity = getMinionType().create(pledgeable.getWorld());
				if (entity instanceof MobEntity mobEntity) {
					BWUtil.attemptTeleport(entity, pledgeable.getBlockPos().up(), 3, true);
					mobEntity.initialize((ServerWorldAccess) pledgeable.getWorld(), pledgeable.getWorld().getLocalDifficulty(pledgeable.getBlockPos()), SpawnReason.EVENT, null, null);
					entity.setPitch(pledgeable.getRandom().nextFloat() * 360);
					mobEntity.setTarget(pledgeable.getTarget());
					BWComponents.MINION_COMPONENT.get(mobEntity).setMaster(pledgeable.getUuid());
					mobEntity.setPersistent();
					getMinionBuffs().forEach(mobEntity::addStatusEffect);
					pledgeable.getWorld().spawnEntity(entity);
				}
			}
		}
	}

public static ActiveTargetGoal<LivingEntity> createGenericPledgeableTargetGoal(MobEntity entity) {
		return new ActiveTargetGoal<>(entity, LivingEntity.class, 10, true, false, foundEntity -> {
			if (foundEntity instanceof ArmorStandEntity) {
				return false;
			}
			if (foundEntity instanceof PlayerEntity player) {
				if (BewitchmentAPI.isPledged(player, ((Pledgeable) entity).getPledgeID())) {
					return false;
				}
			} else if (foundEntity.getGroup() == BewitchmentAPI.DEMON) {
				return false;
			}
			return BWUtil.getArmorPieces(foundEntity, stack -> stack.getItem() instanceof ArmorItem armorItem && armorItem.getMaterial() == BWMaterials.BESMIRCHED_ARMOR) < 3;
		});
	}

@Override
    public boolean isAlliedTo(Entity entityIn) {
        if (this.getTrueOwner() == null) {
            if (entityIn instanceof EnderMan){
                return this.getTeam() == null && entityIn.getTeam() == null;
            } else if (entityIn instanceof AbstractEnderling enderling){
                if (this.getTeam() == null && entityIn.getTeam() == null) {
                    if (enderling.getTrueOwner() != null) {
                        return super.isAlliedTo(entityIn);
                    }
                    if (this.getTarget() == entityIn) {
                        return false;
                    }
                    if (enderling.getTarget() == this) {
                        return false;
                    }
                    return (this.isHostile() && enderling.isHostile()) || (!this.isHostile() && !enderling.isHostile());
                }
            }
        }
        return super.isAlliedTo(entityIn);
    }

public boolean hurt(DamageSource pSource, float pAmount) {
        if (pSource.getEntity() != null){
            if (pSource.getEntity() instanceof LivingEntity livingEntity){
                if (!(livingEntity instanceof ZombifiedPiglin) && !livingEntity.isAlliedTo(this)){
                    for (ZombifiedPiglin zombifiedPiglin : this.level.getEntitiesOfClass(ZombifiedPiglin.class, this.getBoundingBox().inflate(10))){
                        if (zombifiedPiglin.getTarget() != livingEntity) {
                            if (zombifiedPiglin.canAttack(livingEntity)) {
                                zombifiedPiglin.startPersistentAngerTimer();
                                zombifiedPiglin.setPersistentAngerTarget(livingEntity.getUUID());
                                zombifiedPiglin.setTarget(livingEntity);
                            }
                        }
                    }
                }
            }
        }
        return !this.isInvulnerableTo(pSource) && super.hurt(pSource, pAmount);
    }

public InteractionResult mobInteract(Player pPlayer, InteractionHand pHand) {
        ItemStack itemstack = pPlayer.getItemInHand(pHand);
        Item item = itemstack.getItem();
        if (this.getTrueOwner() != null && pPlayer == this.getTrueOwner()) {
            if (this.validFood(itemstack)) {
                if (this.canHaveMoreFood() && this.getInventory().canAddItem(itemstack)) {
                    this.getInventory().addItem(itemstack.copyWithCount(1));
                    if (!pPlayer.getAbilities().instabuild) {
                        itemstack.shrink(1);
                    }
                    this.playSound(SoundEvents.ITEM_PICKUP, 1.0F, 1.0F);
                    if (this.level instanceof ServerLevel serverLevel) {
                        for (int i = 0; i < 7; ++i) {
                            double d0 = this.random.nextGaussian() * 0.02D;
                            double d1 = this.random.nextGaussian() * 0.02D;
                            double d2 = this.random.nextGaussian() * 0.02D;
                            serverLevel.sendParticles(ParticleTypes.HAPPY_VILLAGER, this.getRandomX(1.0D), this.getRandomY() + 0.5D, this.getRandomZ(1.0D), 0, d0, d1, d2, 0.5F);
                        }
                    }
                    return InteractionResult.SUCCESS;
                }
            } else if (item instanceof ArmorItem && this.canWearArmor()) {
                return ServantUtil.equipServantArmor(pPlayer, this, itemstack, super.mobInteract(pPlayer, pHand));
            } else if (pPlayer.getMainHandItem().is(ModItems.WAYSTONE.get())) {
                if (WaystoneItem.isSameDimension(this, pPlayer.getMainHandItem())) {
                    if (WaystoneItem.getBlockEntity(pPlayer.getMainHandItem(), this.level) instanceof ChestBlockEntity chestBlock && chestBlock.canOpen(pPlayer)) {
                        if (!this.level.isClientSide) {
                            BlockPos blockPos = WaystoneItem.getBlockPos(pPlayer.getMainHandItem());
                            if (blockPos != null) {
                                this.playSound(SoundEvents.ARROW_HIT_PLAYER, 1.0F, 0.45F);
                                if (this.level instanceof ServerLevel serverLevel) {
                                    for (int i = 0; i < 7; ++i) {
                                        double d0 = this.random.nextGaussian() * 0.02D;
                                        double d1 = this.random.nextGaussian() * 0.02D;
                                        double d2 = this.random.nextGaussian() * 0.02D;
                                        serverLevel.sendParticles(ParticleTypes.HAPPY_VILLAGER, this.getRandomX(1.0D), this.getRandomY() + 0.5D, this.getRandomZ(1.0D), 0, d0, d1, d2, 0.5F);
                                    }
                                }
                                if (chestBlock.getBlockState().is(ModTags.Blocks.RAIDING_CHESTS)) {
                                    this.setDumpChestPos(blockPos);
                                    this.setDumpChestDim(this.level.dimension());
                                } else {
                                    this.setChestPos(blockPos);
                                    this.setChestDim(this.level.dimension());
                                }
                                if (this.isLeader()) {
                                    for (RaiderServant servant : this.getNearbyCompanions()) {
                                        if (servant instanceof AbstractIllagerServant servant1) {
                                            if (chestBlock.getBlockState().is(ModTags.Blocks.RAIDING_CHESTS)) {
                                                servant1.setDumpChestPos(blockPos);
                                                servant1.setDumpChestDim(this.level.dimension());
                                            } else {
                                                servant1.setChestPos(blockPos);
                                                servant1.setChestDim(this.level.dimension());
                                            }
                                        }
                                    }
                                }
                                return InteractionResult.SUCCESS;
                            }
                            return InteractionResult.FAIL;
                        }
                    }
                }
            } else if (itemstack.is(Items.TOTEM_OF_UNDYING) && this.getOffhandItem().isEmpty()) {
                this.setItemSlot(EquipmentSlot.OFFHAND, itemstack.copyWithCount(1));
                if (!pPlayer.getAbilities().instabuild) {
                    itemstack.shrink(1);
                }
                if (this.getCelebrateSound() != null) {
                    this.playSound(this.getCelebrateSound(), 1.0F, 1.0F);
                }
                this.playSound(SoundEvents.ITEM_PICKUP, 1.0F, 1.0F);
                if (this.level instanceof ServerLevel serverLevel) {
                    for (int i = 0; i < 7; ++i) {
                        double d0 = this.random.nextGaussian() * 0.02D;
                        double d1 = this.random.nextGaussian() * 0.02D;
                        double d2 = this.random.nextGaussian() * 0.02D;
                        serverLevel.sendParticles(ParticleTypes.HAPPY_VILLAGER, this.getRandomX(1.0D), this.getRandomY() + 0.5D, this.getRandomZ(1.0D), 0, d0, d1, d2, 0.5F);
                    }
                }
                return InteractionResult.SUCCESS;
            } else if (itemstack.is(Items.STICK)) {
                if (this.getOffhandItem().is(Items.TOTEM_OF_UNDYING)) {
                    ItemStack totem = this.getOffhandItem();
                    this.setItemSlot(EquipmentSlot.OFFHAND, ItemStack.EMPTY);
                    this.dropEquipment(EquipmentSlot.OFFHAND, totem);
                    this.playSound(SoundEvents.BUNDLE_DROP_CONTENTS, 1.0F, 1.0F);
                    return InteractionResult.SUCCESS;
                } else if (!this.getCharm().isEmpty()) {
                    this.spawnAtLocation(this.getCharm());
                    this.setCharm(ItemStack.EMPTY);
                    this.playSound(SoundEvents.BUNDLE_DROP_CONTENTS, 1.0F, 1.0F);
                    return InteractionResult.SUCCESS;
                }
            } else if (itemstack.getItem() instanceof IMobCharm) {
                ItemStack charm = this.getCharm();
                if (!charm.isEmpty()) {
                    this.spawnAtLocation(charm);
                }
                this.setCharm(itemstack.split(1));
                this.playSound(SoundEvents.ARMOR_EQUIP_GENERIC, 1.0F, 1.0F);
                if (this.level instanceof ServerLevel serverLevel) {
                    for (int i = 0; i < 7; ++i) {
                        double d0 = this.random.nextGaussian() * 0.02D;
                        double d1 = this.random.nextGaussian() * 0.02D;
                        double d2 = this.random.nextGaussian() * 0.02D;
                        serverLevel.sendParticles(ParticleTypes.HAPPY_VILLAGER, this.getRandomX(1.0D), this.getRandomY() + 0.5D, this.getRandomZ(1.0D), 0, d0, d1, d2, 0.5F);
                    }
                }
                return InteractionResult.SUCCESS;
            }
        }
        return super.mobInteract(pPlayer, pHand);
    }

@Override
    public InteractionResult mobInteract(Player pPlayer, InteractionHand pHand) {
        ItemStack itemInHand = pPlayer.getItemInHand(pHand);
        Item item = itemInHand.getItem();
        ItemStack mainHandItem = this.getMainHandItem();
        if (pPlayer.isCrouching() && !(item.interactLivingEntity(itemInHand, pPlayer, this, pHand).consumesAction() || itemInHand.is(ModTags.Items.GRIMOIRES))) {
            this.unshackle(pPlayer);
            return InteractionResult.SUCCESS;
        } else if (this.getMasterOwner() != null && this.getMasterOwner() == pPlayer) {
            if (MobsConfig.PrisonerMining.get() && (item instanceof PickaxeItem || itemInHand.is(ItemTags.PICKAXES))) {
                this.playSound(SoundEvents.ARMOR_EQUIP_GENERIC, 1.0F, 1.0F);
                this.setItemSlot(EquipmentSlot.MAINHAND, itemInHand.copyWithCount(1));
                this.dropEquipment(EquipmentSlot.MAINHAND, mainHandItem);
                this.setGuaranteedDrop(EquipmentSlot.MAINHAND);
                if (!pPlayer.getAbilities().instabuild) {
                    itemInHand.shrink(1);
                }
                this.updateList = 5;
                return InteractionResult.SUCCESS;
            } else if (pPlayer.getMainHandItem().is(Items.STICK)) {
                this.dropEquipment(EquipmentSlot.MAINHAND, this.getMainHandItem());
                this.setItemInHand(InteractionHand.MAIN_HAND, ItemStack.EMPTY);
                return InteractionResult.SUCCESS;
            } else if (this.validFood(itemInHand) && this.canHaveMoreFood() && this.getInventory().canAddItem(itemInHand)) {
                this.getInventory().addItem(itemInHand.copyWithCount(1));
                if (!pPlayer.getAbilities().instabuild) {
                    itemInHand.shrink(1);
                }
                this.playSound(SoundEvents.ITEM_PICKUP, 1.0F, 1.0F);
                return InteractionResult.SUCCESS;
            } else if (pPlayer.getMainHandItem().is(ModItems.WAYSTONE.get())) {
                if (WaystoneItem.isSameDimension(this, pPlayer.getMainHandItem())) {
                    if (WaystoneItem.getBlockEntity(pPlayer.getMainHandItem(), this.level) instanceof ChestBlockEntity chestBlock && chestBlock.canOpen(pPlayer)) {
                        if (!this.level.isClientSide) {
                            BlockPos blockPos = WaystoneItem.getBlockPos(pPlayer.getMainHandItem());
                            if (blockPos != null) {
                                this.playSound(SoundEvents.ARROW_HIT_PLAYER, 1.0F, 0.45F);
                                if (this.level instanceof ServerLevel serverLevel) {
                                    for (int i = 0; i < 7; ++i) {
                                        double d0 = this.random.nextGaussian() * 0.02D;
                                        double d1 = this.random.nextGaussian() * 0.02D;
                                        double d2 = this.random.nextGaussian() * 0.02D;
                                        serverLevel.sendParticles(ParticleTypes.ANGRY_VILLAGER, this.getRandomX(1.0D), this.getRandomY() + 0.5D, this.getRandomZ(1.0D), 0, d0, d1, d2, 0.5F);
                                    }
                                }
                                if (chestBlock.getBlockState().is(ModTags.Blocks.RAIDING_CHESTS)) {
                                    this.setDumpChestPos(blockPos);
                                    this.setDumpChestDim(this.level.dimension());
                                } else {
                                    this.setChestPos(blockPos);
                                    this.setChestDim(this.level.dimension());
                                }
                                return InteractionResult.SUCCESS;
                            }
                        }
                    }
                }
                return InteractionResult.FAIL;
            } else if (pPlayer.getMainHandItem().isEmpty() && this.isMining()) {
                float f = (float)Mth.floor((Mth.wrapDegrees(pPlayer.getYRot() - 180.0F) + 22.5F) / 45.0F) * 45.0F;
                this.setYRot(f);
                this.setYBodyRot(f);
                this.setYHeadRot(f);
                this.setCustomLook(f);
                this.playSound(SoundEvents.VILLAGER_NO, 1.0F, 0.75F);
                return InteractionResult.SUCCESS;
            } else if (this.getLeader() != null) {
                this.setLeader(null);
                this.setFollowing();
                return InteractionResult.SUCCESS;
            } else if (this.getTrueOwner() instanceof OwnableEntity ownable && ownable.getOwner() == pPlayer) {
                this.setTrueOwner(pPlayer);
                this.setFollowing();
                return InteractionResult.SUCCESS;
            }
        }
        return InteractionResult.PASS;
    }

public void dealDamageTo(LivingEntity target) {
        LivingEntity owner = this.getOwner();
        float baseDamage = SpellConfig.FangDamage.get().floatValue() * WandUtil.damageMultiply();
        baseDamage += this.damage;
        boolean hurt;
        if (target.isAlive() && !target.isInvulnerable()) {
            if (owner == null) {
                hurt = target.hurt(this.damageSources().magic(), baseDamage);
            } else {
                if (target == owner){
                    return;
                }
                if (owner instanceof Mob mobOwner) {
                    if (mobOwner instanceof Enemy && target instanceof Enemy) {
                        if (mobOwner.getTarget() != target) {
                            return;
                        }
                    }
                    if (mobOwner instanceof IOwned owned){
                        if (owned.getTrueOwner() != null){
                            if (MobUtil.areAllies(owned.getTrueOwner(), target)){
                                return;
                            }
                        }
                    }
                }
                if (MobUtil.areAllies(target, owner)){
                    return;
                }
                if (owner instanceof Player player){
                    hurt = target.hurt(this.damageSources().indirectMagic(this, owner), baseDamage);
                    if (hurt){
                        if (SEHelper.getSoulGiven(target) > 0) {
                            int soulEater = Mth.clamp(this.getSoulEater(), 0, 10);
                            SEHelper.increaseSouls(player, SpellConfig.FangGainSouls.get() * soulEater);
                        }
                        if (this.burning > 0){
                            target.setSecondsOnFire(5 * this.burning);
                        }
                    }
                } else {
                    hurt = target.hurt(this.damageSources().indirectMagic(this, owner), baseDamage);
                }
            }
            if (hurt) {
                target.invulnerableTime = 11;
                target.knockback(1.0D, (this.getX() - target.getX()) * MathHelper.modelDegrees(45), (this.getZ() - target.getZ()) * MathHelper.modelDegrees(45));
            }
        }
    }

private void dealDamageTo(LivingEntity target) {
        LivingEntity livingentity = this.getOwner();
        float baseDamage = SpellConfig.EarthFistDamage.get().floatValue() * WandUtil.damageMultiply();
        baseDamage += this.getExtraDamage();
        if (target.isAlive() && !target.isInvulnerable()) {
            boolean hurt;
            if (livingentity == null) {
                hurt = target.hurt(this.damageSources().mobProjectile(this, null), baseDamage);
            } else {
                if (target == livingentity){
                    return;
                }
                if (MobUtil.areAllies(target, livingentity)){
                    return;
                }
                hurt = target.hurt(this.damageSources().mobProjectile(this, livingentity), baseDamage);
            }
            if (hurt) {
                MobUtil.push(target, 0, 1, 0);
            } else {
                target.move(MoverType.SHULKER_BOX, new Vec3(0, this.getBbHeight(), 0));
            }
        }
    }

public void tick() {
        super.tick();
        if (!this.level.isClientSide) {
            if (this.getLifespan() < getTotalLife()) {
                ++this.lifespan;
            } else {
                this.trueRemove();
            }
            if (this.getTrueOwner() != null){
                if (this.getTarget() != null){
                    LivingEntity livingentity = this.getTarget();
                    double d1 = livingentity.getX() - this.getX();
                    double d2 = livingentity.getY(0.5D) - this.getY(0.5D);
                    double d3 = livingentity.getZ() - this.getZ();
                    if (this.tickCount % 50 == 0) {
                        this.fakeRemove(d1, d2, d3);
                    }
                }
            }
            int maxSpun = 80;
            if (this.getSpun() >= maxSpun) {
                this.trueRemove();
            }
            List<LivingEntity> targets = new ArrayList<>();
            for (Entity entity : this.level.getEntitiesOfClass(Entity.class, this.getBoundingBox().inflate(this.getSize()))) {
                LivingEntity livingEntity = MobUtil.getLivingTarget(entity);
                if (livingEntity != null) {
                    if (this.getOwner() != null) {
                        if (livingEntity != this.getOwner() && !MobUtil.areAllies(this.getOwner(), livingEntity)) {
                            targets.add(livingEntity);
                        }
                    } else {
                        targets.add(livingEntity);
                    }
                }
            }
            if (!targets.isEmpty()) {
                for (LivingEntity entity : targets) {
                    if (MobUtil.validEntity(entity)) {
                        this.suckInMobs(entity);
                    }
                }
            }
        }
    }

public void fakeRemove(double x, double y, double z){
        Cyclone cyclone = new Cyclone(this.level, this.getTrueOwner(), x, y, z);
        cyclone.setOwner(this.getTrueOwner());
        cyclone.setTarget(this.getTarget());
        cyclone.setLifespan(this.getLifespan());
        cyclone.setTotalLife(this.getTotalLife());
        cyclone.setSpun(this.getSpun());
        cyclone.setSize(this.getSize());
        cyclone.setDamage(this.getDamage());
        cyclone.setExtraDamage(this.getExtraDamage());
        cyclone.setPos(this.getX(), this.getY(), this.getZ());
        this.level.addFreshEntity(cyclone);
        this.remove();
    }

@Override
    public void tick() {
        LivingEntity owner = getOwner();
        if (this.level.isClientSide) {
            if (this.owner instanceof Player) {
                ModNetwork.INSTANCE.sendToServer(new CBeamPacket(this));
            }
            this.updatePositionAndRotation();
        }

        if (owner != null && owner.isAlive() && SpellConfig.CorruptionImmobile.get()){
            owner.setDeltaMovement(0, owner.getDeltaMovement().y, 0);
            owner.xxa = 0.0F;
            owner.zza = 0.0F;
        }

        if (!this.level.isClientSide) {
            if (owner == null || !owner.isAlive() || (this.itemBase && !MobUtil.isSpellCasting(owner))) {
                this.discard();
                return;
            }

            this.updatePositionAndRotation();
            Set<LivingEntity> entities = new HashSet<>();
            AABB aabb = new AABB(this.position(), this.position()).inflate(this.beamWidth);
            double distanceToDestination = beamTraceDistance(MAX_RAYTRACE_DISTANCE, 1.0f, false);
            double distanceTraveled = 0;
            while (!(this.position().distanceTo(aabb.getCenter()) > distanceToDestination) && !(this.position().distanceTo(aabb.getCenter()) > MAX_RAYTRACE_DISTANCE)) {
                for (Entity entity : this.level.getEntitiesOfClass(Entity.class, aabb)) {
                    LivingEntity livingEntity = MobUtil.getLivingTarget(entity);
                    if (livingEntity != null && canHitEntity(owner).test(livingEntity)) {
                        entities.add(livingEntity);
                    }
                }
                distanceTraveled += 1.0D;
                Vec3 viewVector = this.getViewVector(1.0F);
                Vec3 targetVector = this.position().add(viewVector.x * distanceTraveled, viewVector.y * distanceTraveled, viewVector.z * distanceTraveled);
                aabb = new AABB(targetVector, targetVector).inflate(this.beamWidth);
            }
            this.damageEntities(entities);
        }
    }

public void damageEntities(Set<LivingEntity> entities){
        for (LivingEntity entity : entities) {
            entity.invulnerableTime = 0;
            Vec3 deltaMovement = entity.getDeltaMovement();
            float damage = SpellConfig.CorruptedBeamDamage.get().floatValue() * WandUtil.damageMultiply();
            damage += this.extraDamage;
            entity.hurt(entity.damageSources().indirectMagic(owner, owner), damage);
            entity.setDeltaMovement(deltaMovement);
        }
    }

@Override
    public void tick() {
        super.tick();
        if (!this.level.isClientSide){
            this.cloudParticles(this.getColor());
            if (this.activated) {
                if (this.lifeSpan > 0) {
                    --this.lifeSpan;
                    this.rainParticles(this.getRainParticle());
                    AABB below = this.getBoundingBox().move(0, -16, 0).inflate(0, 16, 0);

                    for (Entity entity : this.level.getEntitiesOfClass(Entity.class, below)) {
                        LivingEntity livingEntity = MobUtil.getLivingTarget(entity);
                        if (livingEntity != null) {
                            boolean flag = false;
                            if (this.getOwner() != null) {
                                if (livingEntity != this.getOwner() && !MobUtil.areAllies(this.getOwner(), livingEntity)){
                                    flag = true;
                                }
                            } else {
                                flag = true;
                            }
                            if (flag) {
                                int distance = (int) (this.getY() - livingEntity.getY());
                                if (BlockFinder.emptySpaceBetween(this.level, livingEntity.blockPosition(), distance, true)) {
                                    this.hurtEntities(livingEntity);
                                }
                            }
                        }
                    }
                } else {
                    this.discard();
                }
            } else {
                if (this.tickCount % this.activateTime == 0){
                    this.activated = true;
                }
            }
        }
    }

public void hurtEntities(LivingEntity livingEntity){
        ColorUtil colorUtil = new ColorUtil(this.getLightningColor());
        if (this.level instanceof ServerLevel serverLevel) {
            if (livingEntity != null && !livingEntity.isDeadOrDying() && EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(livingEntity)) {
                if (livingEntity.isSensitiveToWater()) {
                    livingEntity.hurt(livingEntity.damageSources().indirectMagic(this, this.getOwner()), 1.0F);
                }
                if (this.random.nextFloat() <= 0.05F) {
                    Vec3 vec3 = this.position();
                    float damage = SpellConfig.ThunderboltDamage.get().floatValue() * WandUtil.damageMultiply();
                    damage += this.getExtraDamage();
                    BlockHitResult rayTraceResult = this.blockResult(serverLevel, this, 16);
                    Optional<BlockPos> lightningRod = BlockFinder.findLightningRod(serverLevel, BlockPos.containing(rayTraceResult.getLocation()), 16);
                    if (lightningRod.isPresent() && !this.isStaff()) {
                        BlockPos blockPos = lightningRod.get();
                        ModNetwork.sendToALL(new SThunderBoltPacket(vec3, new Vec3(blockPos.getX(), blockPos.getY(), blockPos.getZ()), colorUtil, 10));
                        serverLevel.playSound(null, this.getX(), this.getY(), this.getZ(), ModSounds.THUNDERBOLT.get(), this.getSoundSource(), 1.0F, 1.0F);
                    } else {
                        Vec3 vec31 = new Vec3(livingEntity.getX(), livingEntity.getY() + livingEntity.getBbHeight() / 2, livingEntity.getZ());
                        ModNetwork.sendToALL(new SThunderBoltPacket(vec3, vec31, colorUtil, 10));
                        if (livingEntity.hurt(ModDamageSource.indirectShock(this, this.getOwner()), damage)) {
                            float chance = this.isStaff() ? 0.25F : 0.05F;
                            float chainDamage = damage / 2.0F;
                            if (serverLevel.isThundering() && serverLevel.isRainingAt(livingEntity.blockPosition())){
                                chance += 0.25F;
                                chainDamage = damage;
                            }
                            if (serverLevel.getRandom().nextFloat() <= chance){
                                livingEntity.addEffect(new MobEffectInstance(GoetyEffects.SPASMS.get(), MathHelper.secondsToTicks(5)));
                            }
                            if (this.isStaff()){
                                WandUtil.chainLightning(livingEntity, this.getOwner() != null ? this.getOwner() : null, 6.0D, chainDamage);
                            }
                        }
                        serverLevel.playSound(null, this.getX(), this.getY(), this.getZ(), ModSounds.THUNDERBOLT.get(), this.getSoundSource(), 1.0F, 1.0F);
                    }
                }
            }
        }
    }

public static boolean canAttackRecruit(LivingEntity attacker, AbstractRecruitEntity targetRecruit) {
        if (attacker.equals(targetRecruit)) return false;

        if (attacker instanceof AbstractRecruitEntity attackerRecruit) {
            // Same player owner → never attack
            if (attackerRecruit.isOwned() && targetRecruit.isOwned() &&
                    attackerRecruit.getOwnerUUID().equals(targetRecruit.getOwnerUUID())) {
                return false;
            }

            // Same scoreboards team with friendly fire off → never attack
            if (attackerRecruit.getTeam() != null && targetRecruit.getTeam() != null &&
                    attackerRecruit.getTeam().equals(targetRecruit.getTeam()) &&
                    !attackerRecruit.getTeam().isAllowFriendlyFire()) {
                return false;
            }

            // Same patrol group (protectUUID points to same leader) → never attack
            if (attackerRecruit.getProtectUUID() != null &&
                    attackerRecruit.getProtectUUID().equals(targetRecruit.getProtectUUID())) {
                return false;
            }

            // Same RecruitsGroup UUID → never attack (covers NPC patrol units with no owner/team)
            if (attackerRecruit.getGroup() != null &&
                    attackerRecruit.getGroup().equals(targetRecruit.getGroup())) {
                return false;
            }

            if(targetRecruit instanceof MessengerEntity messenger && messenger.isAtMission()) return false;
        }

        return canHarmTeam(attacker, targetRecruit);
    }

public static boolean canAttackPlayer(LivingEntity attacker, Player player) {
        if (attacker instanceof AbstractRecruitEntity recruit) {
            if(player.getUUID().equals(recruit.getOwnerUUID())
                    || player.getUUID().equals(recruit.getProtectUUID())
                    || player.isCreative()
                    || player.isSpectator()
            )
                return false;
        }
        return canHarmTeam(attacker, player);
    }

public static boolean canAttackAnimal(LivingEntity attacker, Animal animal) {
        if (attacker instanceof AbstractRecruitEntity recruit ){
            if(recruit.getVehicle() != null && recruit.getVehicle().getUUID().equals(animal.getUUID())) return false;

            if (recruit.getProtectUUID() != null && recruit.getProtectUUID().equals(recruit.getProtectUUID())) return false;

            if(animal.isVehicle()){
                if(animal.getFirstPassenger() instanceof AbstractRecruitEntity targetRecruit) return canAttackRecruit(attacker, targetRecruit);
                if(animal.getFirstPassenger() instanceof Player playerTarget) return canAttackPlayer(attacker, playerTarget);
            }
        }
        return canHarmTeam(attacker, animal);
    }

public static boolean canHarmTeam(LivingEntity attacker, LivingEntity target) {
        Team attackerTeam = attacker.getTeam();
        Team targetTeam = target.getTeam();

        if (attackerTeam == null || targetTeam == null) return true;

        if (attackerTeam.equals(targetTeam) && !attackerTeam.isAllowFriendlyFire()) return false;

        if (isAlly(attackerTeam, targetTeam)) return false;

        if (FactionEvents.recruitsTreatyManager != null && FactionEvents.recruitsTreatyManager.hasTreaty(attackerTeam.getName(), targetTeam.getName())) {
            return false;
        }

        return true;
    }

@SubscribeEvent
    public void onLivingAttack(LivingAttackEvent event) {
        if(event.getEntity().getCommandSenderWorld().isClientSide()) return;

        Entity target = event.getEntity();
        Entity source = event.getSource().getEntity();

        if (!target.getCommandSenderWorld().isClientSide() && target instanceof LivingEntity livingTarget && source instanceof LivingEntity livingSource) {
            if (!canAttack(livingSource, livingTarget)){
                event.setCanceled(true);
            }
            else{
                handleSignificantDamage(livingSource, livingTarget, event.getAmount(), (ServerLevel) livingTarget.getCommandSenderWorld());
            }
        }
    }

@SubscribeEvent
    public void onProjectileImpact(ProjectileImpactEvent event) {
        Entity entity = event.getEntity();
        HitResult rayTrace = event.getRayTraceResult();

        if (canceledProjectiles.contains(entity)) {
            return;
        }

        if (!(entity instanceof Projectile projectile)) {
            return;
        }
        Entity owner = projectile.getOwner();

        if(owner == null) return;

        if (rayTrace.getType() != HitResult.Type.ENTITY) {
            return;
        }

        Entity impactEntity = ((EntityHitResult) rayTrace).getEntity();
        String encode = impactEntity.getEncodeId();
        if (encode != null && encode.contains("corpse:corpse")) {
            event.setImpactResult(ProjectileImpactEvent.ImpactResult.SKIP_ENTITY);
            return;
        }

        if (!(impactEntity instanceof LivingEntity impactLiving)) {
            return;
        }

        if (projectile instanceof AbstractArrow arrow && arrow.getPierceLevel() > 0) {

            if (owner instanceof LivingEntity livingOwner && !canAttack(livingOwner, impactLiving)) {
                event.setImpactResult(ProjectileImpactEvent.ImpactResult.SKIP_ENTITY);
                canceledProjectiles.add(projectile);
                return;
            }
        }

        if (owner instanceof AbstractRecruitEntity recruit) {

            if (impactLiving instanceof Animal animal) {
                Entity passenger = animal.getFirstPassenger();
                if (passenger instanceof AbstractRecruitEntity passengerRecruit) {
                    if (!canAttack(recruit, passengerRecruit)) {

                        event.setImpactResult(ProjectileImpactEvent.ImpactResult.SKIP_ENTITY);
                        return;
                    }
                }
                else if (passenger instanceof Player player) {
                    if (!canAttack(recruit, player)) {

                        event.setImpactResult(ProjectileImpactEvent.ImpactResult.SKIP_ENTITY);
                        return;
                    }
                }
            }

            if (!canAttack(recruit, impactLiving)) {
                event.setImpactResult(ProjectileImpactEvent.ImpactResult.SKIP_ENTITY);
                return;
            }
            else {
                recruit.addXp(2);
                recruit.checkLevel();
            }
        }

        if (owner instanceof AbstractIllager illager && !RecruitsServerConfig.PillagerFriendlyFire.get()) {
            if (illager.isAlliedTo(impactLiving)) {
                event.setImpactResult(ProjectileImpactEvent.ImpactResult.SKIP_ENTITY);
                canceledProjectiles.add(projectile);
                return;
            }
        }

        if (owner instanceof Player player) {
            if (!canHarmTeam(player, impactLiving)) {
                event.setImpactResult(ProjectileImpactEvent.ImpactResult.SKIP_ENTITY);
                return;
            }
        }
    }

@SubscribeEvent
    public void onLivingHurt(LivingHurtEvent event) {
        if(event.getEntity().getCommandSenderWorld().isClientSide()) return;

        if (Main.isMusketModLoaded) {
            Entity sourceEntity = event.getSource().getEntity();
            if (sourceEntity instanceof AbstractRecruitEntity owner && IWeapon.isMusketModWeapon(owner.getMainHandItem())) {
                Entity target = event.getEntity();
                if (target instanceof LivingEntity impactEntity) {

                    if (!canAttack(owner, impactEntity)) {
                        event.setCanceled(true);
                    } else {
                        owner.addXp(2);
                        owner.checkLevel();
                    }
                }
            }
        }

        Entity target = event.getEntity();
        Entity source = event.getSource().getEntity();
        if (source instanceof LivingEntity sourceEntity) {
            alertTeam(target, sourceEntity);
        }
    }

public static void alertTeam(Entity target, LivingEntity attacker) {
        if (target.getTeam() == null) return;

        target.getCommandSenderWorld().getEntitiesOfClass(
                AbstractRecruitEntity.class,
                target.getBoundingBox().inflate(32D),
                (recruit) -> recruit.getTarget() == null &&
                        recruit.getTeam() != null &&
                        recruit.getTeam().equals(target.getTeam())
        ).forEach((recruit) -> recruit.setTarget(attacker));
    }

public boolean shouldAttack(LivingEntity target) {
        return switch (this.getState()) {
            case 3 -> false; // Passive mode: never attack
            case 0 -> shouldAttackOnNeutral(target) && canAttack(target);
            case 1 -> (shouldAttackOnNeutral(target) || shouldAttackOnAggressive(target)) && canAttack(target);
            case 2 -> !RecruitEvents.isAlly(this.getTeam(), target.getTeam()) && canAttack(target);
            default -> canAttack(target);
        };
    }

private void searchForTargetsSync(ServerLevel serverLevel) {
        AABB searchBox = this.getBoundingBox().inflate(40);
        List<LivingEntity> nearby = serverLevel.getEntitiesOfClass(
                LivingEntity.class,
                searchBox,
                potTarget -> potTarget != this && targetingConditions.test(this, potTarget) && !AttackUtil.isTooDeepUnderwater(potTarget)
        );

        if (nearby.isEmpty()) return;

        nearby.sort(Comparator.comparingDouble(e -> e.distanceToSqr(this)));

        int pool = Math.min(10, nearby.size());
        LivingEntity target = nearby.get(this.getRandom().nextInt(pool));
        this.setTarget(target);
    }

public void tick() {
        super.tick();
        if(this.level().isClientSide()) return;

        this.collision.tick();

        if(despawnTimer > 0) despawnTimer--;
        if(despawnTimer == 0) recruitCheckDespawn();

        if(RecruitsServerConfig.RecruitsPayment.get()){
            if(paymentTimer > 0) paymentTimer--;
            if(paymentTimer == 0) {
                if(getUpkeepPos() != null || getUpkeepUUID() != null) forcedUpkeep = true;
                else checkPayment(this.getInventory());
            }
        }

        if(getMountTimer() > 0) setMountTimer(getMountTimer() - 1);
        if(getUpkeepTimer() > 0) setUpkeepTimer(getUpkeepTimer() - 1);
        if(remountAfterUpkeep && (this.tickCount + this.getId()) % 20 == 0 && !needsToGetFood()) tryRemountAfterUpkeep();
        // a Small Ships ground cannon pulls everyone touching it into its barrel - recruits are never its ammo
        if(this.getVehicle() != null && GroundCannon.isGroundCannon(this.getVehicle())) GroundCannon.handleRecruitInBarrel(this, this.getVehicle());
        if(getHunger() >=  70F && getHealth() < getMaxHealth()){
            this.heal(1.0F/50F);// 1 hp in 2.5s
        }

        if(this.reachedMovePos){
            this.setFollowState(2);
            this.reachedMovePos = false;
        }

        if(this.attackCooldown > 0) this.attackCooldown--;


        if(this.isAlive() && this.getState() != 3 && (this.tickCount + getTickPhase()) % getTargetSearchInterval() == 0){
            this.searchForTargets();
        }

        LivingEntity currentTarget = this.getTarget();
        if(currentTarget != null && (currentTarget.isDeadOrDying() || currentTarget.isRemoved())) this.setTarget(null);

        else if(currentTarget != null && (this.tickCount + getTickPhase()) % 10 == 0 && AttackUtil.isTooDeepUnderwater(currentTarget)){
            // the target dove deeper than allowed after it was acquired
            this.setTarget(null);
        }
            // Option 2 safety net: drop a target that is no longer visible, covering the case where a
            // recruit saw an enemy but lost sight before any attack/move goal took over (e.g. target
            // stepped behind cover while still out of melee range). Throttled so that, in the worst
            // case where no goal queried line of sight this tick, we don't run a raycast every tick per
            // recruit. EntitySensing caches per tick, so when a goal already queried LoS this is free.
        else if(currentTarget != null && (this.tickCount + getTickPhase()) % 10 == 0 && !this.getSensing().hasLineOfSight(currentTarget)){
            this.setTarget(null);
        }

        // Handle face rotation command
        if(this.rotateTicks > 0) {
            if(this.getNavigation().isDone()) {
                this.setYRot(this.ownerRot);
                this.yRotO = this.ownerRot;
                this.rotateTicks--;
            }
        }

    }

public boolean hire(Player player, RecruitsGroup group, boolean message) {
        if (!this.getCommandSenderWorld().isClientSide()) {
            RecruitEvent.Hired hireEvent = new RecruitEvent.Hired(this, player);
            MinecraftForge.EVENT_BUS.post(hireEvent);
            if (hireEvent.isCanceled()) return false;
        }
        String name = this.getName().getString() + ": ";
        Team ownerTeam = player.getTeam();// player is the new owner
        String stringId = ownerTeam != null ? ownerTeam.getName() : "";
        if (!RecruitEvents.recruitsPlayerUnitManager.canPlayerRecruit(stringId, player.getUUID())) {

            player.sendSystemMessage(INFO_RECRUITING_MAX(name));
            return false;
        }
        else {
            this.makeHireSound();

            this.resetPaymentTimer();
            this.setOwnerUUID(Optional.of(player.getUUID()));
            this.setIsOwned(true);
            this.navigation.stop();
            this.setTarget(null);
            this.setFollowState(2);
            this.setAggroState(0);
            if(group != null) this.setGroupUUID(group.getUUID());
            this.despawnTimer = -1;

            if(!this.getCommandSenderWorld().isClientSide()){
                RecruitEvents.recruitsPlayerUnitManager.addRecruits(player.getUUID(), 1);

                if(group != null){
                    RecruitEvents.recruitsGroupsManager.addMember(group.getUUID(), this.getUUID(),  (ServerLevel) this.getCommandSenderWorld());
                    RecruitEvents.recruitsGroupsManager.broadCastGroupsToPlayer(player);
                }

                if(ownerTeam != null){
                    FactionEvents.addRecruitToTeam(this, ownerTeam, (ServerLevel) this.getCommandSenderWorld());
                }
            }

            if(message){
                int i = this.random.nextInt(4);
                switch (i) {
                    default -> {
                        player.sendSystemMessage(TEXT_RECRUITED1(name));
                    }
                    case 2 -> {
                        player.sendSystemMessage(TEXT_RECRUITED2(name));
                    }
                    case 3 -> {
                        player.sendSystemMessage(TEXT_RECRUITED3(name));
                    }
                }
            }
        }

        return true;
    }

public void disband(@Nullable Player player, boolean keepTeam, boolean increaseCost){
        if (!this.getCommandSenderWorld().isClientSide()) {
            RecruitEvent.Dismissed dismissEvent = new RecruitEvent.Dismissed(this, player, keepTeam);
            MinecraftForge.EVENT_BUS.post(dismissEvent);
            if (dismissEvent.isCanceled()) return;
        }
        String name = this.getName().getString();

        if(player != null){
            player.sendSystemMessage(TEXT_DISBAND(name));
        }

        this.setTarget(null);
        this.setIsOwned(false);

        if(increaseCost) this.recalculateCost();

        if(this.getCommandSenderWorld().isClientSide()) return;
        // garrison recruits are not counted for the player (Governor, Variante B)
        if(!this.isGarrison()) RecruitEvents.recruitsPlayerUnitManager.removeRecruits(this.getOwnerUUID(), 1);
        if(this.isGarrison()){
            this.setGarrisonClaim(null);
            this.setListen(true);
        }
        this.setOwnerUUID(Optional.empty());

        if (this.getTeam() != null && !keepTeam){
            FactionEvents.removeRecruitFromTeam(this, this.getTeam(), (ServerLevel) this.getCommandSenderWorld());
        }

        if(this.getGroup() != null){
            RecruitEvents.recruitsGroupsManager.removeMember(this.getGroup(), this.getUUID(), (ServerLevel) this.getCommandSenderWorld());
            this.setGroupUUID(null);
        }
    }

public void assignToPlayer(UUID newOwner, UUID newGroupUUID){
        RecruitsGroup currentGroup = RecruitEvents.recruitsGroupsManager.getGroup(this.getGroup());
        if(currentGroup != null){
            currentGroup.removeMember(this.getUUID());
        }

        this.setGroupUUID(newGroupUUID);
        RecruitsGroup newGroup = RecruitEvents.recruitsGroupsManager.getGroup(newGroupUUID);

        this.disband(null, false, false);

        this.setOwnerUUID(Optional.of(newOwner));

        if(getOwner() != null){
            this.hire(getOwner(), newGroup, true);
            this.setFollowState(1);
        }
    }

public void updateTeam(){
        if(this.isOwned() && !this.getCommandSenderWorld().isClientSide()){
            Player owner = getOwner();
            if(owner != null) {
                Team recruitTeam = this.getTeam();
                Team ownerTeam = owner.getTeam();

                if (ownerTeam == null) {
                    if(recruitTeam != null){
                        //Remove from current team because ownerTeam is null
                        FactionEvents.removeRecruitFromTeam(this, recruitTeam, (ServerLevel) this.getCommandSenderWorld());
                        FactionEvents.addNPCToData((ServerLevel) this.getCommandSenderWorld(), recruitTeam.getName(), -1 );
                    }
                    //recruit team is also null, so no do nothing
                    needsTeamUpdate = false;
                }
                else if(recruitTeam == null){
                    FactionEvents.addRecruitToTeam(this, ownerTeam, (ServerLevel) this.getCommandSenderWorld());
                    FactionEvents.addNPCToData((ServerLevel) this.getCommandSenderWorld(), ownerTeam.getName(), +1 );
                    needsTeamUpdate = false;
                }
                else if(recruitTeam == ownerTeam){
                    updateColor(ownerTeam.getName());
                    needsTeamUpdate = false;
                }
                else{
                    FactionEvents.removeRecruitFromTeam(this, recruitTeam, (ServerLevel) this.getCommandSenderWorld());
                    FactionEvents.addNPCToData((ServerLevel) this.getCommandSenderWorld(), recruitTeam.getName(), -1 );

                    FactionEvents.addRecruitToTeam(this, ownerTeam, (ServerLevel) this.getCommandSenderWorld());
                    FactionEvents.addNPCToData((ServerLevel) this.getCommandSenderWorld(), ownerTeam.getName(), +1 );
                    needsTeamUpdate = false;
                }
            }
        }
    }

public boolean isEffectedByCommand(UUID player_uuid, UUID group) {
        if (!this.isOwned() || !this.isAlive() || !this.getListen()) return false;
        if (this.isGarrison()) return false;

        if (!this.getOwnerUUID().equals(player_uuid)) return false;

        if (group == null) {
            return true;
        }

        return this.getGroup() != null && this.getGroup().equals(group);
    }

public void setAggroState(int state) {
        switch (state){
            case 0:
            case 3:
                setTarget(null);//wird nur 1x aufgerufen
                break;
            case 1:
                break;
            case 2:
                setFollowState(0);
                break;
        }
        entityData.set(STATE, state);
    }

public void setFollowState(int state){
        switch (state) {
            case 0,6 -> {
                setShouldFollow(false);
                setShouldHoldPos(false);
                setShouldProtect(false);
                setShouldMovePos(false);
            }
            case 1 -> {
                setShouldFollow(true);
                setShouldHoldPos(false);
                setShouldProtect(false);
                setShouldMovePos(false);
            }
            case 2 -> {
                setShouldFollow(false);
                setShouldHoldPos(true);
                clearHoldPos();
                setHoldPos(position());
                setShouldProtect(false);
                setShouldMovePos(false);
            }
            case 3 -> {
                setShouldFollow(false);
                setShouldHoldPos(true);
                setShouldProtect(false);
                setShouldMovePos(false);
            }
            case 4 -> {
                setShouldFollow(false);
                setShouldHoldPos(true);
                clearHoldPos();
                setHoldPos(this.getOwner().position());
                setShouldProtect(false);
                setShouldMovePos(false);
                state = 3;
            }
            case 5 -> {
                setShouldFollow(false);
                setShouldHoldPos(false);
                setShouldProtect(true);
                setShouldMovePos(false);
            }
        }

        this.entityData.set(FOLLOW_STATE, state);
    }

public void reactToHit(@Nullable Entity attacker) {
        if(this.getMorale() > 0) this.setMoral(this.getMorale() - 0.25F);

        if(attacker instanceof LivingEntity living && RecruitEvents.canAttack(this, living)){
            if(this.getFollowState() == 5){//Protecting
                List<AbstractRecruitEntity> list = this.getCommandSenderWorld().getEntitiesOfClass(AbstractRecruitEntity.class, this.getBoundingBox().inflate(32D));
                for(AbstractRecruitEntity recruit : list){
                    if (recruit.getUUID().equals(recruit.getProtectUUID()) && recruit.isAlive() && !recruit.equals(living)){
                        //Patrolleader
                        recruit.setTarget(living);
                    }
                }
            }


            if(this.getTarget() != null){
                double d1 = this.distanceToSqr(this.getTarget());
                double d2 = this.distanceToSqr(living);

                if(d2 < d1) this.setTarget(living);
            }
            else
                this.setTarget(living);

            if(this.getShouldProtect() && this.getProtectingMob() instanceof AbstractRecruitEntity patrolLeader){
                patrolLeader.setTarget(living);
            }
        }
    }

public boolean doHurtTarget(@NotNull Entity entity) {
        float f = (float)this.getAttributeValue(Attributes.ATTACK_DAMAGE);
        if (entity instanceof LivingEntity) {
            f += EnchantmentHelper.getDamageBonus(this.getMainHandItem(), ((LivingEntity)entity).getMobType());
        }

        int i = EnchantmentHelper.getFireAspect(this);
        if (i > 0) {
            entity.setSecondsOnFire(i * 4);
        }

        boolean flag = entity.hurt(this.damageSources().mobAttack(this), f);
        if (flag) {

            this.doEnchantDamageEffects(this, entity);
            this.setLastHurtMob(entity);
        }
        this.addXp(1);
        if(this.getHunger() > 0) this.setHunger(this.getHunger() - 0.1F);
        this.checkLevel();
        if(this.getMorale() < 100) this.setMoral(this.getMorale() + 0.25F);
        this.damageMainHandItem();
        return true;
    }

private boolean canAssign(ServerPlayer sender, AbstractRecruitEntity recruit) {
        if (recruit instanceof GovernorEntity) {
            sender.sendSystemMessage(Component.translatable("chat.recruits.governor.cannot_take_over", recruit.getName().getString()));
            return false;
        }
        boolean isOwner = sender.getUUID().equals(recruit.getOwnerUUID());
        if (isOwner) {
            if (recruit.isGarrison()) {
                sender.sendSystemMessage(Component.translatable("chat.recruits.governor.release_first", recruit.getName().getString()));
                return false;
            }
            return true;
        }

        String factionId = recruit.getTeam() != null ? recruit.getTeam().getName() : null;
        boolean isLeader = factionId != null && sender.getTeam() != null && factionId.equals(sender.getTeam().getName())
                && GovernorManager.isFactionLeader(factionId, sender.getUUID());
        if (!isLeader || !sender.getUUID().equals(this.newOwner)) return false;

        if (!RecruitEvents.recruitsPlayerUnitManager.canPlayerRecruit(factionId, sender.getUUID())) {
            sender.sendSystemMessage(Component.translatable("chat.recruits.governor.release_limit", recruit.getName().getString()));
            return false;
        }
        return true;
    }

protected void alertOthers() {
        double d0 = this.getFollowDistance();
        AABB axisalignedbb = AABB.unitCubeFromLowerCorner(this.recruit.position())
                .inflate(d0, 16.0D, d0);
        List<? extends AbstractRecruitEntity> list = this.recruit.getCommandSenderWorld()
                .getEntitiesOfClass(this.recruit.getClass(), axisalignedbb);

        for (AbstractRecruitEntity recruitToAlert : list) {
            if (this.recruit == recruitToAlert ||
                    recruitToAlert.getTarget() != null ||
                    this.recruit.getLastHurtByMob() == null ||
                    this.recruit.getLastHurtByMob() == null ||
                    recruitToAlert.getOwnerUUID() == null ||
                    !recruitToAlert.getOwnerUUID().equals(this.recruit.getOwnerUUID()) ||
                    recruitToAlert.isAlliedTo(this.recruit.getLastHurtByMob())) continue;

            boolean shouldIgnore = false;
            if (this.toIgnoreAlert != null) {
                for (Class<?> oclass : this.toIgnoreAlert) {
                    if (recruitToAlert.getClass() == oclass) {
                        shouldIgnore = true;
                        break;
                    }
                }
            }
            if (shouldIgnore) continue;

            this.alertOther(recruitToAlert, this.recruit.getLastHurtByMob());
        }
    }

public boolean canContinueToUse() {
        LivingEntity target = this.recruit.getTarget();
        if (target == null || !target.isAlive()) {
            return false;
        } else if (!this.recruit.getSensing().hasLineOfSight(target)) {
            // Option 2: drop the target when line of sight is lost so the recruit does not keep
            // it queued while behind cover. The move-towards goal is also LoS-gated, so once sight
            // is gone nothing chases; the next search re-acquires only if the target becomes
            // visible again.
            this.recruit.setTarget(null);
            return false;
        } else {
            boolean canAttackHoldPos = canAttackHoldPos();
            boolean needsToGetFood = recruit.needsToGetFood();
            boolean getShouldMount = recruit.getShouldMount();
            boolean getShouldMovePos = recruit.getShouldMovePos();
            return (!(target instanceof Player) || !target.isSpectator() && !((Player) target).isCreative()) && canAttackHoldPos && recruit.getState() != 3 && !needsToGetFood && !getShouldMount && !getShouldMovePos;
        }
    }

public void tick() {

        if(this.protectingMob != null) {

            boolean isClose = protectingMob.distanceTo(this.recruit) <= range;
            if(!isClose){
                if (--this.timeToRecalcPath <= 0) {
                    this.timeToRecalcPath = this.adjustedTickDelay(10);
                    recruit.getNavigation().moveTo(protectingMob, 1.15F);

                    if(this.recruit instanceof CaptainEntity captain && captain.getVehicle() instanceof Boat){
                        captain.setSailPos(this.protectingMob.getOnPos());
                    }
                }

                this.recruit.tryJumpOverTerrain();
            }
        }

        if (this.protectingMob == null || !protectingMob.isAlive()) {
            if(this.protectingMob != null && !protectingMob.isAlive()){
                if (recruit.getOwner() != null)recruit.getOwner().sendSystemMessage(TEXT_PROTECT_DIED(recruit.getName().getString()));
            }
            clear();
        }

        if(this.recruit.tickCount % 20 == 0){
            this.getProtecting();
            this.checkMounts();
        }
    }

public void tick() {
        if(target != null && target.isAlive()) {
            double distance = target.distanceToSqr(this.crossBowman);
            boolean isClose = distance <= 150;
            boolean isFar = distance >= 3500;
            boolean isTooFar = distance >= 4500;
            boolean inRange =  !isFar;
            boolean canSee = this.crossBowman.getSensing().hasLineOfSight(target);

            if (canSee) {
                ++this.seeTime;
            } else {
                this.seeTime = 0;
            }

            if(isTooFar){
                this.crossBowman.setTarget(null);
                this.stop();
                return;
            }

            // movement
            if (crossBowman.getShouldFollow() && crossBowman.getOwner() != null) {
                handleFollow(this.crossBowman.getOwner(), inRange, isFar);
            }
            else if(crossBowman.getShouldHoldPos() && crossBowman.getHoldPos() != null){
                handleHoldPos(crossBowman.getHoldPos(), inRange);
            }
            else {
                handleWander(inRange, isFar, isClose);
            }
        }

        //WEAPON HANDLING
        if(isWeaponInMainHand()) {
            if(crossBowman.getShouldStrategicFire() && target == null) {
                BlockPos pos = crossBowman.getStrategicFirePos();
                switch (state) {
                    case IDLE -> {
                        if (weapon.isLoaded(crossBowman.getMainHandItem())) {
                            if (pos != null) {
                                this.state = State.AIMING;
                            }
                        } else if(hasArrows()) this.state = State.RELOAD;
                    }

                    case RELOAD -> {
                        this.crossBowman.startUsingItem(InteractionHand.MAIN_HAND);

                        int i = this.crossBowman.getTicksUsingItem();
                        if (i >= weapon.getWeaponLoadTime()) {
                            this.crossBowman.releaseUsingItem();
                            this.crossBowman.playSound(this.weapon.getLoadSound(), 1.0F, 1.0F / (crossBowman.getRandom().nextFloat() * 0.4F + 0.8F));
                            CrossbowItem.setCharged(this.crossBowman.getMainHandItem(), true);

                            this.state = State.AIMING;
                        }
                    }

                    case AIMING -> {
                        if (pos != null) {
                            this.crossBowman.setAggressive(true);
                            this.crossBowman.getLookControl().setLookAt(pos.getX(), pos.getY(), pos.getZ());

                            if (++this.seeTime > weapon.getWeaponLoadTime()) {
                                this.state = State.SHOOT;
                                this.seeTime = 0;
                            }
                        }
                    }

                    case SHOOT -> {
                        if (pos != null) {
                            this.weapon.performRangedAttackIWeapon(this.crossBowman, pos.getX(), pos.getY(), pos.getZ(), weapon.getProjectileSpeed());
                            CrossbowItem.setCharged(this.crossBowman.getMainHandItem(), false);
                        }
                        this.state = State.IDLE; //RESUPPLY
                    }
                }
            }
            else {
                switch (state) {
                    case IDLE -> {
                        if (weapon.isLoaded(crossBowman.getMainHandItem())) {
                            if (target != null && target.isAlive()) {
                                this.state = State.AIMING;
                            }
                        } else if(hasArrows()) this.state = State.RELOAD;
                    }
                    case RELOAD -> {
                        this.crossBowman.startUsingItem(InteractionHand.MAIN_HAND);

                        int i = this.crossBowman.getTicksUsingItem();
                        if (i >= weapon.getWeaponLoadTime()) {
                            this.crossBowman.releaseUsingItem();
                            this.crossBowman.playSound(this.weapon.getLoadSound(), 1.0F, 1.0F / (crossBowman.getRandom().nextFloat() * 0.4F + 0.8F));
                            CrossbowItem.setCharged(this.crossBowman.getMainHandItem(), true);

                            this.state = State.AIMING;
                        }
                    }

                    case AIMING -> {
                        if (target != null && target.isAlive()) {
                            boolean canSee = this.crossBowman.getSensing().hasLineOfSight(target);
                            this.crossBowman.setAggressive(true);
                            this.crossBowman.getLookControl().setLookAt(target);

                            if (canSee) {
                                if (++this.seeTime >= weapon.getWeaponLoadTime()) {
                                    this.state = State.SHOOT;
                                    this.seeTime = 0;
                                }
                            } else if (crossBowman.getShouldHoldPos()) {
                                this.crossBowman.setTarget(null);
                            }
                        } else {
                            this.crossBowman.setAggressive(false);
                            seeTime = 0;
                        }
                    }

                    case SHOOT -> {
                        LivingEntity savedTarget = null;
                        if (target != null && target.isAlive() && this.crossBowman.canAttack(target) && this.crossBowman.getState() != 3) {
                            this.crossBowman.getLookControl().setLookAt(target);

                            if(AttackUtil.canPerformHorseAttack(this.crossBowman, target)){
                                if(target.getVehicle() instanceof LivingEntity) {
                                    savedTarget = target;
                                    target = (LivingEntity) target.getVehicle();
                                }
                            }

                            this.weapon.performRangedAttackIWeapon(this.crossBowman, target.getX(), target.getY() + target.getEyeHeight(), target.getZ(), weapon.getProjectileSpeed());

                            if(savedTarget != null){
                                target = savedTarget;
                            }

                            CrossbowItem.setCharged(this.crossBowman.getMainHandItem(), false);
                        }
                        this.state = State.IDLE;
                    }
                }
            }
        }
    }

public static void onAttackCommand(Player player, UUID player_uuid, List<AbstractRecruitEntity> list, UUID group) {
        HitResult hitResult = player.pick(100, 1F, false);
        BlockPos blockpos = null;
        AABB aabb = null;
        List<LivingEntity> targets = new ArrayList<>();
        if (hitResult.getType() == HitResult.Type.ENTITY){
            EntityHitResult entityHitResult = (EntityHitResult) hitResult;

            blockpos = entityHitResult.getEntity().getOnPos();
            if(entityHitResult.getEntity() instanceof LivingEntity living) targets.add(living);
        }
        else if (hitResult.getType() == HitResult.Type.BLOCK){
            BlockHitResult blockHitResult = (BlockHitResult) hitResult;
            blockpos = blockHitResult.getBlockPos();
        }
        else return;

        aabb = new AABB(blockpos).inflate(10);

        list.removeIf(recruit -> !recruit.isEffectedByCommand(player_uuid, group));

        List<LivingEntity> validTargets = player.getCommandSenderWorld()
                .getEntitiesOfClass(LivingEntity.class, aabb);

        if (list.isEmpty() || validTargets.isEmpty()) return;

        AbstractRecruitEntity firstRecruit = list.get(0);
        validTargets.removeIf(target -> !firstRecruit.canAttack(target));

        if (validTargets.isEmpty()) return;

        for (int i = 0; i < list.size(); i++) {
            AbstractRecruitEntity recruit = list.get(i);
            LivingEntity target = validTargets.get(i % validTargets.size());
            recruit.setTarget(target);
            recruit.setHoldPos(getEngageHoldPos(recruit, target));
            recruit.setFollowState(3);
        }
    }

public void attackAI(){
        if (!this.level.isClientSide) {
            if (this.fireCooldown > 0){
                --this.fireCooldown;
            }
            if (this.fireTick > 10) {
                ++this.fireTick;
            }
            if (this.fireTick > 54){
                this.fireCooldown = 80;
                this.fireTick = 0;
                if (this.isFiring()){
                    this.stopFiring();
                }
            }
            if (this.getTarget() != null) {
                if (!this.isFiring()){
                    this.getLookControl().setLookAt(this.getTarget(), 100.0F, this.getMaxHeadXRot());
                }
                if (this.getSensing().hasLineOfSight(this.getTarget())) {
                    if (!this.isBreathing()) {
                        if ((this.fireCooldown <= 0 && !this.isTeleporting()
                                && this.getTarget().distanceToSqr(this) < Mth.square(this.attackRange())) || this.isFiring()) {
                            if (this.fireTick <= 10){
                                ++this.fireTick;
                            }
                            if (this.isFiring()){
                                this.getNavigation().stop();
                                double d2 = this.getTarget().getX() - this.getX();
                                double d1 = this.getTarget().getZ() - this.getZ();
                                this.setYRot(-((float) Mth.atan2(d2, d1)) * (180F / (float) Math.PI));
                                this.yBodyRot = this.getYRot();
                            }
                            if (this.fireTick > 10) {
                                this.startFiring();
                                this.getNavigation().stop();
                            } else {
                                this.movement();
                                this.stopFiring();
                            }
                            if (this.fireTick == 20) {
                                this.magicFire(this.getTarget());
                            }
                        } else {
                            if (this.fireTick <= 10) {
                                this.fireTick = 0;
                            }
                            this.stopFiring();
                            this.movement();
                        }
                    } else {
                        this.getNavigation().stop();
                        this.fireCooldown = 100;
                        this.fireTick = 0;
                        ++this.breathTick;
                        if (this.initial != null) {
                            this.lookAt(EntityAnchorArgument.Anchor.EYES, this.initial);
                        }
                        this.setYRot(this.yHeadRot);
                        if (this.breathTick >= 20) {
                            Vec3 vector3d = new Vec3(this.getTarget().getX() - this.initial.x, (this.getTarget().getY() + this.getTarget().getEyeHeight()) - this.initial.y, this.getTarget().getZ() - this.initial.z);
                            vector3d = vector3d.normalize();
                            double speed = 0.25D;

                            this.initial = this.initial.add(vector3d.x * speed, vector3d.y * speed, vector3d.z * speed);

                            this.level.broadcastEntityEvent(this, (byte) 10);
                            Entity entity = MobUtil.getSingleTarget(this.level, this, 8, 3.0F);
                            if (entity != null) {
                                this.doBreathing(entity);
                                this.gameEvent(GameEvent.PROJECTILE_SHOOT);
                            }
                        } else {
                            this.initial = new Vec3(this.getTarget().getX(), this.getTarget().getEyeY(), this.getTarget().getZ());
                        }
                        if (this.breathTick >= MathHelper.secondsToTicks(3.5F) || this.hurtStop()){
                            this.stopBreathing();
                        }
                    }
                }
            } else {
                if (this.fireTick <= 10) {
                    this.fireTick = 0;
                }
                this.stopBreathing();
            }
        }
    }

public void attackGoal(){
        this.goalSelector.addGoal(4, new ModMeleeAttackGoal(this, 1.0D, true){

            @Override
            public boolean canUse() {
                return super.canUse() && this.mob instanceof AbstractBroodMother broodMother && !broodMother.isCircling;
            }

            @Override
            public boolean canContinueToUse() {
                return super.canContinueToUse() && this.mob instanceof AbstractBroodMother broodMother && !broodMother.isCircling;
            }

            protected void checkAndPerformAttack(LivingEntity livingEntity, double distToEnemySqr) {
                double d0 = this.getAttackReachSqr(livingEntity);
                this.mob.getLookControl().setLookAt(livingEntity, 100.0F, 100.0F);
                if (distToEnemySqr <= d0 && this.isTimeToAttack()) {
                    int i = 0;
                    float angle = 2.0F;
                    double radius = 2.0D;
                    double extraX = this.mob.getX() + 0.8D * Math.sin((double)(-this.mob.getYRot()) * Math.PI / 180.0D) + (double)angle * Math.sin((double)(-this.mob.yHeadRot) * Math.PI / 180.0D) * Math.cos((double)(-this.mob.getXRot()) * Math.PI / 180.0D);
                    double extraZ = this.mob.getZ() + 0.8D * Math.cos((double)(-this.mob.getYRot()) * Math.PI / 180.0D) + (double)angle * Math.cos((double)(-this.mob.yHeadRot) * Math.PI / 180.0D) * Math.cos((double)(-this.mob.getXRot()) * Math.PI / 180.0D);
                    List<LivingEntity> list = this.mob.level.getEntitiesOfClass(LivingEntity.class, new AABB(extraX - radius, this.mob.getY(), extraZ - radius, extraX + radius, this.mob.getY() + radius, extraZ + radius));
                    for (LivingEntity target : list) {
                        if (EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(target) && !MobUtil.areAllies(this.mob, target)) {
                            if (this.mob.doHurtTarget(target) || target.isBlocking()) {
                                ++i;
                            }
                        }
                    }
                    if (i > 0) {
                        this.mob.swing(InteractionHand.MAIN_HAND);
