                    }
                    this.resetAttackCooldown();
                }

            }

            @Override
            protected double getAttackReachSqr(LivingEntity target) {
                return this.mob.getBbWidth() * 1.25D * this.mob.getBbWidth() * 1.25D + target.getBbWidth();
