public void tick(){
        super.tick();
        this.setYRot(this.getYRot() + 1);
        this.setXRot(0);
        prevOpenProgress = openProgress;
        if(this.isInWaterOrBubble() || this.isInLava()){
            this.setPos(this.position().add(0, 0.08, 0));
        }
        if(this.entityData.get(OPENED) && openProgress < 1F){
            openProgress += 0.1F;
        }
        if(!this.entityData.get(OPENED) && openProgress > 0F){
            openProgress -= 0.1F;
        }
        if(random.nextFloat() < 0.4F){
            this.level().addParticle(ParticleTypes.PORTAL, this.getRandomX(0.5D), this.getRandomY() - 0.25D, this.getRandomZ(0.5D), (this.random.nextDouble() - 0.5D) * 2.0D, -this.random.nextDouble(), (this.random.nextDouble() - 0.5D) * 2.0D);
        }
        if(this.getY() < level().getMinBuildHeight()){
            this.setPos(this.getX(), level().getMinBuildHeight() + 1.2F, this.getZ());
        }
        if(this.entityData.get(OPENED) && openProgress >= 1F && !this.isFinished()){
            if(!level().isClientSide){
                EntityType type = ForgeRegistries.ENTITY_TYPES.getValue(new ResourceLocation(this.getContainedEntityType()));
                if(type != null){
                    Entity entity = type.create(level());
                    if(entity instanceof LivingEntity alive){
                        alive.readAdditionalSaveData(this.getContainedData());
                        alive.setHealth(Math.max(2, alive.getMaxHealth() * 0.25F));
                        alive.setYRot(random.nextFloat() * 360 - 180);
                        alive.copyPosition(this);
                        level().addFreshEntity(alive);
                    }
                    this.entityData.set(FINISHED, true);
                    this.entityData.set(OPENED, false);
                }
            }
        }
        if(this.isFinished() && openProgress <= 0.01F){
            this.discard();
        }
    }

@Override
    public void tick() {
        super.tick();
        Entity creator = getCreatorEntity();
        Entity current = getToEntity();
        if (creator instanceof LivingEntity) {
            if (current != null) {
                this.setPos(new Vec3(current.getX(), current.getY() + current.getBbHeight() * 0.5F, current.getZ()));
                if(!level().isClientSide){
                    if(!hasShocked){
                        hasShocked = true;
                        current.hurt(current.damageSources().lightningBolt(), 3);
                    }
                }
            }
        }
        if(!level().isClientSide){
            if(!hasChained){
                if(this.getChainsLeft() > 0 && creator instanceof LivingEntity) {
                    Entity closestValid = null;
                    for (Entity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(8.0D))) {
                        if (!entity.equals(creator) && !TameableUtils.hasSameOwnerAs((LivingEntity) creator, entity) && !previouslyShocked.contains(entity) && !creator.isAlliedTo(entity) && entity instanceof Mob && this.hasLineOfSight(entity)) {
                            if (closestValid == null || this.distanceTo(entity) < this.distanceTo(closestValid)) {
                                closestValid = entity;
                            }
                        }
                    }
                    if(closestValid != null){
                        createLightningAt(closestValid);
                        hasChained = true;
                    }
                }
            }
            if(getDiesInTicks() > 0){
                this.setDiesInTicks(getDiesInTicks() - 1);
            }else{
                this.remove(RemovalReason.DISCARDED);
            }
        }
    }

private void createLightningAt(Entity closestValid) {
        ChainLightningEntity child = DIEntityRegistry.CHAIN_LIGHTNING.get().create(this.level());
        child.previouslyShocked = new ArrayList<>(previouslyShocked);
        child.previouslyShocked.add(closestValid);
        child.setCreatorEntityID(this.getCreatorEntityID());
        child.setFromEntityID(this.getId());
        child.setToEntityID(closestValid.getId());
        child.copyPosition(closestValid);
        child.setChainsLeft(this.getChainsLeft() - 1);
        this.level().addFreshEntity(child);
    }

public void tick() {
        super.tick();
        if (this.tickCount <= 10 || this.getLifespan() <= 10) {
            this.setBoundingBox(this.makeBoundingBox());
        } else {
            if (soundLoop % 15 == 0) {
                this.playSound(DISoundRegistry.PSYCHIC_WALL.get(), 1, random.nextFloat() * 0.3F + 0.9F);
            }
            soundLoop++;
        }
        if (!this.level().isClientSide && this.getCreatorId() != null) {
            Entity creator = this.getCreator();
            if (creator != null) {
                this.entityData.set(CREATOR_ID, creator.getId());
                if (!creator.isAlive() && this.getLifespan() > 20) {
                    this.setLifespan(20);
                }
            }
        }
        this.setDeltaMovement(Vec3.ZERO);
        float wX = Math.abs(this.getWallDirection().getStepX());
        float wY = Math.abs(this.getWallDirection().getStepY());
        float wZ = Math.abs(this.getWallDirection().getStepZ());
        AABB collisionAABB = this.getBoundingBox().inflate(wX * 0.25F, wY * 0.25F, wZ * 0.25F);
        List<Entity> colliders = level().getEntities(this, collisionAABB);
        float backISay = this.getWallDirection().getAxis() == Direction.Axis.Y ? -0.6F : -0.1F;
        for (Entity collider : colliders) {
            if (!isSameTeam(collider)) {
                collider.push(getWallDirection().getStepX() * 0.25F, getWallDirection().getStepY() * 0.25F, getWallDirection().getStepZ() * 0.25F);
                if (!deflectedEntities.containsKey(collider.getUUID())) {
                    boolean flag = true;
                    if (collider instanceof Projectile) {
                        if (isFiredByAlly((Projectile) collider)) {
                            flag = false;
                        } else {
                            collider.setDeltaMovement(collider.getDeltaMovement().scale(backISay));
                            collider.setYRot(collider.getYRot() + 180);
                            collider.setXRot(collider.getXRot() + 180);
                        }
                    }
                    if (flag) {
                        deflectedEntities.put(collider.getUUID(), 15);
                        if (level().isClientSide && collider.getBoundingBox().intersects(collisionAABB)) {
                            Vec3 vec3 = new Vec3(collider.getX(), collider.getY(0.5F), collider.getZ());
                            Vec3 vec31 = collisionAABB.getCenter();
                            Vec3 vec32;
                            EntityHitResult entityhitresult = ProjectileUtil.getEntityHitResult(collider, vec3, vec31, collisionAABB, (entity) -> {
                                return entity == this;
                            }, collider.distanceTo(this));
                            if (entityhitresult == null || entityhitresult.getType() == HitResult.Type.MISS) {
                                vec32 = vec3;
                            } else {
                                vec32 = entityhitresult.getLocation();
                            }
                            level().addParticle(DIParticleRegistry.PSYCHIC_WALL.get(), vec32.x, vec32.y, vec32.z, this.getWallDirection().get3DDataValue(), 0, 0);
                            this.playSound(DISoundRegistry.PSYCHIC_WALL_DEFLECT.get(), 1, random.nextFloat() * 0.3F + 0.9F);
                        }
                    }
                }
            }
        }
        if (!deflectedEntities.isEmpty()) {
            for (UUID uuid : deflectedEntities.keySet()) {
                deflectedEntities.put(uuid, deflectedEntities.get(uuid) - 1);
            }
            deflectedEntities.entrySet().removeIf(e -> e.getValue() <= 0);
        }
        if (getLifespan() <= 0) {
            this.discard();
        } else {
            this.setLifespan(this.getLifespan() - 1);
        }
    }

protected void tick(ServerLevel p_23503_, T axolotl, long gameTime) {
