        Brain<Axolotl> brain = axolotl.getBrain();
        Activity activity = brain.getActiveNonCoreActivity().orElse(null);
        if (activity != Activity.PLAY_DEAD && !axolotl.isPlayingDead() && axolotl instanceof ModifedToBeTameable modifedToBeTameable) {
            if (modifedToBeTameable.isStayingStill()) {
                brain.setActiveActivityIfPossible(DIActivityRegistry.AXOLOTL_STAY.get());
                ci.cancel();
            } else if (modifedToBeTameable.isFollowingOwner()) {
                brain.setActiveActivityToFirstValid(ImmutableList.of(Activity.PLAY_DEAD, Activity.FIGHT, DIActivityRegistry.AXOLOTL_FOLLOW.get()));
                ci.cancel();
            }
        }
    }

public void removeUntamedGoals(){
        try {
            this.goalSelector.getAvailableGoals().stream().filter((wrapped) -> {
                return wrapped.getGoal() instanceof AvoidEntityGoal;
            }).filter(WrappedGoal::isRunning).forEach(WrappedGoal::stop);
            this.goalSelector.getAvailableGoals().removeIf((wrapped) -> {
                return wrapped.getGoal() instanceof AvoidEntityGoal;
            });
            this.targetSelector.getAvailableGoals().removeIf((wrapped) -> {
                return wrapped.getGoal() instanceof NearestAttackableTargetGoal;
            });
        } catch (Exception e){
            DomesticationMod.LOGGER.warn("encountered error modifying rabbit AI");
        }
    }

@Inject(
            at = {@At("HEAD")},
            remap = true,
            method = {"Lnet/minecraft/world/entity/animal/Rabbit;setVariant(Lnet/minecraft/world/entity/animal/Rabbit$Variant;)V"},
            cancellable = true
    )
    private void di_setRabbitType(Rabbit.Variant type, CallbackInfo ci) {
        ci.cancel();
        if(type == Rabbit.Variant.EVIL){
            this.getAttribute(Attributes.MAX_HEALTH).setBaseValue(30.0D);
            this.getAttribute(Attributes.ARMOR).setBaseValue(8.0D);
            this.heal(22.0F);
            this.goalSelector.addGoal(4, new RabbitMeleeGoal(this));
            this.targetSelector.addGoal(1, (new HurtByTargetGoal(this)).setAlertOthers());
            if(!this.isTame()){
                this.targetSelector.addGoal(2, new NearestAttackableTargetGoal<>(this, Player.class, true));
                this.targetSelector.addGoal(3, new NearestAttackableTargetGoal<>(this, Wolf.class, true));
            }else{
                this.targetSelector.addGoal(2, new OwnerHurtTarget2Goal(this));
                this.targetSelector.addGoal(3, new OwnerHurtByTarget2Goal(this));
                removeUntamedGoals();
            }
            if (!this.hasCustomName()) {
                this.setCustomName(Component.translatable(Util.makeDescriptionId("entity", new ResourceLocation("killer_bunny"))));
            }
        }
        this.entityData.set(DATA_TYPE_ID, type.id());
    }

@Inject(
            method = {"Lnet/minecraft/world/entity/animal/frog/ShootTongue;eatEntity(Lnet/minecraft/server/level/ServerLevel;Lnet/minecraft/world/entity/animal/frog/Frog;)V"},
            remap = true,
            at = @At("HEAD"),
            cancellable = true
    )
    private void di_eatEntity(ServerLevel level, Frog frog, CallbackInfo ci) {
        if(frog instanceof ModifedToBeTameable tameable && tameable.isTame()){
            ci.cancel();
            frog.playSound(SoundEvents.FROG_TONGUE);
            Optional<Entity> optional = frog.getTongueTarget();
            if (optional.isPresent()) {
                Entity entity = optional.get();
                if (entity.isAlive()) {
                    frog.doHurtTarget(entity);
                    if (!entity.isAlive() && Frog.canEat(frog)) {
                        entity.remove(Entity.RemovalReason.KILLED);
                    }
                }
            }

        }

    }

